INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('ce19afeb-d20b-5085-a97f-91b2a40e9464', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 7, 7, 'always learning, and never able to come to the knowledge of the truth.'),
  ('7de0efc3-3374-571d-a187-07f49821b202', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 8, 8, 'Even as Jannes and Jambres opposed Moses, so do these also oppose the truth; men corrupted in mind, who concerning the faith, are rejected.'),
  ('5be729de-2628-50a8-ada5-43ac52f1a9e8', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 9, 9, 'But they will proceed no further. For their folly will be evident to all men, as theirs also came to be.'),
  ('57b17e90-0ccd-557d-a111-6533464e9f1d', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 10, 10, 'But you did follow my teaching, conduct, purpose, faith, patience, love, steadfastness,'),
  ('14383e48-d15a-5f58-a834-0881ef300812', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 11, 11, 'persecutions, and sufferings: those things that happened to me at Antioch, Iconium, and Lystra. I endured those persecutions. Out of them all the Lord delivered me.'),
  ('578ae122-688e-552e-a1f9-a563d404d2ea', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 12, 12, 'Yes, and all who desire to live godly in Christ Jesus will suffer persecution.'),
  ('3da36a76-b4bf-53f6-ae0b-3b8eea27c5ee', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 13, 13, 'But evil men and impostors will grow worse and worse, deceiving and being deceived.'),
  ('aa354af6-046a-51c1-a334-c52499f49e4a', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 14, 14, 'But you remain in the things which you have learned and have been assured of, knowing from whom you have learned them.'),
  ('06a01cec-6d7c-5e2b-aa78-a20accf24271', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 15, 15, 'From infancy, you have known the holy Scriptures which are able to make you wise for salvation through faith, which is in Christ Jesus.'),
  ('fd4860d5-7222-5c30-a055-d5ce4c4f7d37', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 16, 16, 'Every Scripture is God-breathed and profitable for teaching, for reproof, for correction, and for instruction in righteousness,'),
  ('d99a05b5-176e-5b1a-acd3-8d4c80c289f3', '2e15d3e1-b2a5-50f8-ab9a-5d0a724a8cfb', NULL, 17, 17, 'that the man of God may be complete, thoroughly equipped for every good work.'),
  ('e05252b0-5bba-537a-a0bd-0a86903cc25e', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 1, 1, 'I command you therefore before God and the Lord Jesus Christ, who will judge the living and the dead at his appearing and his Kingdom:'),
  ('9d642978-0bd9-53f7-af4e-4621583f212f', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 2, 2, 'preach the word; be urgent in season and out of season; reprove, rebuke, and exhort, with all patience and teaching.'),
  ('713de73e-7c1f-577d-a952-432eb7a78048', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 3, 3, 'For the time will come when they will not listen to the sound doctrine, but, having itching ears, will heap up for themselves teachers after their own lusts;'),
  ('a3360673-6f01-5e55-ae68-f332f7b79097', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 4, 4, 'and will turn away their ears from the truth, and turn aside to fables.'),
  ('899634fa-7484-53d6-aef3-0f90d7d0fcb6', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 5, 5, 'But you be sober in all things, suffer hardship, do the work of an evangelist, and fulfill your ministry.'),
  ('76ae245b-77ed-5306-a473-1e2907ead792', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 6, 6, 'For I am already being offered, and the time of my departure has come.'),
  ('51bea3da-8c44-516f-a9f6-6b7a9febed4a', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 7, 7, 'I have fought the good fight. I have finished the course. I have kept the faith.'),
  ('13752eca-c8e6-522f-a3d1-254e1a7cf384', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 8, 8, 'From now on, there is stored up for me the crown of righteousness, which the Lord, the righteous judge, will give to me on that day; and not to me only, but also to all those who have loved his appearing.'),
  ('412857a6-e859-5e89-ae68-fea79aa516ef', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 9, 9, 'Be diligent to come to me soon,'),
  ('ec13e3a2-7eef-5b16-a525-6d0dabc09cb8', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 10, 10, 'for Demas left me, having loved this present world, and went to Thessalonica; Crescens to Galatia, and Titus to Dalmatia.'),
  ('eee973f1-ed5c-5fd0-a281-c29a1628c30b', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 11, 11, 'Only Luke is with me. Take Mark, and bring him with you, for he is useful to me for service.'),
  ('e1d24877-9eb8-524c-a7b1-2b32cc780515', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 12, 12, 'But I sent Tychicus to Ephesus.'),
  ('5892b1ae-8d48-59f8-aafa-4454bc80b1ae', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 13, 13, 'Bring the cloak that I left at Troas with Carpus when you come, and the books, especially the parchments.'),
  ('fe10e9a5-761d-53b4-ab61-fb38e9804d24', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 14, 14, 'Alexander, the coppersmith, did much evil to me. The Lord will repay him according to his works,'),
  ('df8f6d65-4852-5e1e-a418-edeb4ef681b0', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 15, 15, 'of whom you also must beware; for he greatly opposed our words.'),
  ('d6483356-ae53-50b7-a9b1-0e9859735725', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 16, 16, 'At my first defense, no one came to help me, but all left me. May it not be held against them.'),
  ('fb617774-7943-5386-a725-2730c3bb0b90', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 17, 17, 'But the Lord stood by me, and strengthened me, that through me the message might be fully proclaimed, and that all the Gentiles might hear; and I was delivered out of the mouth of the lion.'),
  ('350581a9-f405-5a5f-a5b2-33ce33e04902', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 18, 18, 'And the Lord will deliver me from every evil work, and will preserve me for his heavenly Kingdom; to whom be the glory forever and ever. Amen.'),
  ('86183337-3a60-5cc1-a369-2a588f85fdf0', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 19, 19, 'Greet Prisca and Aquila, and the house of Onesiphorus.'),
  ('a318910b-5ea2-53dd-a5b6-1acd5f5a9d06', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 20, 20, 'Erastus remained at Corinth, but I left Trophimus at Miletus sick.'),
  ('645372a5-cb3b-5f38-afb6-f4b6c7bc3aa7', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 21, 21, 'Be diligent to come before winter. Eubulus salutes you, as do Pudens, Linus, Claudia, and all the brothers.'),
  ('e8b724d4-1ee0-5bbe-a1c4-ac90391326b4', 'a5d8e471-f62d-54e0-a05f-f45b9354e9a7', NULL, 22, 22, 'The Lord Jesus Christ be with your spirit. Grace be with you. Amen.'),
  ('bb0bc1db-6999-58f3-aa49-962751048897', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 1, 1, 'Paul, a servant of God, and an apostle of Jesus Christ, according to the faith of God''s chosen ones, and the knowledge of the truth which is according to godliness,'),
  ('86a6d317-2060-593b-abff-c9463b708cf9', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 2, 2, 'in hope of eternal life, which God, who can''t lie, promised before time began;'),
  ('87d1ed4b-34cf-5ecc-a74a-1f0b3355ffba', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 3, 3, 'but in his own time revealed his word in the message with which I was entrusted according to the commandment of God our Savior;'),
  ('ce211d4e-9558-5b8f-a83d-7db50206b7d1', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 4, 4, 'to Titus, my true child according to a common faith: Grace, mercy, and peace from God the Father and the Lord Jesus Christ our Savior.'),
  ('858ad9ea-714a-54d7-a6ac-277159641df5', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 5, 5, 'I left you in Crete for this reason, that you would set in order the things that were lacking, and appoint elders in every city, as I directed you;'),
  ('123cfc20-ed76-5708-a34c-73195f7a8cba', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 6, 6, 'if anyone is blameless, the husband of one wife, having children who believe, who are not accused of loose or unruly behavior.'),
  ('cd90bc69-e20b-5e74-a935-728280d98563', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 7, 7, 'For the overseer must be blameless, as God''s steward; not self-pleasing, not easily angered, not given to wine, not violent, not greedy for dishonest gain;'),
  ('bed86abd-7cbc-5a3d-a08d-b642848ec1e4', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 8, 8, 'but given to hospitality, a lover of good, sober minded, fair, holy, self-controlled;'),
  ('80184699-f848-597a-ab3b-ca6b2f7ddb53', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 9, 9, 'holding to the faithful word which is according to the teaching, that he may be able to exhort in the sound doctrine, and to convict those who contradict him.'),
  ('0ce21314-eee7-5273-ad60-849f9003eb93', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 10, 10, 'For there are also many unruly men, vain talkers and deceivers, especially those of the circumcision,'),
  ('dbafe36d-e5e5-58b5-af9f-33840833ee3f', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 11, 11, 'whose mouths must be stopped; men who overthrow whole houses, teaching things which they ought not, for dishonest gain''s sake.'),
  ('1addd95a-a413-5562-a61f-d47e48bf1155', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 12, 12, 'One of them, a prophet of their own, said, "Cretans are always liars, evil beasts, and idle gluttons."'),
  ('09a527a5-e34d-5074-a483-511eadf0a181', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 13, 13, 'This testimony is true. For this cause, reprove them sharply, that they may be sound in the faith,'),
  ('fe6df9a8-abe1-54ad-a832-40709714116f', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 14, 14, 'not paying attention to Jewish fables and commandments of men who turn away from the truth.'),
  ('87ce43a2-5e12-5d2f-a7aa-99607e7bfe40', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 15, 15, 'To the pure, all things are pure; but to those who are defiled and unbelieving, nothing is pure; but both their mind and their conscience are defiled.'),
  ('bce057a2-4dfb-5d43-a04b-575d7aa75740', '42a747f5-6cd5-55af-ad7a-c209caad8c10', NULL, 16, 16, 'They profess that they know God, but by their works they deny him, being abominable, disobedient, and unfit for any good work.'),
  ('ff90fc79-ec32-56bf-ab66-8c41d6aff4b0', '78e9e1cc-3e0f-530a-a571-6ba4f2c8ba12', NULL, 1, 1, 'But say the things which fit sound doctrine,'),
  ('ece895da-9c3e-59ec-a351-3b4ae986cd72', '78e9e1cc-3e0f-530a-a571-6ba4f2c8ba12', NULL, 2, 2, 'that older men should be temperate, sensible, sober minded, sound in faith, in love, and in patience:'),
  ('4acdf9fa-1617-5d94-af84-a290387b476a', '78e9e1cc-3e0f-530a-a571-6ba4f2c8ba12', NULL, 3, 3, 'and that older women likewise be reverent in behavior, not slanderers nor enslaved to much wine, teachers of that which is good;'),
  ('6b70d906-8014-53b8-a395-3b3318f28736', '78e9e1cc-3e0f-530a-a571-6ba4f2c8ba12', NULL, 4, 4, 'that they may train the young women to love their husbands, to love their children,'),
  ('e55d5e8c-7938-5491-a329-f81e80523a9f', '78e9e1cc-3e0f-530a-a571-6ba4f2c8ba12', NULL, 5, 5, 'to be sober minded, chaste, workers at home, kind, being in subjection to their own husbands, that God''s word may not be blasphemed.'),
  ('9f33c054-4c21-5d34-ae1b-1a8344df81b7', '78e9e1cc-3e0f-530a-a571-6ba4f2c8ba12', NULL, 6, 6, 'Likewise, exhort the younger men to be sober minded;'),
  ('13808c8c-10c9-5681-ab09-deff89993612', '78e9e1cc-3e0f-530a-a571-6ba4f2c8ba12', NULL, 7, 7, 'in all things showing yourself an example of good works; in your teaching showing integrity, seriousness, incorruptibility,'),
  ('27e85147-1a4e-5c62-ad51-f29ac893332f', '78e9e1cc-3e0f-530a-a571-6ba4f2c8ba12', NULL, 8, 8, 'and soundness of speech that can''t be condemned; that he who opposes you may be ashamed, having no evil thing to say about us.'),
  ('eb1e9af3-8775-547f-a3a8-bb4d4c3be591', '78e9e1cc-3e0f-530a-a571-6ba4f2c8ba12', NULL, 9, 9, 'Exhort servants to be in subjection to their own masters, and to be well-pleasing in all things; not contradicting;'),
  ('3f22ea02-2bcb-54fa-af27-d9d2a6d6479c', '78e9e1cc-3e0f-530a-a571-6ba4f2c8ba12', NULL, 10, 10, 'not stealing, but showing all good fidelity; that they may adorn the doctrine of God, our Savior, in all things.'),
  ('80adaeff-8030-52aa-aaf3-e2cd70647b35', '78e9e1cc-3e0f-530a-a571-6ba4f2c8ba12', NULL, 11, 11, 'For the grace of God has appeared, bringing salvation to all men,'),
  ('fa84d979-d8f8-51a6-a59e-b6d9c3e46abf', '78e9e1cc-3e0f-530a-a571-6ba4f2c8ba12', NULL, 12, 12, 'instructing us to the intent that, denying ungodliness and worldly lusts, we would live soberly, righteously, and godly in this present world;'),
  ('db73a7c1-2383-5e9e-a9dc-e468df789c09', '78e9e1cc-3e0f-530a-a571-6ba4f2c8ba12', NULL, 13, 13, 'looking for the blessed hope and appearing of the glory of our great God and Savior, Jesus Christ;'),
  ('6d7dba4c-cbaa-5744-a12d-9bffb76142e4', '78e9e1cc-3e0f-530a-a571-6ba4f2c8ba12', NULL, 14, 14, 'who gave himself for us, that he might redeem us from all iniquity, and purify for himself a people for his own possession, zealous for good works.'),
  ('39d29a5d-53b9-5a48-a283-bd29a0de6a8a', '78e9e1cc-3e0f-530a-a571-6ba4f2c8ba12', NULL, 15, 15, 'Say these things and exhort and reprove with all authority. Let no man despise you.'),
  ('15443ccd-323d-574f-a1b5-ce8a472508fb', 'ab65fdf6-0abc-5726-afb2-d87ecef6613d', NULL, 1, 1, 'Remind them to be in subjection to rulers and to authorities, to be obedient, to be ready for every good work,'),
  ('9b01d0c7-5869-5418-a285-75052e4e6b16', 'ab65fdf6-0abc-5726-afb2-d87ecef6613d', NULL, 2, 2, 'to speak evil of no one, not to be contentious, to be gentle, showing all humility toward all men.'),
  ('01a82832-f226-5c2b-ae21-4f16ca6cac13', 'ab65fdf6-0abc-5726-afb2-d87ecef6613d', NULL, 3, 3, 'For we were also once foolish, disobedient, deceived, serving various lusts and pleasures, living in malice and envy, hateful, and hating one another.'),
  ('d8762058-aae6-54ab-ae96-22771bc90304', 'ab65fdf6-0abc-5726-afb2-d87ecef6613d', NULL, 4, 4, 'But when the kindness of God our Savior and his love toward mankind appeared,'),
  ('50780993-a054-5c6f-a68a-cbac97026d06', 'ab65fdf6-0abc-5726-afb2-d87ecef6613d', NULL, 5, 5, 'not by works of righteousness, which we did ourselves, but according to his mercy, he saved us, through the washing of regeneration and renewing by the Holy Spirit,'),
  ('ca0553a2-ed37-5097-ae55-763d86dbb0e2', 'ab65fdf6-0abc-5726-afb2-d87ecef6613d', NULL, 6, 6, 'whom he poured out on us richly, through Jesus Christ our Savior;'),
  ('80c25798-0ca9-5fdc-a12c-e754214c59d3', 'ab65fdf6-0abc-5726-afb2-d87ecef6613d', NULL, 7, 7, 'that, being justified by his grace, we might be made heirs according to the hope of eternal life.'),
  ('a3cf81fc-92cb-55fd-a138-17a69baddc98', 'ab65fdf6-0abc-5726-afb2-d87ecef6613d', NULL, 8, 8, 'This saying is faithful, and concerning these things I desire that you affirm confidently, so that those who have believed God may be careful to maintain good works. These things are good and profitable to men;'),
  ('280e64d0-92c9-5d93-a24b-164484a247b6', 'ab65fdf6-0abc-5726-afb2-d87ecef6613d', NULL, 9, 9, 'but shun foolish questionings, genealogies, strife, and disputes about the law; for they are unprofitable and vain.'),
  ('1ca27625-e605-5637-a0ff-c6120b557bf8', 'ab65fdf6-0abc-5726-afb2-d87ecef6613d', NULL, 10, 10, 'Avoid a factious man after a first and second warning;'),
  ('0a4b3a76-03a4-51bd-aa1c-ff9dd5ce067e', 'ab65fdf6-0abc-5726-afb2-d87ecef6613d', NULL, 11, 11, 'knowing that such a one is perverted, and sins, being self-condemned.'),
  ('bd9abd54-df24-5376-a766-ee6ae0d0814d', 'ab65fdf6-0abc-5726-afb2-d87ecef6613d', NULL, 12, 12, 'When I send Artemas to you, or Tychicus, be diligent to come to me to Nicopolis, for I have determined to winter there.'),
  ('619f584b-b7d4-5ec1-a27a-b7dbc659944f', 'ab65fdf6-0abc-5726-afb2-d87ecef6613d', NULL, 13, 13, 'Send Zenas, the lawyer, and Apollos on their journey speedily, that nothing may be lacking for them.'),
  ('079ebef7-44fc-5955-a774-54d717a301ba', 'ab65fdf6-0abc-5726-afb2-d87ecef6613d', NULL, 14, 14, 'Let our people also learn to maintain good works for necessary uses, that they may not be unfruitful.'),
  ('1d03cc36-ff2b-58af-a129-4e79c71c7e74', 'ab65fdf6-0abc-5726-afb2-d87ecef6613d', NULL, 15, 15, 'All who are with me greet you. Greet those who love us in faith. Grace be with you all. Amen.'),
  ('182d24c7-7811-5880-a512-636b96bb937f', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 1, 1, 'Paul, a prisoner of Christ Jesus, and Timothy our brother, to Philemon, our beloved fellow worker,'),
  ('77cc3d44-941d-57eb-a2dc-399efd00c02c', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 2, 2, 'to the beloved Apphia, to Archippus, our fellow soldier, and to the assembly in your house:'),
  ('e28493cb-ffc7-5acd-a201-2a39766f273b', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 3, 3, 'Grace to you and peace from God our Father and the Lord Jesus Christ.'),
  ('d7f69b92-86fe-5c74-a8ce-219d0c664156', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 4, 4, 'I thank my God always, making mention of you in my prayers,'),
  ('b7ced71d-bd7f-5024-ae0d-b96f0420b048', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 5, 5, 'hearing of your love, and of the faith which you have toward the Lord Jesus, and toward all the saints;'),
  ('81d2bff2-e1c4-50e3-a863-ab4f648a996b', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 6, 6, 'that the fellowship of your faith may become effective, in the knowledge of every good thing which is in us in Christ Jesus.'),
  ('afaa5020-b032-55f1-a58e-d9feec85ce2a', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 7, 7, 'For we have much joy and comfort in your love, because the hearts of the saints have been refreshed through you, brother.'),
  ('3619f4ca-ccd9-550b-a05a-5c218987a900', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 8, 8, 'Therefore, though I have all boldness in Christ to command you that which is appropriate,'),
  ('c7281a27-d422-5d46-a1e8-4b04c08feda2', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 9, 9, 'yet for love''s sake I rather beg, being such a one as Paul, the aged, but also a prisoner of Jesus Christ.'),
  ('73378bd8-a833-5070-ab73-11ee39c56f6f', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 10, 10, 'I beg you for my child, whom I have become the father of in my chains, Onesimus,'),
  ('95e29d98-79ca-5f29-a27e-12613d2385ab', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 11, 11, 'who once was useless to you, but now is useful to you and to me.'),
  ('c9788953-f5ed-5007-ac57-f2a82c6f3c88', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 12, 12, 'I am sending him back. Therefore receive him, that is, my own heart,'),
  ('f8ae65d1-5802-56ac-ad83-c06d977148e7', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 13, 13, 'whom I desired to keep with me, that on your behalf he might serve me in my chains for the Good News.'),
  ('593cdac0-53cb-597d-aa04-c9914d770a4d', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 14, 14, 'But I was willing to do nothing without your consent, that your goodness would not be as of necessity, but of free will.'),
  ('1abfff3e-dce5-59af-a27e-f223663ea363', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 15, 15, 'For perhaps he was therefore separated from you for a while, that you would have him forever,'),
  ('a17f61b6-9819-52ab-a284-40eff7dc53df', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 16, 16, 'no longer as a slave, but more than a slave, a beloved brother, especially to me, but how much rather to you, both in the flesh and in the Lord.'),
  ('0374216c-86bb-5e6d-a220-9ac5d6f1443b', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 17, 17, 'If then you count me a partner, receive him as you would receive me.'),
  ('41d28eb4-e0b9-5f84-a081-07b4bde8e7bf', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 18, 18, 'But if he has wronged you at all, or owes you anything, put that to my account.'),
  ('b69b2921-0cd0-598d-a445-f75af18362e1', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 19, 19, 'I, Paul, write this with my own hand: I will repay it (not to mention to you that you owe to me even your own self besides).'),
  ('1d9b811d-f592-583d-ab57-c7b15918fce4', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 20, 20, 'Yes, brother, let me have joy from you in the Lord. Refresh my heart in the Lord.'),
  ('89b5b24a-34f2-51ff-a527-51775c3993a8', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 21, 21, 'Having confidence in your obedience, I write to you, knowing that you will do even beyond what I say.'),
  ('94d260b5-b8a3-555b-a012-a5e3f99b0724', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 22, 22, 'Also, prepare a guest room for me, for I hope that through your prayers I will be restored to you.'),
  ('865e1f55-204e-50a3-a48a-5dbdce746102', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 23, 23, 'Epaphras, my fellow prisoner in Christ Jesus, greets you,'),
  ('1e169d54-6a1d-5556-ad74-d0eae91ed54c', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 24, 24, 'as do Mark, Aristarchus, Demas, and Luke, my fellow workers.'),
  ('e409cb7f-a05a-5f89-a302-6795896998c9', '7aff58f2-fdbe-511f-aef7-0b08140873ef', NULL, 25, 25, 'The grace of our Lord Jesus Christ be with your spirit. Amen.'),
  ('dd17369f-3021-54a8-a060-a7aa360f5a07', 'dd68702e-9a33-5479-a794-b37e40c81d3b', NULL, 1, 1, 'God, having in the past spoken to the fathers through the prophets at many times and in various ways,'),
  ('bf4cac0d-9d45-5384-a97f-fba66f8e3332', 'dd68702e-9a33-5479-a794-b37e40c81d3b', NULL, 2, 2, 'has at the end of these days spoken to us by his Son, whom he appointed heir of all things, through whom also he made the worlds.'),
  ('022f7a95-136b-5704-aa75-c38be370504f', 'dd68702e-9a33-5479-a794-b37e40c81d3b', NULL, 3, 3, 'His Son is the radiance of his glory, the very image of his substance, and upholding all things by the word of his power, when he had by himself made purification for our sins, sat down on the right hand of the Majesty on high;'),
  ('d5f1d9a2-bc8b-5ecb-afb5-038dbbba77b1', 'dd68702e-9a33-5479-a794-b37e40c81d3b', NULL, 4, 4, 'having become so much better than the angels, as he has inherited a more excellent name than they have.'),
  ('e458e2bc-1e71-5ecc-abd9-d57feb95ff50', 'dd68702e-9a33-5479-a794-b37e40c81d3b', NULL, 5, 5, 'For to which of the angels did he say at any time, "You are my Son. Today have I become your father?" and again, "I will be to him a Father, and he will be to me a Son?"'),
  ('a132a8ba-1b5d-5a4d-a814-f750a9e97d70', 'dd68702e-9a33-5479-a794-b37e40c81d3b', NULL, 6, 6, 'Again, when he brings in the firstborn into the world he says, "Let all the angels of God worship him."'),
  ('95856c38-a413-529e-aab3-24094d3e4e74', 'dd68702e-9a33-5479-a794-b37e40c81d3b', NULL, 7, 7, 'Of the angels he says, "Who makes his angels winds, and his servants a flame of fire."'),
  ('d44b8a16-3562-5f2f-a2e8-41db285aa36a', 'dd68702e-9a33-5479-a794-b37e40c81d3b', NULL, 8, 8, 'But of the Son he says, "Your throne, O God, is forever and ever. The scepter of uprightness is the scepter of your Kingdom.'),
  ('9832a483-114d-5a31-a65a-b35e35adb2e0', 'dd68702e-9a33-5479-a794-b37e40c81d3b', NULL, 9, 9, 'You have loved righteousness, and hated iniquity; therefore God, your God, has anointed you with the oil of gladness above your fellows."'),
  ('f19061d0-b21d-53bb-a2c0-41b70dc45b0c', 'dd68702e-9a33-5479-a794-b37e40c81d3b', NULL, 10, 10, 'And, "You, Lord, in the beginning, laid the foundation of the earth. The heavens are the works of your hands.'),
  ('7ca82ff2-4249-51ae-a90a-b879f80b3222', 'dd68702e-9a33-5479-a794-b37e40c81d3b', NULL, 11, 11, 'They will perish, but you continue. They all will grow old like a garment does.'),
  ('ab522081-7a7b-534e-ad59-bd73f862ee6a', 'dd68702e-9a33-5479-a794-b37e40c81d3b', NULL, 12, 12, 'As a mantle, you will roll them up, and they will be changed; but you are the same. Your years will not fail."'),
  ('f3291689-7c81-533d-aff3-18049ee0c5d7', 'dd68702e-9a33-5479-a794-b37e40c81d3b', NULL, 13, 13, 'But which of the angels has he told at any time, "Sit at my right hand, until I make your enemies the footstool of your feet?"'),
  ('1c8db786-7fd3-5bee-af68-01926a2c959a', 'dd68702e-9a33-5479-a794-b37e40c81d3b', NULL, 14, 14, 'Aren''t they all serving spirits, sent out to do service for the sake of those who will inherit salvation?'),
  ('e80aa922-3746-5e35-a416-c87c7b33a275', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 1, 1, 'Therefore we ought to pay greater attention to the things that were heard, lest perhaps we drift away.'),
  ('c692fef6-897d-5273-a9ee-fa4a4e806593', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 2, 2, 'For if the word spoken through angels proved steadfast, and every transgression and disobedience received a just recompense;'),
  ('7d09d964-f71f-5a06-ad17-af46922e9d06', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 3, 3, 'how will we escape if we neglect so great a salvation--which at the first having been spoken through the Lord, was confirmed to us by those who heard;'),
  ('29fbf5f6-16ef-532c-a8ed-7af5d258094d', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 4, 4, 'God also testifying with them, both by signs and wonders, by various works of power, and by gifts of the Holy Spirit, according to his own will?'),
  ('e0fced2a-cbd7-5696-aaca-fc60d720253f', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 5, 5, 'For he didn''t subject the world to come, of which we speak, to angels.'),
  ('2787b021-3fbe-5143-a1e3-fcb35725c433', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 6, 6, 'But one has somewhere testified, saying, "What is man, that you think of him? Or the son of man, that you care for him?'),
  ('7b51e3af-8c76-56dd-a9d6-6549f7095108', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 7, 7, 'You made him a little lower than the angels. You crowned him with glory and honor.'),
  ('0bc62d34-b201-5a6b-a326-c196bab8c874', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 8, 8, 'You have put all things in subjection under his feet." For in that he subjected all things to him, he left nothing that is not subject to him. But now we don''t see all things subjected to him, yet.'),
  ('7e2344af-cf1f-5a29-a80e-438ea79de12d', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 9, 9, 'But we see him who has been made a little lower than the angels, Jesus, because of the suffering of death crowned with glory and honor, that by the grace of God he should taste of death for everyone.'),
  ('ac34cc94-cfeb-5b3f-aacd-fadff0606bf6', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 10, 10, 'For it became him, for whom are all things, and through whom are all things, in bringing many children to glory, to make the author of their salvation perfect through sufferings.'),
  ('c11fe7b7-7bc8-5c0f-a3e1-b726861dd2ee', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 11, 11, 'For both he who sanctifies and those who are sanctified are all from one, for which cause he is not ashamed to call them brothers,'),
  ('76eecfd9-31bf-510e-a03d-86183d86feeb', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 12, 12, 'saying, "I will declare your name to my brothers. In the midst of the congregation I will sing your praise."'),
  ('e7d907dc-8bdf-5488-a820-3859d1ef4021', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 13, 13, 'Again, "I will put my trust in him." Again, "Behold, here I am with the children whom God has given me."'),
  ('d08476c0-5ef8-5f7a-a405-28f10420c1e1', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 14, 14, 'Since then the children have shared in flesh and blood, he also himself in the same way partook of the same, that through death he might bring to nothing him who had the power of death, that is, the devil,'),
  ('420bae4b-f1a5-519c-a2cf-b5813070db48', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 15, 15, 'and might deliver all of them who through fear of death were all their lifetime subject to bondage.'),
  ('54e5441b-1ecc-58e7-aabf-01b55bfbea6d', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 16, 16, 'For most certainly, he doesn''t give help to angels, but he gives help to the seed of Abraham.'),
  ('8a1b9709-9a82-5bc0-a443-44fb750ba7da', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 17, 17, 'Therefore he was obligated in all things to be made like his brothers, that he might become a merciful and faithful high priest in things pertaining to God, to make atonement for the sins of the people.'),
  ('13944450-eac1-5cfb-ac5b-4de3cccda278', 'd30376d1-ee38-5273-ae6c-91be32da59b5', NULL, 18, 18, 'For in that he himself has suffered being tempted, he is able to help those who are tempted.'),
  ('84656f75-572e-54df-a99a-365b84ca891f', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 1, 1, 'Therefore, holy brothers, partakers of a heavenly calling, consider the Apostle and High Priest of our confession, Jesus;'),
  ('a6b7e407-212f-59d2-a553-8e301bd6ce8e', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 2, 2, 'who was faithful to him who appointed him, as also was Moses in all his house.'),
  ('c58d5138-19ea-539e-a953-f1644ca6a63d', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 3, 3, 'For he has been counted worthy of more glory than Moses, inasmuch as he who built the house has more honor than the house.'),
  ('e5243c6b-06a4-5187-a5c2-7995931e47f3', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 4, 4, 'For every house is built by someone; but he who built all things is God.'),
  ('b7e4ba5a-ee53-54f6-a61f-6762a5ee01e6', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 5, 5, 'Moses indeed was faithful in all his house as a servant, for a testimony of those things which were afterward to be spoken,'),
  ('1139b0d4-e6ee-5a8c-adc0-3476c88314dc', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 6, 6, 'but Christ is faithful as a Son over his house; whose house we are, if we hold fast our confidence and the glorying of our hope firm to the end.'),
  ('427b41ff-2877-5d19-a6dc-5869e8a3b833', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 7, 7, 'Therefore, even as the Holy Spirit says, "Today if you will hear his voice,'),
  ('ce513681-1258-5b12-ac48-8cd3e8b9ac51', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 8, 8, 'don''t harden your hearts, as in the rebellion, like as in the day of the trial in the wilderness,'),
  ('4eba7389-1246-5972-a569-634eeaf56445', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 9, 9, 'where your fathers tested me by proving me, and saw my works for forty years.'),
  ('ed4d8222-87f0-54fa-a8db-e846edc2fd45', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 10, 10, 'Therefore I was displeased with that generation, and said, ''They always err in their heart, but they didn''t know my ways;'''),
  ('c2b2e522-63e9-52e3-a644-8b6f7646dbf0', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 11, 11, 'as I swore in my wrath, ''They will not enter into my rest.''"'),
  ('24c59e53-b089-53bc-a2d3-e379195111df', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 12, 12, 'Beware, brothers, lest perhaps there be in any one of you an evil heart of unbelief, in falling away from the living God;'),
  ('976899e5-0d2c-52ac-af9e-d760292dffcd', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 13, 13, 'but exhort one another day by day, so long as it is called "today;" lest any one of you be hardened by the deceitfulness of sin.'),
  ('7bbf1717-aab3-5423-a630-38bac6ab371a', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 14, 14, 'For we have become partakers of Christ, if we hold fast the beginning of our confidence firm to the end:'),
  ('bce65b01-dd0e-544a-a0e7-403ce6578668', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 15, 15, 'while it is said, "Today if you will hear his voice, don''t harden your hearts, as in the rebellion."'),
  ('a8c2f21f-ceba-5d15-ae64-1ae19bb80cb2', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 16, 16, 'For who, when they heard, rebelled? No, didn''t all those who came out of Egypt by Moses?'),
  ('c81da35f-6791-5c26-a8c9-589f184c61c9', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 17, 17, 'With whom was he displeased forty years? Wasn''t it with those who sinned, whose bodies fell in the wilderness?'),
  ('1c77277f-a68f-5140-aa83-eb842dd8baf6', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 18, 18, 'To whom did he swear that they wouldn''t enter into his rest, but to those who were disobedient?'),
  ('1d835a2a-363a-53be-a384-e4ec01341244', 'a4e55b00-8cbd-5157-ad57-30e9400f4527', NULL, 19, 19, 'We see that they were not able to enter in because of unbelief.'),
  ('10345473-2d08-5bbb-a1e4-b76a89f941fa', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 1, 1, 'Let us fear therefore, lest perhaps anyone of you should seem to have come short of a promise of entering into his rest.'),
  ('72444f86-bec0-5298-ae0e-735c568ac518', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 2, 2, 'For indeed we have had good news preached to us, even as they also did, but the word they heard didn''t profit them, because it wasn''t mixed with faith by those who heard.'),
  ('d0bca94f-0eb1-50bb-a3ed-20264c78403c', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 3, 3, 'For we who have believed do enter into that rest, even as he has said, "As I swore in my wrath, they will not enter into my rest;" although the works were finished from the foundation of the world.'),
  ('351352a5-767d-5317-a3e6-652434608770', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 4, 4, 'For he has said this somewhere about the seventh day, "God rested on the seventh day from all his works;"'),
  ('181fb458-811f-504b-ad80-e6afa368e6f2', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 5, 5, 'and in this place again, "They will not enter into my rest."'),
  ('b8c088b1-d017-509e-acb0-fdd1a9e13eb0', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 6, 6, 'Seeing therefore it remains that some should enter therein, and they to whom the good news was before preached failed to enter in because of disobedience,'),
  ('56446510-6f87-5cfd-a4af-bdd921b98edd', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 7, 7, 'he again defines a certain day, today, saying through David so long a time afterward (just as has been said), "Today if you will hear his voice, don''t harden your hearts."'),
  ('8ab517fd-9de3-5dd1-ab0d-79965e996be2', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 8, 8, 'For if Joshua had given them rest, he would not have spoken afterward of another day.'),
  ('d91f46e5-7d7e-5bd1-a51c-31a3f66e2b19', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 9, 9, 'There remains therefore a Sabbath rest for the people of God.'),
  ('b0450572-0179-568d-ac51-62b65e3251c3', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 10, 10, 'For he who has entered into his rest has himself also rested from his works, as God did from his.'),
  ('3f35b724-335a-5c9b-a20d-97a9c92335be', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 11, 11, 'Let us therefore give diligence to enter into that rest, lest anyone fall after the same example of disobedience.'),
  ('d3810139-f0f6-5237-ae61-0e8b916fa1c5', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 12, 12, 'For the word of God is living, and active, and sharper than any two-edged sword, and piercing even to the dividing of soul and spirit, of both joints and marrow, and is able to discern the thoughts and intentions of the heart.'),
  ('47772b32-bde0-59da-a031-c07d460a3644', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 13, 13, 'There is no creature that is hidden from his sight, but all things are naked and laid open before the eyes of him with whom we have to do.'),
  ('7f8caa28-b824-5c77-a060-6a5255deca25', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 14, 14, 'Having then a great high priest, who has passed through the heavens, Jesus, the Son of God, let us hold tightly to our confession.'),
  ('8784903a-d34d-5f98-afab-eb488bd54116', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 15, 15, 'For we don''t have a high priest who can''t be touched with the feeling of our infirmities, but one who has been in all points tempted like we are, yet without sin.'),
  ('9600f6c8-7b7b-5d9a-a1f2-9a5956c0d14e', 'fea5744d-6fcd-5ad8-a04b-4a2ddb4c2cd1', NULL, 16, 16, 'Let us therefore draw near with boldness to the throne of grace, that we may receive mercy, and may find grace for help in time of need.'),
  ('9a6152be-351c-5e0e-af06-b8de44404285', '2f825577-e74e-5476-acc4-a76070e0a3d9', NULL, 1, 1, 'For every high priest, being taken from among men, is appointed for men in things pertaining to God, that he may offer both gifts and sacrifices for sins.'),
  ('74e8c9cb-a1a2-55f7-a53c-12433f7832e7', '2f825577-e74e-5476-acc4-a76070e0a3d9', NULL, 2, 2, 'The high priest can deal gently with those who are ignorant and going astray, because he himself is also surrounded with weakness.'),
  ('4b1946c4-320e-5478-a12d-5a5f4ae809c3', '2f825577-e74e-5476-acc4-a76070e0a3d9', NULL, 3, 3, 'Because of this, he must offer sacrifices for sins for the people, as well as for himself.'),
  ('f9992324-e56a-56db-a70a-57dd60112a6e', '2f825577-e74e-5476-acc4-a76070e0a3d9', NULL, 4, 4, 'Nobody takes this honor on himself, but he is called by God, just like Aaron was.'),
  ('45e2e586-4146-50bb-a865-9adc6ca781b8', '2f825577-e74e-5476-acc4-a76070e0a3d9', NULL, 5, 5, 'So also Christ didn''t glorify himself to be made a high priest, but it was he who said to him, "You are my Son. Today I have become your father."'),
  ('42ea4fa3-2d5e-5a2f-a0af-accc5917971d', '2f825577-e74e-5476-acc4-a76070e0a3d9', NULL, 6, 6, 'As he says also in another place, "You are a priest forever, after the order of Melchizedek."'),
  ('1e942fa9-a79c-565f-a0bd-43befd75e152', '2f825577-e74e-5476-acc4-a76070e0a3d9', NULL, 7, 7, 'He, in the days of his flesh, having offered up prayers and petitions with strong crying and tears to him who was able to save him from death, and having been heard for his godly fear,'),
  ('21b464a0-99be-5444-aed5-aecf8b19cdf9', '2f825577-e74e-5476-acc4-a76070e0a3d9', NULL, 8, 8, 'though he was a Son, yet learned obedience by the things which he suffered.'),
  ('4fee88d0-44ed-5a28-a022-c0c6f773870b', '2f825577-e74e-5476-acc4-a76070e0a3d9', NULL, 9, 9, 'Having been made perfect, he became to all of those who obey him the author of eternal salvation,'),
  ('faa01cab-e0df-51d5-a2d4-012d77c27a85', '2f825577-e74e-5476-acc4-a76070e0a3d9', NULL, 10, 10, 'named by God a high priest after the order of Melchizedek.'),
  ('70a12624-478f-550a-a82d-0ed1e7a6022e', '2f825577-e74e-5476-acc4-a76070e0a3d9', NULL, 11, 11, 'About him we have many words to say, and hard to interpret, seeing you have become dull of hearing.'),
  ('834b2d90-54be-596c-a31e-a5bf9cb7eacd', '2f825577-e74e-5476-acc4-a76070e0a3d9', NULL, 12, 12, 'For although by this time you should be teachers, you again need to have someone teach you the rudiments of the first principles of the oracles of God. You have come to need milk, and not solid food.'),
  ('2d576ccc-d2f3-55c1-a85e-364c9dd2b511', '2f825577-e74e-5476-acc4-a76070e0a3d9', NULL, 13, 13, 'For everyone who lives on milk is not experienced in the word of righteousness, for he is a baby.'),
  ('65c30132-db88-5a5d-a8ce-3d35e58753d8', '2f825577-e74e-5476-acc4-a76070e0a3d9', NULL, 14, 14, 'But solid food is for those who are full grown, who by reason of use have their senses exercised to discern good and evil.'),
  ('9c6ea979-508e-52d2-aec6-ab042a8ce644', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 1, 1, 'Therefore leaving the teaching of the first principles of Christ, let us press on to perfection--not laying again a foundation of repentance from dead works, of faith toward God,'),
  ('173415a1-b90d-56eb-a439-c90086df9a9c', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 2, 2, 'of the teaching of baptisms, of laying on of hands, of resurrection of the dead, and of eternal judgment.'),
  ('afc79604-9fe6-54fe-a9e1-fdff7f054e13', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 3, 3, 'This will we do, if God permits.'),
  ('14c93c58-2e80-54ef-a11c-7228bae940b7', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 4, 4, 'For concerning those who were once enlightened and tasted of the heavenly gift, and were made partakers of the Holy Spirit,'),
  ('3ec35f25-eff2-5a7d-a313-7eb3507dec43', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 5, 5, 'and tasted the good word of God, and the powers of the age to come,'),
  ('104324c5-c0af-58ae-afb0-607d5da02fac', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 6, 6, 'and then fell away, it is impossible to renew them again to repentance; seeing they crucify the Son of God for themselves again, and put him to open shame.'),
  ('014d0d36-e98a-5180-a287-6d3273fc28cb', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 7, 7, 'For the land which has drunk the rain that comes often on it, and brings forth a crop suitable for them for whose sake it is also tilled, receives blessing from God;'),
  ('10041145-399e-5624-a722-de75130e6bb2', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 8, 8, 'but if it bears thorns and thistles, it is rejected and near being cursed, whose end is to be burned.'),
  ('5edc6441-407b-5df2-ae1c-d5bb32d6f4d7', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 9, 9, 'But, beloved, we are persuaded of better things for you, and things that accompany salvation, even though we speak like this.'),
  ('fee2bfd5-4cf8-5fd2-a345-f0a28abb8e9c', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 10, 10, 'For God is not unrighteous, so as to forget your work and the labor of love which you showed toward his name, in that you served the saints, and still do serve them.'),
  ('1d26ee1f-63da-5353-a937-26d3af4c7cc9', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 11, 11, 'We desire that each one of you may show the same diligence to the fullness of hope even to the end,'),
  ('6a4875e3-66b3-5421-a2e3-5b3bd9639dc4', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 12, 12, 'that you won''t be sluggish, but imitators of those who through faith and patience inherited the promises.'),
  ('a26e034a-4c4f-5bb9-add3-64062c01493c', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 13, 13, 'For when God made a promise to Abraham, since he could swear by none greater, he swore by himself,'),
  ('4612dc6a-a46a-5fed-a24d-8cc598645848', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 14, 14, 'saying, "Surely blessing I will bless you, and multiplying I will multiply you."'),
  ('2587389f-68eb-5033-a163-ec5fb88e8e5d', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 15, 15, 'Thus, having patiently endured, he obtained the promise.'),
  ('2dfebad2-a636-5b50-aaea-1fd23c67a5b5', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 16, 16, 'For men indeed swear by a greater one, and in every dispute of theirs the oath is final for confirmation.'),
  ('68e8a1c2-74c0-548a-aa5e-53f63999c481', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 17, 17, 'In this way God, being determined to show more abundantly to the heirs of the promise the immutability of his counsel, interposed with an oath;'),
  ('81ac965e-9fc9-5ca7-abfc-28cffffdd75c', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 18, 18, 'that by two immutable things, in which it is impossible for God to lie, we may have a strong encouragement, who have fled for refuge to take hold of the hope set before us.'),
  ('7f67cf34-fd96-5621-a2f3-db89a8d19082', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 19, 19, 'This hope we have as an anchor of the soul, a hope both sure and steadfast and entering into that which is within the veil;'),
  ('2af3aa5f-226a-571b-a342-45fcd3082f94', '34cbd134-e417-5db2-aaab-626899e0717e', NULL, 20, 20, 'where as a forerunner Jesus entered for us, having become a high priest forever after the order of Melchizedek.'),
  ('e59983f8-55b8-5901-ab1e-0e62080e2beb', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 1, 1, 'For this Melchizedek, king of Salem, priest of God Most High, who met Abraham returning from the slaughter of the kings and blessed him,'),
  ('7fe12c8e-b4bf-53a8-ad04-aeb589070baa', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 2, 2, 'to whom also Abraham divided a tenth part of all (being first, by interpretation, king of righteousness, and then also king of Salem, which is king of peace;'),
  ('8c54392e-ce0d-545b-a72e-36718af802eb', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 3, 3, 'without father, without mother, without genealogy, having neither beginning of days nor end of life, but made like the Son of God), remains a priest continually.'),
  ('a521653f-bcb9-5e8c-abfc-db0af71ac546', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 4, 4, 'Now consider how great this man was, to whom even Abraham, the patriarch, gave a tenth out of the best spoils.'),
  ('ae0dab38-afdd-5a67-a891-60c72e85c6ce', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 5, 5, 'They indeed of the sons of Levi who receive the priest''s office have a commandment to take tithes of the people according to the law, that is, of their brothers, though these have come out of the body of Abraham,'),
  ('1d45aa2f-8765-5649-a2ac-e4e4dde11fa0', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 6, 6, 'but he whose genealogy is not counted from them has accepted tithes from Abraham, and has blessed him who has the promises.'),
  ('a90877e5-aa20-57ae-acf7-87355df1bc50', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 7, 7, 'But without any dispute the lesser is blessed by the greater.'),
  ('f1896d1a-5fbc-5f54-aae7-4dd2e31ab390', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 8, 8, 'Here people who die receive tithes, but there one receives tithes of whom it is testified that he lives.'),
  ('96b21506-1815-52a0-a60b-4e7f785f8e69', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 9, 9, 'We can say that through Abraham even Levi, who receives tithes, has paid tithes,'),
  ('78cf6c4d-fea8-5227-a3cc-0431e80d8e79', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 10, 10, 'for he was yet in the body of his father when Melchizedek met him.'),
  ('28c1c509-2076-5ab1-ae85-b61a2bb0319d', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 11, 11, 'Now if there was perfection through the Levitical priesthood (for under it the people have received the law), what further need was there for another priest to arise after the order of Melchizedek, and not be called after the order of Aaron?'),
  ('d31907c4-65cd-5006-a8e5-b81c2bd64583', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 12, 12, 'For the priesthood being changed, there is of necessity a change made also in the law.'),
  ('ef3cb722-dc23-53c8-a7df-252ef8598bc4', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 13, 13, 'For he of whom these things are said belongs to another tribe, from which no one has officiated at the altar.'),
  ('86f1da25-e86d-563a-a638-c40b063579c5', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 14, 14, 'For it is evident that our Lord has sprung out of Judah, about which tribe Moses spoke nothing concerning priesthood.'),
  ('27e2aa48-28b2-524a-af0b-5fc45cda110f', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 15, 15, 'This is yet more abundantly evident, if after the likeness of Melchizedek there arises another priest,'),
  ('3f7a776e-ae0a-5b65-acfa-55e2bba4d7e9', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 16, 16, 'who has been made, not after the law of a fleshly commandment, but after the power of an endless life:'),
  ('59c4a445-78ed-549c-acd9-f344b2c41735', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 17, 17, 'for it is testified, "You are a priest forever, according to the order of Melchizedek."'),
  ('f34c8cb7-21be-587a-ab90-7fd5b74ee83a', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 18, 18, 'For there is an annulling of a foregoing commandment because of its weakness and uselessness'),
  ('e1b400ea-d678-5294-ab49-c513cea5f3c6', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 19, 19, '(for the law made nothing perfect), and a bringing in of a better hope, through which we draw near to God.'),
  ('a4f0fcae-a3f4-59b1-aff6-8147c7720a84', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 20, 20, 'Inasmuch as he was not made priest without the taking of an oath'),
  ('c7d964c9-f70a-5d9d-aed4-22c539f23625', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 21, 21, '(for they indeed have been made priests without an oath), but he with an oath by him that says of him, "The Lord swore and will not change his mind, ''You are a priest forever, according to the order of Melchizedek.''"'),
  ('8e32e030-c040-546b-aebd-756b03c0992c', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 22, 22, 'By so much, Jesus has become the collateral of a better covenant.'),
  ('51e51ae1-c696-5fe7-a523-d95c34cf9af5', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 23, 23, 'Many, indeed, have been made priests, because they are hindered from continuing by death.'),
  ('e04fabdf-0a1b-5604-aac1-c739e1da1527', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 24, 24, 'But he, because he lives forever, has his priesthood unchangeable.'),
  ('5ec4cd89-1859-58db-a204-348684166e89', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 25, 25, 'Therefore he is also able to save to the uttermost those who draw near to God through him, seeing that he lives forever to make intercession for them.'),
  ('39265294-d7b1-5196-aefa-309de9718874', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 26, 26, 'For such a high priest was fitting for us: holy, guiltless, undefiled, separated from sinners, and made higher than the heavens;'),
  ('f4696d0b-f198-587a-a179-201e490075ba', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 27, 27, 'who doesn''t need, like those high priests, to offer up sacrifices daily, first for his own sins, and then for the sins of the people. For he did this once for all, when he offered up himself.'),
  ('e10aafd2-6b29-5aa5-acf4-19ed2a39e7e6', 'd65e7432-a805-53f5-ab66-b985d8645fd3', NULL, 28, 28, 'For the law appoints men as high priests who have weakness, but the word of the oath which came after the law appoints a Son forever who has been perfected.'),
  ('3f83a7a0-0d5c-5482-abe2-7eb9ea15aec0', '7bbdbabf-3396-5fc1-a4f1-07ea377afc21', NULL, 1, 1, 'Now in the things which we are saying, the main point is this. We have such a high priest, who sat down on the right hand of the throne of the Majesty in the heavens,'),
  ('59a8c81b-c3d0-5498-ab14-31d63e575c2e', '7bbdbabf-3396-5fc1-a4f1-07ea377afc21', NULL, 2, 2, 'a servant of the sanctuary, and of the true tabernacle, which the Lord pitched, not man.'),
  ('dce4bb2b-c055-5514-af2e-4ee58b98e36e', '7bbdbabf-3396-5fc1-a4f1-07ea377afc21', NULL, 3, 3, 'For every high priest is appointed to offer both gifts and sacrifices. Therefore it is necessary that this high priest also have something to offer.'),
  ('d9b09cec-baaf-5fa2-af1e-3287e45fd12a', '7bbdbabf-3396-5fc1-a4f1-07ea377afc21', NULL, 4, 4, 'For if he were on earth, he would not be a priest at all, seeing there are priests who offer the gifts according to the law;'),
  ('fc9a9fda-4ab2-53fd-a6ce-fc3560868ae1', '7bbdbabf-3396-5fc1-a4f1-07ea377afc21', NULL, 5, 5, 'who serve a copy and shadow of the heavenly things, even as Moses was warned by God when he was about to make the tabernacle, for he said, "See, you shall make everything according to the pattern that was shown to you on the mountain."'),
  ('cfe1afb8-c07b-5c18-a347-eff9f557cfdd', '7bbdbabf-3396-5fc1-a4f1-07ea377afc21', NULL, 6, 6, 'But now he has obtained a more excellent ministry, by so much as he is also the mediator of a better covenant, which on better promises has been given as law.'),
  ('0f7f877a-43ae-5053-afb3-e6de89539bfd', '7bbdbabf-3396-5fc1-a4f1-07ea377afc21', NULL, 7, 7, 'For if that first covenant had been faultless, then no place would have been sought for a second.'),
  ('1b80701d-831c-5f17-a5d5-8d3a68ee94d9', '7bbdbabf-3396-5fc1-a4f1-07ea377afc21', NULL, 8, 8, 'For finding fault with them, he said, "Behold, the days come," says the Lord, "that I will make a new covenant with the house of Israel and with the house of Judah;'),
  ('bc328f70-217c-55e1-ae9a-49243dbde8ef', '7bbdbabf-3396-5fc1-a4f1-07ea377afc21', NULL, 9, 9, 'not according to the covenant that I made with their fathers, in the day that I took them by the hand to lead them out of the land of Egypt; for they didn''t continue in my covenant, and I disregarded them," says the Lord.'),
  ('21c0cb66-dbf3-51aa-a972-2cac5b2920c8', '7bbdbabf-3396-5fc1-a4f1-07ea377afc21', NULL, 10, 10, '"For this is the covenant that I will make with the house of Israel. After those days," says the Lord; "I will put my laws into their mind, I will also write them on their heart. I will be their God, and they will be my people.'),
  ('56186f48-0c35-511d-aaba-87efc3ec547b', '7bbdbabf-3396-5fc1-a4f1-07ea377afc21', NULL, 11, 11, 'They will not teach every man his fellow citizen, and every man his brother, saying, ''Know the Lord,'' for all will know me, from the least of them to the greatest of them.'),
  ('707324b5-a2d6-58fd-aee1-f80ab89917d5', '7bbdbabf-3396-5fc1-a4f1-07ea377afc21', NULL, 12, 12, 'For I will be merciful to their unrighteousness. I will remember their sins and lawless deeds no more."'),
  ('c70a9a9f-0580-5c5d-a167-b2745006627e', '7bbdbabf-3396-5fc1-a4f1-07ea377afc21', NULL, 13, 13, 'In that he says, "A new covenant," he has made the first old. But that which is becoming old and grows aged is near to vanishing away.'),
  ('892ab2eb-990a-5706-a69d-0b9bda3d554d', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 1, 1, 'Now indeed even the first covenant had ordinances of divine service, and an earthly sanctuary.'),
  ('a1b8bf61-42bd-5c69-a56e-07c2fe33b5fe', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 2, 2, 'For a tabernacle was prepared. In the first part were the lampstand, the table, and the show bread; which is called the Holy Place.'),
  ('4121ca75-1dc2-57fc-ae84-4f8e0413b8d3', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 3, 3, 'After the second veil was the tabernacle which is called the Holy of Holies,'),
  ('e332fb5a-9389-5af0-a088-5c7418567622', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 4, 4, 'having a golden altar of incense, and the ark of the covenant overlaid on all sides with gold, in which was a golden pot holding the manna, Aaron''s rod that budded, and the tablets of the covenant;')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4fc1bdc9-ff94-5938-a0c4-97d982950811', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 5, 5, 'and above it cherubim of glory overshadowing the mercy seat, of which things we can''t speak now in detail.'),
  ('77872d21-538f-56e1-a8da-3badfd940d7d', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 6, 6, 'Now these things having been thus prepared, the priests go in continually into the first tabernacle, accomplishing the services,'),
  ('54ca5da8-aa26-501e-ad41-460a036d8607', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 7, 7, 'but into the second the high priest alone, once in the year, not without blood, which he offers for himself, and for the errors of the people.'),
  ('5d1ea6e7-cd43-5a63-aa98-102d5f982545', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 8, 8, 'The Holy Spirit is indicating this, that the way into the Holy Place wasn''t yet revealed while the first tabernacle was still standing;'),
  ('f6dd2dba-6cc8-5a86-adb6-7d984b0c5894', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 9, 9, 'which is a symbol of the present age, where gifts and sacrifices are offered that are incapable, concerning the conscience, of making the worshipper perfect;'),
  ('abf49b27-21e2-5101-af1a-c9bef248c252', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 10, 10, 'being only (with meats and drinks and various washings) fleshly ordinances, imposed until a time of reformation.'),
  ('eeb6e4e6-0870-553f-aa43-029067e5c8e0', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 11, 11, 'But Christ having come as a high priest of the coming good things, through the greater and more perfect tabernacle, not made with hands, that is to say, not of this creation,'),
  ('3e113c41-a5af-5066-ad01-8ed7b56b3286', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 12, 12, 'nor yet through the blood of goats and calves, but through his own blood, entered in once for all into the Holy Place, having obtained eternal redemption.'),
  ('b08fa8a7-1959-5f3a-ab14-755327032a01', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 13, 13, 'For if the blood of goats and bulls, and the ashes of a heifer sprinkling those who have been defiled, sanctify to the cleanness of the flesh:'),
  ('6a3496cd-0e0a-513e-af55-5777ef641ac8', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 14, 14, 'how much more will the blood of Christ, who through the eternal Spirit offered himself without blemish to God, cleanse your conscience from dead works to serve the living God?'),
  ('28a383a4-d446-5cf7-a81a-2a0f9df6b6ca', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 15, 15, 'For this reason he is the mediator of a new covenant, since a death has occurred for the redemption of the transgressions that were under the first covenant, that those who have been called may receive the promise of the eternal inheritance.'),
  ('e66f95d6-e255-59ce-a40f-eb14c6002010', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 16, 16, 'For where a last will and testament is, there must of necessity be the death of him who made it.'),
  ('577eaeb3-c97e-50af-a180-864039892cd6', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 17, 17, 'For a will is in force where there has been death, for it is never in force while he who made it lives.'),
  ('a788e1db-7039-5bcc-aae3-3642aa5d9a6e', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 18, 18, 'Therefore even the first covenant has not been dedicated without blood.'),
  ('f722a21e-fc0c-53c1-a492-c795b15cc113', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 19, 19, 'For when every commandment had been spoken by Moses to all the people according to the law, he took the blood of the calves and the goats, with water and scarlet wool and hyssop, and sprinkled both the book itself and all the people,'),
  ('83d4a332-a17e-5a65-a941-1fb0a7530382', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 20, 20, 'saying, "This is the blood of the covenant which God has commanded you."'),
  ('3f2e2034-3104-577d-a80a-ebd3335dd236', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 21, 21, 'Moreover he sprinkled the tabernacle and all the vessels of the ministry in the same way with the blood.'),
  ('f4e85076-4e77-5aec-a678-d4c7b42753da', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 22, 22, 'According to the law, nearly everything is cleansed with blood, and apart from shedding of blood there is no remission.'),
  ('dde78aec-683a-55a9-a98c-7bf2a885d620', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 23, 23, 'It was necessary therefore that the copies of the things in the heavens should be cleansed with these; but the heavenly things themselves with better sacrifices than these.'),
  ('055f93e3-44d0-549b-a026-bad1af2d6afe', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 24, 24, 'For Christ hasn''t entered into holy places made with hands, which are representations of the true, but into heaven itself, now to appear in the presence of God for us;'),
  ('4e7ee031-b5a2-57ea-a9c9-1a2f7237d6d2', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 25, 25, 'nor yet that he should offer himself often, as the high priest enters into the holy place year by year with blood not his own,'),
  ('ec83d50c-703c-5205-a567-898c2d319c02', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 26, 26, 'or else he must have suffered often since the foundation of the world. But now once at the end of the ages, he has been revealed to put away sin by the sacrifice of himself.'),
  ('4517b7e5-f261-55ea-ac15-9cecc078347c', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 27, 27, 'Inasmuch as it is appointed for men to die once, and after this, judgment,'),
  ('f1e8a696-bc2f-508e-ac97-de99f44695ae', '720f0ff9-29f4-5099-a827-bb8e8877e233', NULL, 28, 28, 'so Christ also, having been offered once to bear the sins of many, will appear a second time, without sin, to those who are eagerly waiting for him for salvation.'),
  ('4706aa14-15f4-5c42-ac8f-ee0487a63d22', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 1, 1, 'For the law, having a shadow of the good to come, not the very image of the things, can never with the same sacrifices year by year, which they offer continually, make perfect those who draw near.'),
  ('c4c9bbfc-054e-567f-ab77-d5e9ed0f527b', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 2, 2, 'Or else wouldn''t they have ceased to be offered, because the worshippers, having been once cleansed, would have had no more consciousness of sins?'),
  ('61bfdc07-3ebf-5653-a7ea-f6e4c51e80ae', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 3, 3, 'But in those sacrifices there is a yearly reminder of sins.'),
  ('e7436a3f-c607-53ab-ab30-454609499625', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 4, 4, 'For it is impossible that the blood of bulls and goats should take away sins.'),
  ('2c56887a-9f11-5adf-a780-0b333ab56ecb', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 5, 5, 'Therefore when he comes into the world, he says, "Sacrifice and offering you didn''t desire, but you prepared a body for me;'),
  ('7baefa77-6680-5a24-a344-3a455383b4b8', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 6, 6, 'You had no pleasure in whole burnt offerings and sacrifices for sin.'),
  ('900c4a29-685a-5f98-a47b-31499af81057', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 7, 7, 'Then I said, ''Behold, I have come (in the scroll of the book it is written of me) to do your will, O God.''"'),
  ('6347b7c1-8686-5d4d-a7f7-ce21ff75b05f', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 8, 8, 'Previously saying, "Sacrifices and offerings and whole burnt offerings and sacrifices for sin you didn''t desire, neither had pleasure in them" (those which are offered according to the law),'),
  ('4349b9e6-1eb9-5a85-a859-a597fe39ce67', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 9, 9, 'then he has said, "Behold, I have come to do your will." He takes away the first, that he may establish the second,'),
  ('7892dc10-9d47-597f-a915-2a48384fb922', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 10, 10, 'by which will we have been sanctified through the offering of the body of Jesus Christ once for all.'),
  ('a5e72d76-d747-54b9-aada-c1b08b47a9b0', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 11, 11, 'Every priest indeed stands day by day serving and often offering the same sacrifices, which can never take away sins,'),
  ('98efce7a-988c-529a-a9fb-15a62a9cf254', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 12, 12, 'but he, when he had offered one sacrifice for sins forever, sat down on the right hand of God;'),
  ('9532696e-096c-5b55-a3da-928260566aa9', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 13, 13, 'from that time waiting until his enemies are made the footstool of his feet.'),
  ('cd65aa58-7902-5e48-a7c3-7b5134f80d4e', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 14, 14, 'For by one offering he has perfected forever those who are being sanctified.'),
  ('346c0e38-09fa-5974-aa7c-ecf613853b21', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 15, 15, 'The Holy Spirit also testifies to us, for after saying,'),
  ('c62addfd-a673-5376-a005-509bbf827b83', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 16, 16, '"This is the covenant that I will make with them: ''After those days,'' says the Lord, ''I will put my laws on their heart, I will also write them on their mind;''" then he says,'),
  ('095c95d0-09e3-5e14-a771-ebde75eeabc9', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 17, 17, '"I will remember their sins and their iniquities no more."'),
  ('c92dca4c-7889-5d07-a4a4-75110435ce99', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 18, 18, 'Now where remission of these is, there is no more offering for sin.'),
  ('e7ac5e0c-98b7-529f-a531-7294bb838dd3', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 19, 19, 'Having therefore, brothers, boldness to enter into the holy place by the blood of Jesus,'),
  ('b6d80acb-33f5-57cb-ac31-b602df7b2e1a', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 20, 20, 'by the way which he dedicated for us, a new and living way, through the veil, that is to say, his flesh;'),
  ('6be1775f-388e-5201-a7ce-4f5ff15fdcef', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 21, 21, 'and having a great priest over the house of God,'),
  ('64aaedf3-c664-5691-ae0e-5a4ab685a365', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 22, 22, 'let''s draw near with a true heart in fullness of faith, having our hearts sprinkled from an evil conscience, and having our body washed with pure water,'),
  ('73bf4138-a4a2-57d9-aa7d-9e7b90c988f4', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 23, 23, 'let us hold fast the confession of our hope without wavering; for he who promised is faithful.'),
  ('d3bf9a7e-0dbf-58aa-a570-f018dc8e896d', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 24, 24, 'Let us consider how to provoke one another to love and good works,'),
  ('820f00e8-6a74-5092-a8b2-976d32d57d40', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 25, 25, 'not forsaking our own assembling together, as the custom of some is, but exhorting one another; and so much the more, as you see the Day approaching.'),
  ('49a67113-ae94-517a-a1fa-8da28fea6420', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 26, 26, 'For if we sin willfully after we have received the knowledge of the truth, there remains no more a sacrifice for sins,'),
  ('71cb59f8-5dce-5f23-aea8-caec8c4672b7', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 27, 27, 'but a certain fearful expectation of judgment, and a fierceness of fire which will devour the adversaries.'),
  ('0427c08a-4a1f-5430-a011-e934252114c6', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 28, 28, 'A man who disregards Moses'' law dies without compassion on the word of two or three witnesses.'),
  ('9de49aae-49a2-535c-ab5b-ef8b1ef1d25e', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 29, 29, 'How much worse punishment, do you think, will he be judged worthy of, who has trodden under foot the Son of God, and has counted the blood of the covenant with which he was sanctified an unholy thing, and has insulted the Spirit of grace?'),
  ('f68cc515-e675-5763-af3c-738f7c0b70ca', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 30, 30, 'For we know him who said, "Vengeance belongs to me," says the Lord, "I will repay." Again, "The Lord will judge his people."'),
  ('255cc47b-56c8-5631-aca1-4532c9802051', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 31, 31, 'It is a fearful thing to fall into the hands of the living God.'),
  ('cce7efb3-81e5-57fb-ad7b-45078ef6d4db', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 32, 32, 'But remember the former days, in which, after you were enlightened, you endured a great struggle with sufferings;'),
  ('2c95266b-53eb-5470-a934-abf820e3bc5b', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 33, 33, 'partly, being exposed to both reproaches and oppressions; and partly, becoming partakers with those who were treated so.'),
  ('37f0a0f9-69f5-542f-ab37-b10e7b3fc794', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 34, 34, 'For you both had compassion on me in my chains, and joyfully accepted the plundering of your possessions, knowing that you have for yourselves a better possession and an enduring one in the heavens.'),
  ('e2d3476e-520d-5e5e-a146-ea4e2d8f433b', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 35, 35, 'Therefore don''t throw away your boldness, which has a great reward.'),
  ('aa6387a5-3e38-5c5f-abd2-b4d5164b2f7c', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 36, 36, 'For you need endurance so that, having done the will of God, you may receive the promise.'),
  ('d0c38d36-ca3d-5f34-a7a7-aa356c4e3ca9', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 37, 37, '"In a very little while, he who comes will come, and will not wait.'),
  ('5d8d0f84-0e4d-5aa5-a131-432723468063', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 38, 38, 'But the righteous will live by faith. If he shrinks back, my soul has no pleasure in him."'),
  ('078fa8d4-8876-52e3-aee1-99818674b90d', '09260e82-5f47-5f65-aec0-8f4e1a68d8bd', NULL, 39, 39, 'But we are not of those who shrink back to destruction, but of those who have faith to the saving of the soul.'),
  ('cadf6038-a3bc-50cf-aec7-bf90e843b88d', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 1, 1, 'Now faith is assurance of things hoped for, proof of things not seen.'),
  ('86cc5dd8-92f1-592a-aa28-6449ea28fcb2', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 2, 2, 'For by this, the elders obtained testimony.'),
  ('99264761-6edd-570e-ad53-9f58bd673cb7', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 3, 3, 'By faith, we understand that the universe has been framed by the word of God, so that what is seen has not been made out of things which are visible.'),
  ('1d635ae7-4f64-583b-a4e5-f04accdadd7e', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 4, 4, 'By faith, Abel offered to God a more excellent sacrifice than Cain, through which he had testimony given to him that he was righteous, God testifying with respect to his gifts; and through it he, being dead, still speaks.'),
  ('9f2fab86-b90c-5062-a6a1-8be9a25abcf3', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 5, 5, 'By faith, Enoch was taken away, so that he wouldn''t see death, and he was not found, because God translated him. For he has had testimony given to him that before his translation he had been well pleasing to God.'),
  ('136e55fa-6092-5724-a06c-fa6ee750957f', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 6, 6, 'Without faith it is impossible to be well pleasing to him, for he who comes to God must believe that he exists, and that he is a rewarder of those who seek him.'),
  ('c5cd0e43-6107-5d2f-a594-2a7201230de9', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 7, 7, 'By faith, Noah, being warned about things not yet seen, moved with godly fear, prepared a ship for the saving of his house, through which he condemned the world, and became heir of the righteousness which is according to faith.'),
  ('37448f59-ea3c-5b23-ad00-170668d0e7c8', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 8, 8, 'By faith, Abraham, when he was called, obeyed to go out to the place which he was to receive for an inheritance. He went out, not knowing where he went.'),
  ('41bdf8bb-bd09-5158-a279-23916f6e1f3e', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 9, 9, 'By faith, he lived as an alien in the land of promise, as in a land not his own, dwelling in tents, with Isaac and Jacob, the heirs with him of the same promise.'),
  ('47de222e-4344-57a9-af0b-4b3ac0c68c21', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 10, 10, 'For he looked for the city which has the foundations, whose builder and maker is God.'),
  ('f01efdbe-555c-58ea-a025-8c6606235523', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 11, 11, 'By faith, even Sarah herself received power to conceive, and she bore a child when she was past age, since she counted him faithful who had promised.'),
  ('994fa00d-7e63-5878-accc-495bee04598a', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 12, 12, 'Therefore as many as the stars of the sky in multitude, and as innumerable as the sand which is by the sea shore, were fathered by one man, and him as good as dead.'),
  ('6a25eed2-0ed7-5e11-a17f-f355665fa4d5', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 13, 13, 'These all died in faith, not having received the promises, but having seen them and embraced them from afar, and having confessed that they were strangers and pilgrims on the earth.'),
  ('53761abc-06ab-5e11-a13e-45be941bdeee', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 14, 14, 'For those who say such things make it clear that they are seeking a country of their own.'),
  ('e22d3a54-bb90-5632-ae29-fd993e72feab', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 15, 15, 'If indeed they had been thinking of that country from which they went out, they would have had enough time to return.'),
  ('0a4eb6fe-e4a2-5596-ab0a-60bf26ebae10', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 16, 16, 'But now they desire a better country, that is, a heavenly one. Therefore God is not ashamed of them, to be called their God, for he has prepared a city for them.'),
  ('20aad4f0-e3ec-55ba-ae45-74c92c5f3f21', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 17, 17, 'By faith, Abraham, being tested, offered up Isaac. Yes, he who had gladly received the promises was offering up his one and only son;'),
  ('50c4b566-725c-528d-ac0e-15f499ca8dd0', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 18, 18, 'even he to whom it was said, "In Isaac will your seed be called;"'),
  ('466909ac-ae3c-503a-ace5-b69e8ba9bdbb', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 19, 19, 'concluding that God is able to raise up even from the dead. Figuratively speaking, he also did receive him back from the dead.'),
  ('2e0f53fe-35d7-59a5-ad6d-0dded923a5fb', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 20, 20, 'By faith, Isaac blessed Jacob and Esau, even concerning things to come.'),
  ('b091a6ba-45c2-5cb9-a80b-b609a5c5247f', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 21, 21, 'By faith, Jacob, when he was dying, blessed each of the sons of Joseph, and worshiped, leaning on the top of his staff.'),
  ('4ce29c28-ffba-565e-a8f3-1645c0e3ba13', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 22, 22, 'By faith, Joseph, when his end was near, made mention of the departure of the children of Israel; and gave instructions concerning his bones.'),
  ('15c6f37f-edcc-51aa-a919-04867b75d22e', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 23, 23, 'By faith, Moses, when he was born, was hidden for three months by his parents, because they saw that he was a beautiful child, and they were not afraid of the king''s commandment.'),
  ('9924d057-af0f-51c7-ad00-936434ebaa26', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 24, 24, 'By faith, Moses, when he had grown up, refused to be called the son of Pharaoh''s daughter,'),
  ('a8a82317-387d-583a-a53f-108f54b53824', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 25, 25, 'choosing rather to share ill treatment with God''s people, than to enjoy the pleasures of sin for a time;'),
  ('a1cbe6c5-1b33-5667-a97f-14dc34cf9157', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 26, 26, 'accounting the reproach of Christ greater riches than the treasures of Egypt; for he looked to the reward.'),
  ('09dbdb43-357b-58f5-aa53-afcd78e157c1', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 27, 27, 'By faith, he left Egypt, not fearing the wrath of the king; for he endured, as seeing him who is invisible.'),
  ('b158ab3e-731e-551e-ad45-00ec68bf6c7e', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 28, 28, 'By faith, he kept the Passover, and the sprinkling of the blood, that the destroyer of the firstborn should not touch them.'),
  ('06d0a492-25f9-55b1-a020-59488b313561', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 29, 29, 'By faith, they passed through the Red Sea as on dry land. When the Egyptians tried to do so, they were swallowed up.'),
  ('a91b67b1-56a9-5a33-aeee-62e409750515', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 30, 30, 'By faith, the walls of Jericho fell down, after they had been encircled for seven days.'),
  ('6bc849b8-2998-56a1-a36c-712166f5a0a8', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 31, 31, 'By faith, Rahab the prostitute, didn''t perish with those who were disobedient, having received the spies in peace.'),
  ('923a17c6-5ef1-5dc5-ada5-73fbdb58fa7d', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 32, 32, 'What more shall I say? For the time would fail me if I told of Gideon, Barak, Samson, Jephthah, David, Samuel, and the prophets;'),
  ('830212eb-f212-56de-a94c-5e1e1c142c2d', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 33, 33, 'who, through faith subdued kingdoms, worked out righteousness, obtained promises, stopped the mouths of lions,'),
  ('3163bae4-9def-5c68-a17f-f41b0bf0b96d', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 34, 34, 'quenched the power of fire, escaped the edge of the sword, from weakness were made strong, grew mighty in war, and caused foreign armies to flee.'),
  ('1ca78e53-0e45-5512-a944-288ea02b3b92', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 35, 35, 'Women received their dead by resurrection. Others were tortured, not accepting their deliverance, that they might obtain a better resurrection.'),
  ('5f3a3ed5-77f8-5e9f-a316-4f8b5c547ffb', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 36, 36, 'Others were tried by mocking and scourging, yes, moreover by bonds and imprisonment.'),
  ('d12eee64-e753-559e-aaa1-1b0c6c3b3984', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 37, 37, 'They were stoned. They were sawn apart. They were tempted. They were slain with the sword. They went around in sheep skins and in goat skins; being destitute, afflicted, ill-treated'),
  ('b8d6ff53-71c1-55f7-a54c-67c068f206d3', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 38, 38, '(of whom the world was not worthy), wandering in deserts, mountains, caves, and the holes of the earth.'),
  ('14d08f85-af44-5e26-a57b-ad10e13ff395', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 39, 39, 'These all, having had testimony given to them through their faith, didn''t receive the promise,'),
  ('65c31c24-618a-56a0-a023-09bb2a8f67bb', '6281e5c5-c275-539a-a117-ed72afbdfc15', NULL, 40, 40, 'God having provided some better thing concerning us, so that apart from us they should not be made perfect.'),
  ('0b75bb0a-12b1-5818-af3f-f0424ed260ac', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 1, 1, 'Therefore let us also, seeing we are surrounded by so great a cloud of witnesses, lay aside every weight and the sin which so easily entangles us, and let us run with patience the race that is set before us,'),
  ('b65eeedd-079a-50ee-a18f-535efb345266', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 2, 2, 'looking to Jesus, the author and perfecter of faith, who for the joy that was set before him endured the cross, despising its shame, and has sat down at the right hand of the throne of God.'),
  ('e22a5d39-2f1e-56e7-aea0-92007335c6ca', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 3, 3, 'For consider him who has endured such contradiction of sinners against himself, that you don''t grow weary, fainting in your souls.'),
  ('af2a586e-3e57-5b73-a4f5-34cbe8848f77', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 4, 4, 'You have not yet resisted to blood, striving against sin;'),
  ('6f8814e8-5fe4-5be9-a591-393c16b6f56b', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 5, 5, 'and you have forgotten the exhortation which reasons with you as with children, "My son, don''t take lightly the chastening of the Lord, nor faint when you are reproved by him;'),
  ('50b15448-ebcb-5f7b-a526-b5922a19a70a', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 6, 6, 'For whom the Lord loves, he chastens, and scourges every son whom he receives."'),
  ('c79cb497-0660-5bfc-aa65-d4fb950d84bd', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 7, 7, 'It is for discipline that you endure. God deals with you as with children, for what son is there whom his father doesn''t discipline?'),
  ('ded74e5f-8b2b-543d-a015-2e2d92d178d7', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 8, 8, 'But if you are without discipline, of which all have been made partakers, then are you illegitimate, and not children.'),
  ('783fcbee-bcfd-5352-aad8-386de0b5649f', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 9, 9, 'Furthermore, we had the fathers of our flesh to chasten us, and we paid them respect. Shall we not much rather be in subjection to the Father of spirits, and live?'),
  ('a58cb334-81d9-556c-abca-15f58ae9354e', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 10, 10, 'For they indeed, for a few days, punished us as seemed good to them; but he for our profit, that we may be partakers of his holiness.'),
  ('9f43e874-d14c-5834-a96a-f78363bcc37c', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 11, 11, 'All chastening seems for the present to be not joyous but grievous; yet afterward it yields the peaceful fruit of righteousness to those who have been exercised thereby.'),
  ('4cdb836c-e445-595f-a58b-ff0ca48b174a', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 12, 12, 'Therefore, lift up the hands that hang down and the feeble knees,'),
  ('03193ee8-4e72-5147-a0f0-596c2d253ca3', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 13, 13, 'and make straight paths for your feet, so that which is lame may not be dislocated, but rather be healed.'),
  ('de5761c2-2971-5602-afe8-66493bb4adeb', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 14, 14, 'Follow after peace with all men, and the sanctification without which no man will see the Lord,'),
  ('f07ea489-77e4-52b5-a89b-0bcda3664c78', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 15, 15, 'looking carefully lest there be any man who falls short of the grace of God; lest any root of bitterness springing up trouble you, and many be defiled by it;'),
  ('f497bdf8-04ed-5809-a854-b0ddea9f27cd', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 16, 16, 'lest there be any sexually immoral person, or profane person, like Esau, who sold his birthright for one meal.'),
  ('020e4280-c8bf-57ec-accb-0637ca8439ff', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 17, 17, 'For you know that even when he afterward desired to inherit the blessing, he was rejected, for he found no place for a change of mind though he sought it diligently with tears.'),
  ('5a5c742f-5e3d-5090-aaeb-d7b264aca997', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 18, 18, 'For you have not come to a mountain that might be touched, and that burned with fire, and to blackness, darkness, storm,'),
  ('225ceb40-4619-5808-ab0b-5d922c12e0c0', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 19, 19, 'the sound of a trumpet, and the voice of words; which those who heard it begged that not one more word should be spoken to them,'),
  ('0dfc9285-ce75-5abc-ac92-8c7c2ce4d771', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 20, 20, 'for they could not stand that which was commanded, "If even an animal touches the mountain, it shall be stoned;"'),
  ('632de5be-e759-5e39-a249-f5fc29017a5b', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 21, 21, 'and so fearful was the appearance, that Moses said, "I am terrified and trembling."'),
  ('b55347ed-4c6c-5097-a457-74ddd488ed00', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 22, 22, 'But you have come to Mount Zion, and to the city of the living God, the heavenly Jerusalem, and to innumerable multitudes of angels,'),
  ('0cac7f87-674e-56be-a94c-adf24469f426', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 23, 23, 'to the general assembly and assembly of the firstborn who are enrolled in heaven, to God the Judge of all, to the spirits of just men made perfect,'),
  ('c16b6136-b3ee-550f-a3f2-b17779e09cf0', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 24, 24, 'to Jesus, the mediator of a new covenant, and to the blood of sprinkling that speaks better than that of Abel.'),
  ('527a0776-2ab8-5b8f-a638-c8d3efc56a29', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 25, 25, 'See that you don''t refuse him who speaks. For if they didn''t escape when they refused him who warned on the Earth, how much more will we not escape who turn away from him who warns from heaven,'),
  ('48730da0-a563-5be4-a4be-3e3c780b1acf', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 26, 26, 'whose voice shook the earth then, but now he has promised, saying, "Yet once more I will shake not only the earth, but also the heavens."'),
  ('d4be433f-9500-5665-a448-3dfdd2bc4c25', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 27, 27, 'This phrase, "Yet once more," signifies the removing of those things that are shaken, as of things that have been made, that those things which are not shaken may remain.'),
  ('041363f8-aff7-5c69-ad01-8e52f5cffa57', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 28, 28, 'Therefore, receiving a Kingdom that can''t be shaken, let us have grace, through which we serve God acceptably, with reverence and awe,'),
  ('305f04a3-098e-528d-ab52-6053eda7efac', '0a8838b8-91e3-50eb-aa57-331cbab55759', NULL, 29, 29, 'for our God is a consuming fire.'),
  ('d17c4e0f-e9aa-51c8-a5dd-5a23ef5005ac', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 1, 1, 'Let brotherly love continue.'),
  ('9d1c143c-e937-572b-a6f4-14957c0a9abe', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 2, 2, 'Don''t forget to show hospitality to strangers, for in doing so, some have entertained angels without knowing it.'),
  ('4069b9b1-db20-5bab-a0cc-3dc1362428fb', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 3, 3, 'Remember those who are in bonds, as bound with them; and those who are ill-treated, since you are also in the body.'),
  ('2a58ceec-1b49-580c-a28e-06b7872f6581', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 4, 4, 'Let marriage be held in honor among all, and let the bed be undefiled: but God will judge the sexually immoral and adulterers.'),
  ('fdc8a457-45e2-5db3-ae30-73368bf7ea0c', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 5, 5, 'Be free from the love of money, content with such things as you have, for he has said, "I will in no way leave you, neither will I in any way forsake you."'),
  ('90fe5c72-a853-538b-a25c-7c177d3c94d7', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 6, 6, 'So that with good courage we say, "The Lord is my helper. I will not fear. What can man do to me?"'),
  ('824d6295-b3d7-5ad5-a125-75289b14086d', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 7, 7, 'Remember your leaders, men who spoke to you the word of God, and considering the results of their conduct, imitate their faith.'),
  ('bfa85cc5-ed04-5d0c-aa03-8aeb0b593537', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 8, 8, 'Jesus Christ is the same yesterday, today, and forever.'),
  ('4549f09e-9786-510a-aa2c-b0da00884d10', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 9, 9, 'Don''t be carried away by various and strange teachings, for it is good that the heart be established by grace, not by food, through which those who were so occupied were not benefited.'),
  ('13886d04-46eb-50e7-a7eb-e3628177af27', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 10, 10, 'We have an altar from which those who serve the holy tabernacle have no right to eat.'),
  ('0abdc12f-4784-5cbd-a7b7-030aa0514bdc', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 11, 11, 'For the bodies of those animals, whose blood is brought into the holy place by the high priest as an offering for sin, are burned outside of the camp.'),
  ('80dfd0fa-de8d-50ce-a979-f2a7cf644054', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 12, 12, 'Therefore Jesus also, that he might sanctify the people through his own blood, suffered outside of the gate.'),
  ('ecb49829-dd9e-5141-a2ee-f250496d5ba6', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 13, 13, 'Let us therefore go out to him outside of the camp, bearing his reproach.'),
  ('c384ef95-2487-55d0-ae22-07f4e0bc69f6', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 14, 14, 'For we don''t have here an enduring city, but we seek that which is to come.'),
  ('b350b494-2818-5064-aed9-a8bfdae823df', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 15, 15, 'Through him, then, let us offer up a sacrifice of praise to God continually, that is, the fruit of lips which proclaim allegiance to his name.'),
  ('04ce2da6-8fec-5372-a608-3d86ccfa086a', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 16, 16, 'But don''t forget to be doing good and sharing, for with such sacrifices God is well pleased.'),
  ('96b807cd-0935-5003-ac93-cdb80d7222c0', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 17, 17, 'Obey your leaders and submit to them, for they watch on behalf of your souls, as those who will give account, that they may do this with joy, and not with groaning, for that would be unprofitable for you.'),
  ('c8b79592-3471-576b-a9e7-1499fa172a18', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 18, 18, 'Pray for us, for we are persuaded that we have a good conscience, desiring to live honorably in all things.'),
  ('a01d55e5-52fe-5292-a4b0-61feb4501ecd', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 19, 19, 'I strongly urge you to do this, that I may be restored to you sooner.'),
  ('9cd57e7e-3286-5343-a926-e3089147e962', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 20, 20, 'Now may the God of peace, who brought again from the dead the great shepherd of the sheep with the blood of an eternal covenant, our Lord Jesus,'),
  ('242d2a50-d779-537c-ad5d-5bc5fc825c82', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 21, 21, 'make you complete in every good work to do his will, working in you that which is well pleasing in his sight, through Jesus Christ, to whom be the glory forever and ever. Amen.'),
  ('ee474cbc-e2cd-568f-aff0-55820e512197', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 22, 22, 'But I exhort you, brothers, endure the word of exhortation, for I have written to you in few words.'),
  ('9a522287-adef-5321-ab77-15c0b67290b1', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 23, 23, 'Know that our brother Timothy has been freed, with whom, if he comes shortly, I will see you.'),
  ('556e5fcb-c13c-58b3-a588-876378ce885e', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 24, 24, 'Greet all of your leaders and all the saints. The Italians greet you.'),
  ('fa5a0ee4-5ce8-5eb2-afd4-30631d653a08', 'ac4bba1a-fb62-5770-a490-fb63e9eec2c4', NULL, 25, 25, 'Grace be with you all. Amen.'),
  ('d1649fc6-db26-5ead-ad03-1ca0926cad77', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 1, 1, 'James, a servant of God and of the Lord Jesus Christ, to the twelve tribes which are in the Dispersion: Greetings.'),
  ('9e2afc2d-8f4c-5c32-a92b-86d309e89aea', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 2, 2, 'Count it all joy, my brothers, when you fall into various temptations,'),
  ('feca9d4f-e612-58f4-a0be-1568e0316ceb', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 3, 3, 'knowing that the testing of your faith produces endurance.'),
  ('7e395e21-78e8-5fdd-ab5e-7a24e8e17f2f', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 4, 4, 'Let endurance have its perfect work, that you may be perfect and complete, lacking in nothing.'),
  ('de6e8ef6-bc8f-5b8b-a0c0-f05fc12018cc', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 5, 5, 'But if any of you lacks wisdom, let him ask of God, who gives to all liberally and without reproach; and it will be given to him.'),
  ('784c04c1-eecf-54d1-adc5-ea4c7d60966a', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 6, 6, 'But let him ask in faith, without any doubting, for he who doubts is like a wave of the sea, driven by the wind and tossed.'),
  ('dbf4b40d-6d4a-54c8-a5ac-06a92379f1b9', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 7, 7, 'For let that man not think that he will receive anything from the Lord.'),
  ('a1b708d0-2406-56b5-a6b7-38234fe0ec59', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 8, 8, 'He is a double-minded man, unstable in all his ways.'),
  ('bb332075-67bf-58a6-a086-e069282065a1', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 9, 9, 'But let the brother in humble circumstances glory in his high position;'),
  ('fa32f797-12b6-5a52-a38a-a109d1e0c5d5', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 10, 10, 'and the rich, in that he is made humble, because like the flower in the grass, he will pass away.'),
  ('36ecb6e1-df92-5b68-a943-e112253d01b4', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 11, 11, 'For the sun arises with the scorching wind, and withers the grass, and the flower in it falls, and the beauty of its appearance perishes. So also will the rich man fade away in his pursuits.'),
  ('9ce7f83d-6d5d-5e40-a418-5e57fad013d3', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 12, 12, 'Blessed is the man who endures temptation, for when he has been approved, he will receive the crown of life, which the Lord promised to those who love him.'),
  ('51716c03-30e1-547e-a179-ca9ebebcf663', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 13, 13, 'Let no man say when he is tempted, "I am tempted by God," for God can''t be tempted by evil, and he himself tempts no one.'),
  ('12d5cafa-5bbd-53ee-a8fe-5d78aa3d4a64', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 14, 14, 'But each one is tempted, when he is drawn away by his own lust, and enticed.'),
  ('7da9b521-e8e6-5596-adce-fce5f17a36c4', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 15, 15, 'Then the lust, when it has conceived, bears sin; and the sin, when it is full grown, brings forth death.'),
  ('eefa38a8-40c2-5888-a0af-92b7cac08da7', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 16, 16, 'Don''t be deceived, my beloved brothers.'),
  ('cdeca3f6-0f8e-5926-a3de-f44e5c407dd7', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 17, 17, 'Every good gift and every perfect gift is from above, coming down from the Father of lights, with whom can be no variation, nor turning shadow.'),
  ('d6e6cd5d-b72a-5e9d-aecc-29e70bcad72a', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 18, 18, 'Of his own will he brought us forth by the word of truth, that we should be a kind of first fruits of his creatures.'),
  ('3743b8ba-d15d-5eae-aad0-41770116366f', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 19, 19, 'So, then, my beloved brothers, let every man be swift to hear, slow to speak, and slow to anger;'),
  ('ab940ce6-b130-5579-a25c-7aa18b8cffbb', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 20, 20, 'for the anger of man doesn''t produce the righteousness of God.'),
  ('039fe7c6-98e9-5556-a58f-25cf556ce219', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 21, 21, 'Therefore, putting away all filthiness and overflowing of wickedness, receive with humility the implanted word, which is able to save your souls.'),
  ('b2aac6df-65e6-5cc8-a1e3-a6dff3d31b58', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 22, 22, 'But be doers of the word, and not only hearers, deluding your own selves.'),
  ('7d171213-8824-503b-a41f-f685cd1d3add', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 23, 23, 'For if anyone is a hearer of the word and not a doer, he is like a man looking at his natural face in a mirror;'),
  ('e88ac0e9-80a7-5106-af13-dd4897f95ef6', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 24, 24, 'for he sees himself, and goes away, and immediately forgets what kind of man he was.'),
  ('06f40dc5-7686-563d-a8fc-8685c91fa312', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 25, 25, 'But he who looks into the perfect law of freedom, and continues, not being a hearer who forgets, but a doer of the work, this man will be blessed in what he does.'),
  ('309ad77d-550b-5b3b-ab72-6782133f03aa', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 26, 26, 'If anyone among you thinks himself to be religious while he doesn''t bridle his tongue, but deceives his heart, this man''s religion is worthless.'),
  ('29e26b49-ad6b-5ea0-ab83-5a5da5d6d663', 'fe4e67e4-9723-5fac-a4ef-6bf7a3308544', NULL, 27, 27, 'Pure religion and undefiled before our God and Father is this: to visit the fatherless and widows in their affliction, and to keep oneself unstained by the world.'),
  ('62a1b923-5e3c-5bd9-a02d-4ca5cb3d3632', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 1, 1, 'My brothers, don''t hold the faith of our Lord Jesus Christ of glory with partiality.'),
  ('1eab6f5b-4762-5992-ac87-0d4e441874b7', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 2, 2, 'For if a man with a gold ring, in fine clothing, comes into your synagogue, and a poor man in filthy clothing also comes in;'),
  ('c7a5b9a2-1c34-58c6-afc9-529e93e0a14c', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 3, 3, 'and you pay special attention to him who wears the fine clothing, and say, "Sit here in a good place;" and you tell the poor man, "Stand there," or "Sit by my footstool;"'),
  ('b43e90e6-ead3-5377-ade5-ff842cb4d17c', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 4, 4, 'haven''t you shown partiality among yourselves, and become judges with evil thoughts?'),
  ('d83fd89b-3851-5f67-a764-b7f86b868a17', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 5, 5, 'Listen, my beloved brothers. Didn''t God choose those who are poor in this world to be rich in faith, and heirs of the Kingdom which he promised to those who love him?'),
  ('932b8d49-c794-52d7-a253-737e88f644b1', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 6, 6, 'But you have dishonored the poor man. Don''t the rich oppress you, and personally drag you before the courts?'),
  ('044bf42f-cc97-5def-a2e0-30f0b641687e', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 7, 7, 'Don''t they blaspheme the honorable name by which you are called?'),
  ('fb000fb8-27a7-598c-acc3-719cc34da99c', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 8, 8, 'However, if you fulfill the royal law, according to the Scripture, "You shall love your neighbor as yourself," you do well.'),
  ('1f6a3f67-26aa-5ac4-a0d9-39dc196ac8a5', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 9, 9, 'But if you show partiality, you commit sin, being convicted by the law as transgressors.'),
  ('6ca3bbca-1006-5dee-a807-186367adef37', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 10, 10, 'For whoever keeps the whole law, and yet stumbles in one point, he has become guilty of all.'),
  ('ba229e83-d25b-598a-a516-7b666a679ee0', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 11, 11, 'For he who said, "Do not commit adultery," also said, "Do not commit murder." Now if you do not commit adultery, but murder, you have become a transgressor of the law.'),
  ('2a88c2a0-fafc-50b1-a66a-0dec1d40af47', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 12, 12, 'So speak, and so do, as men who are to be judged by a law of freedom.'),
  ('25f31354-4488-5fad-ae51-c4b98d0aa1ba', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 13, 13, 'For judgment is without mercy to him who has shown no mercy. Mercy triumphs over judgment.'),
  ('f46f7840-e89e-5b66-a63f-4cc467b4e598', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 14, 14, 'What good is it, my brothers, if a man says he has faith, but has no works? Can faith save him?'),
  ('01dfc040-90dd-5448-a45c-919dfe3c5ce5', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 15, 15, 'And if a brother or sister is naked and in lack of daily food,'),
  ('9f255485-3800-5a90-a0eb-c521252598da', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 16, 16, 'and one of you tells them, "Go in peace, be warmed and filled;" and yet you didn''t give them the things the body needs, what good is it?'),
  ('639e9a64-7a6c-5c7c-a506-53c888922148', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 17, 17, 'Even so faith, if it has no works, is dead in itself.'),
  ('13ff6a41-e006-59dd-a235-6739ec50c378', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 18, 18, 'Yes, a man will say, "You have faith, and I have works." Show me your faith without works, and I by my works will show you my faith.'),
  ('d01aca0c-4479-5b7a-a100-6920b9c00bcb', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 19, 19, 'You believe that God is one. You do well. The demons also believe, and shudder.'),
  ('f0e96e96-758c-5b0e-a967-80130308acd9', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 20, 20, 'But do you want to know, vain man, that faith apart from works is dead?'),
  ('5e262312-1190-54dd-a2a7-d7950e773fb8', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 21, 21, 'Wasn''t Abraham our father justified by works, in that he offered up Isaac his son on the altar?'),
  ('a3268b29-05e3-5b86-a48f-8b5e7356ff34', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 22, 22, 'You see that faith worked with his works, and by works faith was perfected;'),
  ('721b91d7-d382-50b4-a160-39d0b672340e', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 23, 23, 'and the Scripture was fulfilled which says, "Abraham believed God, and it was accounted to him as righteousness;" and he was called the friend of God.'),
  ('6d9b1bb9-f40d-51d1-a258-e19d95774776', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 24, 24, 'You see then that by works, a man is justified, and not only by faith.'),
  ('edab3bab-46e8-54fd-aed3-9e6ca6baa054', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 25, 25, 'In the same way, wasn''t Rahab the prostitute also justified by works, in that she received the messengers, and sent them out another way?'),
  ('1696de08-b7d8-58fe-a13e-e76550e9e9a6', '4b8e1e1c-e403-5036-ae3e-7a203ae4caf6', NULL, 26, 26, 'For as the body apart from the spirit is dead, even so faith apart from works is dead.'),
  ('49c333f5-68fa-534f-a5dd-99b6e4edbeec', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 1, 1, 'Let not many of you be teachers, my brothers, knowing that we will receive heavier judgment.'),
  ('c717be1c-2483-5cca-a4fd-6b71ca154268', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 2, 2, 'For in many things we all stumble. If anyone doesn''t stumble in word, the same is a perfect man, able to bridle the whole body also.'),
  ('b6b9e4cf-4528-5dbf-aa10-fd007852b4f5', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 3, 3, 'Indeed, we put bits into the horses'' mouths so that they may obey us, and we guide their whole body.'),
  ('534f4ca8-9e31-5db2-a0b7-7bb0187bb029', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 4, 4, 'Behold, the ships also, though they are so big and are driven by fierce winds, are yet guided by a very small rudder, wherever the pilot desires.'),
  ('fa77cae8-fe05-5806-a980-4f681dec543b', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 5, 5, 'So the tongue is also a little member, and boasts great things. See how a small fire can spread to a large forest!'),
  ('1b70ff80-cb2f-58f6-a9ed-344bf41886a1', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 6, 6, 'And the tongue is a fire. The world of iniquity among our members is the tongue, which defiles the whole body, and sets on fire the course of nature, and is set on fire by Gehenna.'),
  ('800df69f-3048-5b7d-afde-fb894fef8c50', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 7, 7, 'For every kind of animal, bird, creeping thing, and thing in the sea, is tamed, and has been tamed by mankind.'),
  ('94e7d71f-e4d6-5c97-abad-36f2494b63c5', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 8, 8, 'But nobody can tame the tongue. It is a restless evil, full of deadly poison.'),
  ('db686e9c-593f-53ef-a58c-dedd73758a2c', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 9, 9, 'With it we bless our God and Father, and with it we curse men, who are made in the image of God.'),
  ('1c664fbe-2afe-5551-a5a8-443b3a156e05', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 10, 10, 'Out of the same mouth comes forth blessing and cursing. My brothers, these things ought not to be so.'),
  ('ffaecdc9-15bc-56d3-adb1-25c607d86e2a', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 11, 11, 'Does a spring send out from the same opening fresh and bitter water?'),
  ('07333fb1-ff76-5807-ac6d-4b1598fb2e3f', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 12, 12, 'Can a fig tree, my brothers, yield olives, or a vine figs? Thus no spring yields both salt water and fresh water.'),
  ('1cc875ca-2d54-55d5-a939-199fe921121a', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 13, 13, 'Who is wise and understanding among you? Let him show by his good conduct that his deeds are done in gentleness of wisdom.'),
  ('eb8ddc4a-f27c-5b03-abe5-da3d2cb9b6f0', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 14, 14, 'But if you have bitter jealousy and selfish ambition in your heart, don''t boast and don''t lie against the truth.'),
  ('366901d0-9362-5588-a887-4829144ec219', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 15, 15, 'This wisdom is not that which comes down from above, but is earthly, sensual, and demonic.'),
  ('3d7c07cc-4237-5323-a0fa-6e433c8ea66e', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 16, 16, 'For where jealousy and selfish ambition are, there is confusion and every evil deed.'),
  ('8fa14c77-5917-5f4f-acb3-402c5c01c3e7', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 17, 17, 'But the wisdom that is from above is first pure, then peaceful, gentle, reasonable, full of mercy and good fruits, without partiality, and without hypocrisy.'),
  ('d798667c-c4a1-5e5a-a174-2f30a095d292', '6ba97492-0929-53c9-ad2b-8a26db5df7b2', NULL, 18, 18, 'Now the fruit of righteousness is sown in peace by those who make peace.'),
  ('6e8de633-d590-5a38-a763-4ad6dec502cc', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 1, 1, 'Where do wars and fightings among you come from? Don''t they come from your pleasures that war in your members?'),
  ('a591ec5c-7b4b-5fb5-a7ef-35936599575e', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 2, 2, 'You lust, and don''t have. You kill, covet, and can''t obtain. You fight and make war. You don''t have, because you don''t ask.'),
  ('7a318037-5068-56ee-a8e0-31b5782d0204', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 3, 3, 'You ask, and don''t receive, because you ask with wrong motives, so that you may spend it for your pleasures.'),
  ('910ca759-b01e-567b-ac06-f7c156ac6137', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 4, 4, 'You adulterers and adulteresses, don''t you know that friendship with the world is enmity with God? Whoever therefore wants to be a friend of the world makes himself an enemy of God.'),
  ('a8c6d177-4141-5285-a22a-d62634f5aeff', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 5, 5, 'Or do you think that the Scripture says in vain, "The Spirit who lives in us yearns jealously"?'),
  ('dba94533-2d25-51d7-a8b2-428aa6505c74', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 6, 6, 'But he gives more grace. Therefore it says, "God resists the proud, but gives grace to the humble."'),
  ('543ac751-1fa3-5d43-a8e3-c46b5cb798a6', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 7, 7, 'Be subject therefore to God. But resist the devil, and he will flee from you.'),
  ('e4814595-0296-5088-a61c-f7fde0bc46f1', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 8, 8, 'Draw near to God, and he will draw near to you. Cleanse your hands, you sinners; and purify your hearts, you double-minded.'),
  ('d7323840-13c1-5d27-ad1f-be01f5d0e402', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 9, 9, 'Lament, mourn, and weep. Let your laughter be turned to mourning, and your joy to gloom.'),
  ('8119b125-a8a4-53ba-ac46-ef7a16f55cb9', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 10, 10, 'Humble yourselves in the sight of the Lord, and he will exalt you.'),
  ('19b5037d-2d96-5106-ad55-1f67bd85feba', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 11, 11, 'Don''t speak against one another, brothers. He who speaks against a brother and judges his brother, speaks against the law and judges the law. But if you judge the law, you are not a doer of the law, but a judge.'),
  ('ece87dcc-ab8f-5001-a72c-d5adb6fb30e5', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 12, 12, 'Only one is the lawgiver, who is able to save and to destroy. But who are you to judge another?'),
  ('29104d02-819c-53f1-a31e-adf85af8a4f5', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 13, 13, 'Come now, you who say, "Today or tomorrow let''s go into this city, and spend a year there, trade, and make a profit."'),
  ('6274d000-3ff0-5011-a999-6a87ede8ec4b', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 14, 14, 'Whereas you don''t know what your life will be like tomorrow. For what is your life? For you are a vapor, that appears for a little time, and then vanishes away.'),
  ('f9cac5f2-57d4-5689-a637-d0068a9c7901', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 15, 15, 'For you ought to say, "If the Lord wills, we will both live, and do this or that."'),
  ('507cdc3b-4f62-5400-af50-3e1df4f7dc09', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 16, 16, 'But now you glory in your boasting. All such boasting is evil.'),
  ('65422a28-af5a-5028-a343-fcd747ae1e30', 'df2d5d4f-b3a0-5ae7-acbc-e8f750625ba1', NULL, 17, 17, 'To him therefore who knows to do good, and doesn''t do it, to him it is sin.'),
  ('4e37a77c-43de-5b2d-a206-5de24fa7b879', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 1, 1, 'Come now, you rich, weep and howl for your miseries that are coming on you.'),
  ('7e0b104f-30bd-5e09-a2b9-354766e330a4', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 2, 2, 'Your riches are corrupted and your garments are moth-eaten.'),
  ('9acbf9ac-f047-5f97-a12b-eb8e4cd634ed', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 3, 3, 'Your gold and your silver are corroded, and their corrosion will be for a testimony against you, and will eat your flesh like fire. You have laid up your treasure in the last days.'),
  ('2a0c0d8c-fe64-50c0-a000-52a7aa588472', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 4, 4, 'Behold, the wages of the laborers who mowed your fields, which you have kept back by fraud, cry out, and the cries of those who reaped have entered into the ears of the Lord of Armies.'),
  ('602bf973-0e83-5a6d-ab88-b1140e74b12c', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 5, 5, 'You have lived delicately on the earth, and taken your pleasure. You have nourished your hearts as in a day of slaughter.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('338e725b-3478-5249-a018-775241a59d67', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 6, 6, 'You have condemned, you have murdered the righteous one. He doesn''t resist you.'),
  ('918935fb-8af8-5e01-a3fe-8e73d1bea4d4', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 7, 7, 'Be patient therefore, brothers, until the coming of the Lord. Behold, the farmer waits for the precious fruit of the earth, being patient over it, until it receives the early and late rain.'),
  ('32caf216-009d-5ea2-a0d1-5a5ea1e5760c', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 8, 8, 'You also be patient. Establish your hearts, for the coming of the Lord is at hand.'),
  ('8a06429a-3ed3-5c44-a2b2-673d9d354043', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 9, 9, 'Don''t grumble, brothers, against one another, so that you won''t be judged. Behold, the judge stands at the door.'),
  ('61f518de-f4e7-5bb6-a57e-667eff97ee64', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 10, 10, 'Take, brothers, for an example of suffering and of patience, the prophets who spoke in the name of the Lord.'),
  ('f03a9842-1fa3-5231-ab3a-16178ea3ec5b', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 11, 11, 'Behold, we call them blessed who endured. You have heard of the patience of Job, and have seen the Lord in the outcome, and how the Lord is full of compassion and mercy.'),
  ('477152af-97ff-5838-af3b-b40715db45e5', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 12, 12, 'But above all things, my brothers, don''t swear, neither by heaven, nor by the earth, nor by any other oath; but let your "yes" be "yes," and your "no," "no;" so that you don''t fall into hypocrisy.'),
  ('4fd0c30d-d29d-514d-ae45-e2a466a0fe61', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 13, 13, 'Is any among you suffering? Let him pray. Is any cheerful? Let him sing praises.'),
  ('0742e62e-1faa-5aba-ac7b-d45a46195fe3', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 14, 14, 'Is any among you sick? Let him call for the elders of the assembly, and let them pray over him, anointing him with oil in the name of the Lord,'),
  ('69a6206f-c4de-516d-ad65-2cb5eb6a37f4', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 15, 15, 'and the prayer of faith will heal him who is sick, and the Lord will raise him up. If he has committed sins, he will be forgiven.'),
  ('acafbe9d-77ec-5f32-a18b-0548380c8633', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 16, 16, 'Confess your offenses to one another, and pray for one another, that you may be healed. The insistent prayer of a righteous person is powerfully effective.'),
  ('c27fe4b1-542d-52b0-a495-0fa66c1cef68', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 17, 17, 'Elijah was a man with a nature like ours, and he prayed earnestly that it might not rain, and it didn''t rain on the earth for three years and six months.'),
  ('6ae9d4c4-deb8-55eb-a1bb-04142c5da7b3', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 18, 18, 'He prayed again, and the sky gave rain, and the earth brought forth its fruit.'),
  ('a77b5ca5-e3db-5cb0-a95e-925bf38899b1', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 19, 19, 'Brothers, if any among you wanders from the truth, and someone turns him back,'),
  ('db96931a-18b2-52d3-aaf2-f13c04c818a6', 'eb2492b0-fd87-5030-a54b-b7ee16b72aaa', NULL, 20, 20, 'let him know that he who turns a sinner from the error of his way will save a soul from death, and will cover a multitude of sins.'),
  ('08b08f38-49e4-5a0f-a52a-e51cf1d0802b', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 1, 1, 'Peter, an apostle of Jesus Christ, to the chosen ones who are living as foreigners in the Dispersion in Pontus, Galatia, Cappadocia, Asia, and Bithynia,'),
  ('aeebacc2-73f5-51e7-a9ef-37cf61144649', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 2, 2, 'according to the foreknowledge of God the Father, in sanctification of the Spirit, that you may obey Jesus Christ and be sprinkled with his blood: Grace to you and peace be multiplied.'),
  ('4334597c-d76b-5a66-a5d1-c7fc7c47c6c3', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 3, 3, 'Blessed be the God and Father of our Lord Jesus Christ, who according to his great mercy became our father again to a living hope through the resurrection of Jesus Christ from the dead,'),
  ('a1f28931-491d-5962-a35c-4747ec7110cf', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 4, 4, 'to an incorruptible and undefiled inheritance that doesn''t fade away, reserved in Heaven for you,'),
  ('f8ef037c-09d7-58b2-ad14-ce8dd23c941b', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 5, 5, 'who by the power of God are guarded through faith for a salvation ready to be revealed in the last time.'),
  ('4b841b6c-4f4e-5db9-a7b9-20eaff61e987', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 6, 6, 'Wherein you greatly rejoice, though now for a little while, if need be, you have been put to grief in various trials,'),
  ('89b6666b-9972-501c-aaa8-4fb04f3ebe92', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 7, 7, 'that the proof of your faith, which is more precious than gold that perishes even though it is tested by fire, may be found to result in praise, glory, and honor at the revelation of Jesus Christ--'),
  ('74c5fe6f-899f-5ac6-ab92-0bff1ec1fc98', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 8, 8, 'whom not having known you love; in whom, though now you don''t see him, yet believing, you rejoice greatly with joy unspeakable and full of glory--'),
  ('5230389f-05ea-528a-ae90-b4f168ec9bf8', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 9, 9, 'receiving the result of your faith, the salvation of your souls.'),
  ('b4473f0c-9b42-5c9b-a9b7-d5a939126276', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 10, 10, 'Concerning this salvation, the prophets sought and searched diligently, who prophesied of the grace that would come to you,'),
  ('6e9cf6ba-f0e0-51b3-aa37-6bbab23013f3', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 11, 11, 'searching for who or what kind of time the Spirit of Christ, which was in them, pointed to, when he predicted the sufferings of Christ, and the glories that would follow them.'),
  ('27ae8044-67ee-5702-a660-40bc7da01b37', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 12, 12, 'To them it was revealed, that not to themselves, but to you, they ministered these things, which now have been announced to you through those who preached the Good News to you by the Holy Spirit sent out from heaven; which things angels desire to look into.'),
  ('0aa1f5f2-c85c-5e86-a0dd-7ba1c83a4cc4', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 13, 13, 'Therefore, prepare your minds for action, be sober and set your hope fully on the grace that will be brought to you at the revelation of Jesus Christ--'),
  ('323f7af6-a7b5-5bdf-a8cd-71bc37b159ed', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 14, 14, 'as children of obedience, not conforming yourselves according to your former lusts as in your ignorance,'),
  ('82a091bc-dbfd-5590-abfa-bde44fec239a', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 15, 15, 'but just as he who called you is holy, you yourselves also be holy in all of your behavior;'),
  ('1504033e-d535-57b2-a40e-f85a2ecc181b', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 16, 16, 'because it is written, "You shall be holy; for I am holy."'),
  ('dc60777b-9075-5517-a96d-09bf35ffd6f0', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 17, 17, 'If you call on him as Father, who without respect of persons judges according to each man''s work, pass the time of your living as foreigners here in reverent fear:'),
  ('728e1d08-c0be-52e1-ab7a-f2f4bdb05ac4', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 18, 18, 'knowing that you were redeemed, not with corruptible things, with silver or gold, from the useless way of life handed down from your fathers,'),
  ('a366afc5-d9a1-505f-aa8e-9ac70b85cc78', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 19, 19, 'but with precious blood, as of a faultless and pure lamb, the blood of Christ;'),
  ('ec584868-17da-598a-a240-7b2e9e994bd8', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 20, 20, 'who was foreknown indeed before the foundation of the world, but was revealed at the end of times for your sake,'),
  ('309089de-f6c2-5999-a929-0625dca5bc3d', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 21, 21, 'who through him are believers in God, who raised him from the dead, and gave him glory; so that your faith and hope might be in God.'),
  ('4e1bfaae-82c0-5d6f-a9a0-770d40a43c6c', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 22, 22, 'Seeing you have purified your souls in your obedience to the truth through the Spirit in sincere brotherly affection, love one another from the heart fervently:'),
  ('fbc0c793-3d84-5067-ae41-5c1b0b3ad3aa', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 23, 23, 'having been born again, not of corruptible seed, but of incorruptible, through the word of God, which lives and remains forever.'),
  ('5e6af1b5-7b4e-5c8b-a8ac-a10c67df75cd', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 24, 24, 'For, "All flesh is like grass, and all of man''s glory like the flower in the grass. The grass withers, and its flower falls;'),
  ('5a15bfe8-02b2-5310-ad8c-731c8ad1e1e2', '56d5b470-4711-5b27-a3d7-1bd18329bce1', NULL, 25, 25, 'but the Lord''s word endures forever." This is the word of Good News which was preached to you.'),
  ('fa910bbf-d01f-5814-a946-f90ade9c288f', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 1, 1, 'Putting away therefore all wickedness, all deceit, hypocrisies, envies, and all evil speaking,'),
  ('8b2cabaf-ddd8-53cd-aa95-46d6739254cc', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 2, 2, 'as newborn babies, long for the pure milk of the Word, that you may grow thereby,'),
  ('c295cb28-b6fd-5c35-a694-1a6396ec1d0d', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 3, 3, 'if indeed you have tasted that the Lord is gracious:'),
  ('e4546876-144e-5e6a-a195-eb1da7717fd1', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 4, 4, 'coming to him, a living stone, rejected indeed by men, but chosen by God, precious.'),
  ('3c5e62fc-2e57-52a6-ada8-656893c1189f', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 5, 5, 'You also, as living stones, are built up as a spiritual house, to be a holy priesthood, to offer up spiritual sacrifices, acceptable to God through Jesus Christ.'),
  ('7d4d6148-1d76-58c4-ae5e-dfdced738585', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 6, 6, 'Because it is contained in Scripture, "Behold, I lay in Zion a chief cornerstone, chosen, and precious: He who believes in him will not be disappointed."'),
  ('3ff13d87-cd14-5852-ab6c-47fcfa0abc6c', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 7, 7, 'For you who believe therefore is the honor, but for those who are disobedient, "The stone which the builders rejected, has become the chief cornerstone,"'),
  ('1c3b62c0-25b6-50e4-a319-f872bbddfd4b', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 8, 8, 'and, "a stone of stumbling, and a rock of offense." For they stumble at the word, being disobedient, to which also they were appointed.'),
  ('8d9778cd-f851-580a-ab1d-4e90f02b3313', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 9, 9, 'But you are a chosen race, a royal priesthood, a holy nation, a people for God''s own possession, that you may proclaim the excellence of him who called you out of darkness into his marvelous light:'),
  ('ff0216eb-1444-53b3-aa89-6a0cb13cfaa6', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 10, 10, 'who in time past were no people, but now are God''s people, who had not obtained mercy, but now have obtained mercy.'),
  ('ff12dafd-1cec-58f8-a609-cbcaacf8593a', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 11, 11, 'Beloved, I beg you as foreigners and pilgrims, to abstain from fleshly lusts, which war against the soul;'),
  ('b2ba0355-2f3c-539e-acdb-610dad74fe23', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 12, 12, 'having good behavior among the nations, so in that of which they speak against you as evildoers, they may by your good works, which they see, glorify God in the day of visitation.'),
  ('767e4148-5b0c-5dd4-aca2-fb557c79d3e0', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 13, 13, 'Therefore subject yourselves to every ordinance of man for the Lord''s sake: whether to the king, as supreme;'),
  ('6254ca22-9faf-53cc-a76f-2061fdcaa5b8', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 14, 14, 'or to governors, as sent by him for vengeance on evildoers and for praise to those who do well.'),
  ('0ff8e91b-85cb-5e7f-ae84-97cea863c429', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 15, 15, 'For this is the will of God, that by well-doing you should put to silence the ignorance of foolish men:'),
  ('310d363b-0c93-5c38-a539-6897d8c97417', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 16, 16, 'as free, and not using your freedom for a cloak of wickedness, but as bondservants of God.'),
  ('85a47f26-84fc-579a-ad37-b0ee3e81c6a0', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 17, 17, 'Honor all men. Love the brotherhood. Fear God. Honor the king.'),
  ('ed63a400-e0f3-55a0-ab67-e1b3d0b8e463', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 18, 18, 'Servants, be in subjection to your masters with all fear; not only to the good and gentle, but also to the wicked.'),
  ('95407261-7fec-5ab2-a513-5261c8a8bd1a', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 19, 19, 'For it is commendable if someone endures pain, suffering unjustly, because of conscience toward God.'),
  ('096dd5c3-c20c-54e9-a600-562a20e33b49', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 20, 20, 'For what glory is it if, when you sin, you patiently endure beating? But if, when you do well, you patiently endure suffering, this is commendable with God.'),
  ('78f4a7ea-f253-56e0-a95e-3e9f6bfb86b8', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 21, 21, 'For to this you were called, because Christ also suffered for us, leaving you an example, that you should follow his steps,'),
  ('8d9ac4b0-f540-5a13-a6e3-4f46e8c8bd72', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 22, 22, 'who did not sin, "neither was deceit found in his mouth."'),
  ('d38dbd46-21bf-5ab3-a1e6-6e16e9301b35', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 23, 23, 'Who, when he was cursed, didn''t curse back. When he suffered, didn''t threaten, but committed himself to him who judges righteously;'),
  ('1074017c-c72e-54c1-aa28-8637c1cae356', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 24, 24, 'who his own self bore our sins in his body on the tree, that we, having died to sins, might live to righteousness; by whose stripes you were healed.'),
  ('17a4d9e0-39d2-5d06-afae-172059df8fab', '31f4bf43-1247-5982-a79b-03d636c341ba', NULL, 25, 25, 'For you were going astray like sheep; but now have returned to the Shepherd and Overseer of your souls.'),
  ('92dd2f97-22d7-5f83-aaf4-1c04121fab36', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 1, 1, 'In the same way, wives, be in subjection to your own husbands; so that, even if any don''t obey the Word, they may be won by the behavior of their wives without a word;'),
  ('c42682ff-a072-5142-a08f-7fe87387d4a9', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 2, 2, 'seeing your pure behavior in fear.'),
  ('bd0b7926-8d0f-590d-a217-ad1c206f8ee6', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 3, 3, 'Let your beauty be not just the outward adorning of braiding the hair, and of wearing jewels of gold, or of putting on fine clothing;'),
  ('bfcae797-2e8d-5909-a3d8-1bf90b3a7869', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 4, 4, 'but in the hidden person of the heart, in the incorruptible adornment of a gentle and quiet spirit, which is in the sight of God very precious.'),
  ('93b701e1-f719-5a44-aed3-d739a8e203f0', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 5, 5, 'For this is how the holy women before, who hoped in God also adorned themselves, being in subjection to their own husbands:'),
  ('dc8a4438-b76c-52f9-ab88-d2927dca034b', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 6, 6, 'as Sarah obeyed Abraham, calling him lord, whose children you now are, if you do well, and are not put in fear by any terror.'),
  ('5b45cb4a-0866-54ae-a9c9-9c10bbd12af2', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 7, 7, 'You husbands, in the same way, live with your wives according to knowledge, giving honor to the woman, as to the weaker vessel, as being also joint heirs of the grace of life; that your prayers may not be hindered.'),
  ('cb60a224-df93-5d25-a676-90294131d381', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 8, 8, 'Finally, be all like-minded, compassionate, loving as brothers, tenderhearted, courteous,'),
  ('3be3c0b0-7e96-587f-ad14-37f2d9640219', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 9, 9, 'not rendering evil for evil, or insult for insult; but instead blessing; knowing that to this were you called, that you may inherit a blessing.'),
  ('88e1ae17-297d-5bb7-aa4f-1d4394b9ebea', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 10, 10, 'For, "He who would love life, and see good days, let him keep his tongue from evil, and his lips from speaking deceit.'),
  ('c448f278-481d-56ce-a325-ebe237a3a892', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 11, 11, 'Let him turn away from evil, and do good. Let him seek peace, and pursue it.'),
  ('8b3e2bda-7085-5983-a43f-d7da753dfd1e', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 12, 12, 'For the eyes of the Lord are on the righteous, and his ears open to their prayer; but the face of the Lord is against those who do evil."'),
  ('123c921c-e99d-5f50-a701-52d31266142c', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 13, 13, 'Now who is he who will harm you, if you become imitators of that which is good?'),
  ('1347ad60-ff53-5e0e-ab76-053e4f1c20c5', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 14, 14, 'But even if you should suffer for righteousness'' sake, you are blessed. "Don''t fear what they fear, neither be troubled."'),
  ('731d17e2-d3a1-5582-afc9-af8c0a7ba446', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 15, 15, 'But sanctify the Lord God in your hearts; and always be ready to give an answer to everyone who asks you a reason concerning the hope that is in you, with humility and fear:'),
  ('79ef33d9-d9a9-5f0e-a54a-800ce274679c', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 16, 16, 'having a good conscience; that, while you are spoken against as evildoers, they may be disappointed who curse your good way of life in Christ.'),
  ('6b70dd54-7947-5cb1-a074-d070abdc3788', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 17, 17, 'For it is better, if it is God''s will, that you suffer for doing well than for doing evil.'),
  ('c24f939a-8755-5bd9-a5d0-0db9d522885f', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 18, 18, 'Because Christ also suffered for sins once, the righteous for the unrighteous, that he might bring you to God; being put to death in the flesh, but made alive in the spirit;'),
  ('6f22cfb5-99e7-5d4a-a4eb-bd247d37a898', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 19, 19, 'in which he also went and preached to the spirits in prison,'),
  ('211d761c-2c5a-509e-a67e-eca184c9cc20', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 20, 20, 'who before were disobedient, when God waited patiently in the days of Noah, while the ship was being built. In it, few, that is, eight souls, were saved through water.'),
  ('fb6584b8-10b5-55b5-a1ba-d6f7d568b54e', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 21, 21, 'This is a symbol of baptism, which now saves you--not the putting away of the filth of the flesh, but the answer of a good conscience toward God, through the resurrection of Jesus Christ,'),
  ('52e898e4-0518-5f54-a8fb-8e923e612d79', 'd6c3e514-d333-58f8-a5af-28b56fbd7b9a', NULL, 22, 22, 'who is at the right hand of God, having gone into heaven, angels and authorities and powers being made subject to him.'),
  ('6abb24a0-be11-5a98-a769-89f04f728d8c', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 1, 1, 'Forasmuch then as Christ suffered for us in the flesh, arm yourselves also with the same mind; for he who has suffered in the flesh has ceased from sin;'),
  ('aa280961-2479-53b7-a2ae-693bad5fcbd7', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 2, 2, 'that you no longer should live the rest of your time in the flesh for the lusts of men, but for the will of God.'),
  ('fa00c2ec-fdcc-5aca-a26f-528ffb4bfffc', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 3, 3, 'For we have spent enough of our past time doing the desire of the Gentiles, and having walked in lewdness, lusts, drunken binges, orgies, carousings, and abominable idolatries.'),
  ('c469beb5-32f4-52ce-acc5-86e390d0256f', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 4, 4, 'They think it is strange that you don''t run with them into the same excess of riot, blaspheming:'),
  ('29060a9f-029f-5106-ad59-0950d57cc55b', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 5, 5, 'who will give account to him who is ready to judge the living and the dead.'),
  ('1a1fbeee-e5e4-5cde-a1d1-abd0b817d682', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 6, 6, 'For to this end the Good News was preached even to the dead, that they might be judged indeed as men in the flesh, but live as to God in the spirit.'),
  ('78182f74-1110-5b13-a024-639bea4a0341', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 7, 7, 'But the end of all things is near. Therefore be of sound mind, self-controlled, and sober in prayer.'),
  ('4f1936b8-6dd7-5784-ab17-21e7e35ed64a', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 8, 8, 'And above all things be earnest in your love among yourselves, for love covers a multitude of sins.'),
  ('cc928ea6-829d-52d8-aba9-b259fd3fd702', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 9, 9, 'Be hospitable to one another without grumbling.'),
  ('f5d55369-6fa4-5288-af53-69e7a59ebf79', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 10, 10, 'As each has received a gift, employ it in serving one another, as good managers of the grace of God in its various forms.'),
  ('cc8b0575-611d-5c31-a33c-2a0dcce97585', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 11, 11, 'If anyone speaks, let it be as it were the very words of God. If anyone serves, let it be as of the strength which God supplies, that in all things God may be glorified through Jesus Christ, to whom belong the glory and the dominion forever and ever. Amen.'),
  ('6d19121e-34cb-50b6-a317-2d5548d546c0', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 12, 12, 'Beloved, don''t be astonished at the fiery trial which has come upon you, to test you, as though a strange thing happened to you.'),
  ('c0dce8c6-3eb4-556f-a098-982093547a5e', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 13, 13, 'But because you are partakers of Christ''s sufferings, rejoice; that at the revelation of his glory you also may rejoice with exceeding joy.'),
  ('23664871-46c3-5754-ad05-9df666462cef', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 14, 14, 'If you are insulted for the name of Christ, you are blessed; because the Spirit of glory and of God rests on you. On their part he is blasphemed, but on your part he is glorified.'),
  ('789484b1-d110-52e3-a9b7-d18478222c10', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 15, 15, 'For let none of you suffer as a murderer, or a thief, or an evil doer, or a meddler in other men''s matters.'),
  ('e8c46ed0-ff4f-5bb3-a8a6-3d78a1d1861d', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 16, 16, 'But if one of you suffers for being a Christian, let him not be ashamed; but let him glorify God in this matter.'),
  ('6860f46a-d353-5246-a7a1-23fbf1ca9b8e', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 17, 17, 'For the time has come for judgment to begin with the household of God. If it begins first with us, what will happen to those who don''t obey the Good News of God?'),
  ('aa96e83d-a17d-5cfd-a2b7-a4ccb5fc2439', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 18, 18, '"If it is hard for the righteous to be saved, what will happen to the ungodly and the sinner?"'),
  ('4051c608-f1c2-5fe0-af65-b7d4f7bc5a04', '1f51a922-7f1e-53c2-a9e3-7a01fa41b456', NULL, 19, 19, 'Therefore let them also who suffer according to the will of God in doing good entrust their souls to him, as to a faithful Creator.'),
  ('dccf9c3d-1b74-5443-a8e9-12eaf665fe13', '2ab6d79b-83b8-5d1e-accc-f77adf13f2d2', NULL, 1, 1, 'I exhort the elders among you, as a fellow elder, and a witness of the sufferings of Christ, and who will also share in the glory that will be revealed.'),
  ('3d9b428f-7fa0-58c6-a97e-30ca0d1f2506', '2ab6d79b-83b8-5d1e-accc-f77adf13f2d2', NULL, 2, 2, 'Shepherd the flock of God which is among you, exercising the oversight, not under compulsion, but voluntarily, not for dishonest gain, but willingly;'),
  ('a01973ff-d7ba-5e34-a1d3-05e3236cf176', '2ab6d79b-83b8-5d1e-accc-f77adf13f2d2', NULL, 3, 3, 'neither as lording it over those entrusted to you, but making yourselves examples to the flock.'),
  ('e95634e3-57fd-5c8f-ae36-d80a0fd285af', '2ab6d79b-83b8-5d1e-accc-f77adf13f2d2', NULL, 4, 4, 'When the chief Shepherd is revealed, you will receive the crown of glory that doesn''t fade away.'),
  ('40ec8b73-8695-5a8d-a395-703f35751072', '2ab6d79b-83b8-5d1e-accc-f77adf13f2d2', NULL, 5, 5, 'Likewise, you younger ones, be subject to the elder. Yes, all of you clothe yourselves with humility, to subject yourselves to one another; for "God resists the proud, but gives grace to the humble."'),
  ('aa3471cc-0152-5d33-a8b2-55f434d0a8c3', '2ab6d79b-83b8-5d1e-accc-f77adf13f2d2', NULL, 6, 6, 'Humble yourselves therefore under the mighty hand of God, that he may exalt you in due time;'),
  ('27b9d8a8-9504-552c-ae1f-d0c0407eedff', '2ab6d79b-83b8-5d1e-accc-f77adf13f2d2', NULL, 7, 7, 'casting all your worries on him, because he cares for you.'),
  ('e2e908c9-2009-5def-a9bf-af712dced16c', '2ab6d79b-83b8-5d1e-accc-f77adf13f2d2', NULL, 8, 8, 'Be sober and self-controlled. Be watchful. Your adversary, the devil, walks around like a roaring lion, seeking whom he may devour.'),
  ('14ad8fa4-e749-54f7-a0fc-c744ad0dc7e4', '2ab6d79b-83b8-5d1e-accc-f77adf13f2d2', NULL, 9, 9, 'Withstand him steadfast in your faith, knowing that your brothers who are in the world are undergoing the same sufferings.'),
  ('b528122c-3d99-5144-aa89-90dbbc70a846', '2ab6d79b-83b8-5d1e-accc-f77adf13f2d2', NULL, 10, 10, 'But may the God of all grace, who called you to his eternal glory by Christ Jesus, after you have suffered a little while, perfect, establish, strengthen, and settle you.'),
  ('3dfa2904-9061-543a-abf5-fcedc81f97bd', '2ab6d79b-83b8-5d1e-accc-f77adf13f2d2', NULL, 11, 11, 'To him be the glory and the power forever and ever. Amen.'),
  ('e196095d-f211-5de4-a049-d1427acc704e', '2ab6d79b-83b8-5d1e-accc-f77adf13f2d2', NULL, 12, 12, 'Through Silvanus, our faithful brother, as I consider him, I have written to you briefly, exhorting, and testifying that this is the true grace of God in which you stand.'),
  ('66f23c7e-0512-576b-a2d6-33d208aad028', '2ab6d79b-83b8-5d1e-accc-f77adf13f2d2', NULL, 13, 13, 'She who is in Babylon, chosen together with you, greets you; and so does Mark, my son.'),
  ('6b6cdb47-c734-5c9b-a91a-2e67991c48f8', '2ab6d79b-83b8-5d1e-accc-f77adf13f2d2', NULL, 14, 14, 'Greet one another with a kiss of love. Peace be to you all who are in Christ Jesus. Amen.'),
  ('055de205-0c52-5d17-a2e1-8fafec3ad11b', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 1, 1, 'Simon Peter, a servant and apostle of Jesus Christ, to those who have obtained a like precious faith with us in the righteousness of our God and Savior, Jesus Christ:'),
  ('c9f9d03b-fd05-59fe-a7ce-efa7a197d213', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 2, 2, 'Grace to you and peace be multiplied in the knowledge of God and of Jesus our Lord,'),
  ('cadc7afd-10dc-592e-aa25-4ff30e5efaa4', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 3, 3, 'seeing that his divine power has granted to us all things that pertain to life and godliness, through the knowledge of him who called us by his own glory and virtue;'),
  ('c15c9e29-0b32-5229-a914-186b1af750d2', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 4, 4, 'by which he has granted to us his precious and exceedingly great promises; that through these you may become partakers of the divine nature, having escaped from the corruption that is in the world by lust.'),
  ('9fabfa2c-588b-5c70-abf1-c9e52099a7f4', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 5, 5, 'Yes, and for this very cause adding on your part all diligence, in your faith supply moral excellence; and in moral excellence, knowledge;'),
  ('e04e549e-d947-5354-ad1d-7c3aa9057a0a', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 6, 6, 'and in knowledge, self-control; and in self-control patience; and in patience godliness;'),
  ('927a0ea3-24e4-54c4-a964-21bef613b60d', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 7, 7, 'and in godliness brotherly affection; and in brotherly affection, love.'),
  ('8003549a-736f-52b5-a56d-25e7087f423b', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 8, 8, 'For if these things are yours and abound, they make you to be not idle nor unfruitful to the knowledge of our Lord Jesus Christ.'),
  ('ae16e592-8fd4-5190-a436-e09fc2f82837', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 9, 9, 'For he who lacks these things is blind, seeing only what is near, having forgotten the cleansing from his old sins.'),
  ('391668fc-f584-582d-a74c-d7d56bbb3b4d', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 10, 10, 'Therefore, brothers, be more diligent to make your calling and election sure. For if you do these things, you will never stumble.'),
  ('3d1517f9-ffda-5617-ae02-5275f36f0ffc', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 11, 11, 'For thus you will be richly supplied with the entrance into the eternal Kingdom of our Lord and Savior, Jesus Christ.'),
  ('d118c438-0530-50e5-ad2b-6b47e735ae29', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 12, 12, 'Therefore I will not be negligent to remind you of these things, though you know them, and are established in the present truth.'),
  ('01a6d452-d844-515b-ab21-1e9133a3f7ef', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 13, 13, 'I think it right, as long as I am in this tent, to stir you up by reminding you;'),
  ('0da79947-233c-5e34-a2cb-6ab170783cd4', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 14, 14, 'knowing that the putting off of my tent comes swiftly, even as our Lord Jesus Christ made clear to me.'),
  ('e710728e-78dd-5fb5-a21f-fa472ea1e89f', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 15, 15, 'Yes, I will make every effort that you may always be able to remember these things even after my departure.'),
  ('6fd30838-8511-5b7a-a973-da81209bdca3', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 16, 16, 'For we did not follow cunningly devised fables, when we made known to you the power and coming of our Lord Jesus Christ, but we were eyewitnesses of his majesty.'),
  ('cc2d66be-1b63-56f6-ad78-9696f906f2d5', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 17, 17, 'For he received from God the Father honor and glory, when the voice came to him from the Majestic Glory, "This is my beloved Son, in whom I am well pleased."'),
  ('34fd1411-76df-5ccd-a6b6-727866e7d727', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 18, 18, 'We heard this voice come out of heaven when we were with him on the holy mountain.'),
  ('dd4761a7-9438-5d6c-a9e3-35671d5ebfff', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 19, 19, 'We have the more sure word of prophecy; and you do well that you heed it, as to a lamp shining in a dark place, until the day dawns, and the morning star arises in your hearts:'),
  ('fd43d7c1-79c4-5eff-aef2-de983b05f398', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 20, 20, 'knowing this first, that no prophecy of Scripture is of private interpretation.'),
  ('277f06e1-adcd-5187-a8fb-a2de4ec0cde2', '82310d34-1644-57a5-a3eb-edeb6c3393d0', NULL, 21, 21, 'For no prophecy ever came by the will of man: but holy men of God spoke, being moved by the Holy Spirit.'),
  ('82b2c0e2-9d96-5fbb-a4ad-47a0dd947345', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 1, 1, 'But false prophets also arose among the people, as false teachers will also be among you, who will secretly bring in destructive heresies, denying even the Master who bought them, bringing on themselves swift destruction.'),
  ('c06abe90-29d4-5d5f-a3c2-721b5ca7b23f', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 2, 2, 'Many will follow their immoral ways, and as a result, the way of the truth will be maligned.'),
  ('0857f695-1287-5256-afd4-b9aad3cddf15', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 3, 3, 'In covetousness they will exploit you with deceptive words: whose sentence now from of old doesn''t linger, and their destruction will not slumber.'),
  ('e20f0b88-7e59-5170-ac3a-dd6ce6b3a195', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 4, 4, 'For if God didn''t spare angels when they sinned, but cast them down to Tartarus, and committed them to pits of darkness, to be reserved for judgment;'),
  ('4dec831e-ac14-506a-a7ae-43a23428ac6a', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 5, 5, 'and didn''t spare the ancient world, but preserved Noah with seven others, a preacher of righteousness, when he brought a flood on the world of the ungodly;'),
  ('4f7d18c2-84a0-5962-a957-a2df94df40af', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 6, 6, 'and turning the cities of Sodom and Gomorrah into ashes, condemned them to destruction, having made them an example to those who would live ungodly;'),
  ('cad0b597-181a-5b64-a1ea-63e6bcc08023', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 7, 7, 'and delivered righteous Lot, who was very distressed by the lustful life of the wicked'),
  ('2ef9dd06-2d3e-5fd4-af01-f1219eedf640', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 8, 8, '(for that righteous man dwelling among them, was tormented in his righteous soul from day to day with seeing and hearing lawless deeds):'),
  ('8db71d27-4af7-5179-ac33-167d7453b605', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 9, 9, 'the Lord knows how to deliver the godly out of temptation and to keep the unrighteous under punishment for the day of judgment;'),
  ('b44b248d-8c02-5442-ae32-d2cdf5ceb508', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 10, 10, 'but chiefly those who walk after the flesh in the lust of defilement, and despise authority. Daring, self-willed, they are not afraid to speak evil of dignitaries;'),
  ('57f7cc23-24fd-57db-a51f-b07dd5e38d98', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 11, 11, 'whereas angels, though greater in might and power, don''t bring a railing judgment against them before the Lord.'),
  ('324b8f67-56f3-5c40-a632-8189340c6285', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 12, 12, 'But these, as unreasoning creatures, born natural animals to be taken and destroyed, speaking evil in matters about which they are ignorant, will in their destroying surely be destroyed,'),
  ('374396c9-e539-5447-a7ec-adcad2a13a33', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 13, 13, 'receiving the wages of unrighteousness; people who count it pleasure to revel in the daytime, spots and blemishes, reveling in their deceit while they feast with you;'),
  ('fe69c24c-9b1d-5ebd-a9cf-d9bd7f10bdfa', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 14, 14, 'having eyes full of adultery, and who can''t cease from sin; enticing unsettled souls; having a heart trained in greed; children of cursing;'),
  ('58a94c88-d62e-5b6c-adda-168392dd789a', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 15, 15, 'forsaking the right way, they went astray, having followed the way of Balaam the son of Beor, who loved the wages of wrongdoing;'),
  ('bf78a5d1-4a27-52ac-a8af-092b52fe2167', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 16, 16, 'but he was rebuked for his own disobedience. A mute donkey spoke with a man''s voice and stopped the madness of the prophet.'),
  ('bcd85f9b-6b90-58c9-a635-5736e71472e8', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 17, 17, 'These are wells without water, clouds driven by a storm; for whom the blackness of darkness has been reserved forever.'),
  ('c2402946-3c5d-56c9-ab41-d7c1b9777539', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 18, 18, 'For, uttering great swelling words of emptiness, they entice in the lusts of the flesh, by licentiousness, those who are indeed escaping from those who live in error;'),
  ('6d589123-3fc9-53a9-a04b-c14a83536db8', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 19, 19, 'promising them liberty, while they themselves are bondservants of corruption; for a man is brought into bondage by whoever overcomes him.'),
  ('766220c9-6f04-5623-a93d-763b48428a89', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 20, 20, 'For if, after they have escaped the defilement of the world through the knowledge of the Lord and Savior Jesus Christ, they are again entangled in it and overcome, the last state has become worse for them than the first.'),
  ('3c49f92b-bde5-5bef-a398-4a3936466cc9', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 21, 21, 'For it would be better for them not to have known the way of righteousness, than, after knowing it, to turn back from the holy commandment delivered to them.'),
  ('1dba08a2-5fea-55bc-ae5b-dd18984d70b5', '2e2de6c2-80f8-5cb7-a413-d065407eb601', NULL, 22, 22, 'But it has happened to them according to the true proverb, "The dog turns to his own vomit again," and "the sow that has washed to wallowing in the mire."'),
  ('fbb9583c-d37d-5656-a79b-b9b5741efc26', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 1, 1, 'This is now, beloved, the second letter that I have written to you; and in both of them I stir up your sincere mind by reminding you;'),
  ('f2dd38a6-d7a1-5d31-a4c3-e27dc59282c3', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 2, 2, 'that you should remember the words which were spoken before by the holy prophets, and the commandments of us, the apostles of the Lord and Savior:'),
  ('5d418a39-e4e7-5cea-a723-413abcccace0', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 3, 3, 'knowing this first, that in the last days mockers will come, walking after their own lusts,'),
  ('00e84f5c-a2da-5c7e-a08f-bdc9d9561e66', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 4, 4, 'and saying, "Where is the promise of his coming? For, from the day that the fathers fell asleep, all things continue as they were from the beginning of the creation."'),
  ('14f30837-9b4c-5776-af8d-b88a65fba051', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 5, 5, 'For this they willfully forget, that there were heavens from of old, and an earth formed out of water and amid water, by the word of God;'),
  ('e44a7e10-89de-502c-a6be-a6879134bff6', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 6, 6, 'by which means the world that then was, being overflowed with water, perished.'),
  ('5ec3f1f8-d7fc-5eee-a3c8-fe2985fa3a33', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 7, 7, 'But the heavens that now are, and the earth, by the same word have been stored up for fire, being reserved against the day of judgment and destruction of ungodly men.'),
  ('7fe3b3b9-2464-5d4f-a9c5-8b073ecc4ab5', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 8, 8, 'But don''t forget this one thing, beloved, that one day is with the Lord as a thousand years, and a thousand years as one day.'),
  ('97c26117-1050-5b0c-a39e-92caad65d545', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 9, 9, 'The Lord is not slow concerning his promise, as some count slowness; but is patient with us, not wishing that any should perish, but that all should come to repentance.'),
  ('d4edfd94-eead-5ecc-a7c0-fcc1d78f46fe', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 10, 10, 'But the day of the Lord will come as a thief in the night; in which the heavens will pass away with a great noise, and the elements will be dissolved with fervent heat, and the earth and the works that are in it will be burned up.'),
  ('981aa3e3-e011-5ba1-a122-1125eac90c89', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 11, 11, 'Therefore since all these things will be destroyed like this, what kind of people ought you to be in holy living and godliness,'),
  ('03c7cb02-8c4c-545c-ab3e-ce97471bc6ca', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 12, 12, 'looking for and earnestly desiring the coming of the day of God, which will cause the burning heavens to be dissolved, and the elements will melt with fervent heat?'),
  ('8be6fe91-7346-5e26-ae61-17616abd562d', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 13, 13, 'But, according to his promise, we look for new heavens and a new earth, in which righteousness dwells.'),
  ('70d3c45d-98d9-5294-a16a-74f0f53d1cc5', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 14, 14, 'Therefore, beloved, seeing that you look for these things, be diligent to be found in peace, without blemish and blameless in his sight.'),
  ('4b8ce84b-5aeb-5fe0-a39f-008d5c401d93', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 15, 15, 'Regard the patience of our Lord as salvation; even as our beloved brother Paul also, according to the wisdom given to him, wrote to you;'),
  ('8b9b7751-4bdf-5fe8-a969-1abbd0f109db', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 16, 16, 'as also in all of his letters, speaking in them of these things. In those, there are some things that are hard to understand, which the ignorant and unsettled twist, as they also do to the other Scriptures, to their own destruction.'),
  ('94209f73-10bc-55c7-a838-43c634eb780e', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 17, 17, 'You therefore, beloved, knowing these things beforehand, beware, lest being carried away with the error of the wicked, you fall from your own steadfastness.'),
  ('584e5ee6-8e3a-5f6f-a51a-dfde49998922', '8772048b-f011-5044-ada1-7a1c0de6ce23', NULL, 18, 18, 'But grow in the grace and knowledge of our Lord and Savior Jesus Christ. To him be the glory both now and forever. Amen.'),
  ('b8e719f1-f5ed-51b7-a724-7d80c6322b4b', 'eee4e978-8831-52cf-aa58-fa092f91fe79', NULL, 1, 1, 'That which was from the beginning, that which we have heard, that which we have seen with our eyes, that which we saw, and our hands touched, concerning the Word of life'),
  ('0e52e74a-6d59-58a9-aae7-f90b011a646d', 'eee4e978-8831-52cf-aa58-fa092f91fe79', NULL, 2, 2, '(and the life was revealed, and we have seen, and testify, and declare to you the life, the eternal life, which was with the Father, and was revealed to us);'),
  ('8af02d9d-1307-5c91-ada7-8bcf7b42109c', 'eee4e978-8831-52cf-aa58-fa092f91fe79', NULL, 3, 3, 'that which we have seen and heard we declare to you, that you also may have fellowship with us. Yes, and our fellowship is with the Father, and with his Son, Jesus Christ.'),
  ('50a6a0f5-7d10-5af7-a6b7-5789a1a0aa4f', 'eee4e978-8831-52cf-aa58-fa092f91fe79', NULL, 4, 4, 'And we write these things to you, that our joy may be fulfilled.'),
  ('228408d3-e31e-5159-a1da-016d0d7af551', 'eee4e978-8831-52cf-aa58-fa092f91fe79', NULL, 5, 5, 'This is the message which we have heard from him and announce to you, that God is light, and in him is no darkness at all.'),
  ('c0e337c6-5d40-5309-a9a5-4b0044e7cdc6', 'eee4e978-8831-52cf-aa58-fa092f91fe79', NULL, 6, 6, 'If we say that we have fellowship with him and walk in the darkness, we lie, and don''t tell the truth.'),
  ('d5223037-8dba-5004-a810-c319e27f66c4', 'eee4e978-8831-52cf-aa58-fa092f91fe79', NULL, 7, 7, 'But if we walk in the light, as he is in the light, we have fellowship with one another, and the blood of Jesus Christ, his Son, cleanses us from all sin.'),
  ('b1603144-ffc5-53a7-a6b6-c36841a6ce51', 'eee4e978-8831-52cf-aa58-fa092f91fe79', NULL, 8, 8, 'If we say that we have no sin, we deceive ourselves, and the truth is not in us.'),
  ('eb73c17f-7c6e-5dd1-a403-24f6e6308733', 'eee4e978-8831-52cf-aa58-fa092f91fe79', NULL, 9, 9, 'If we confess our sins, he is faithful and righteous to forgive us the sins, and to cleanse us from all unrighteousness.'),
  ('171f2158-a4c5-535c-a6db-ea2612f79cd4', 'eee4e978-8831-52cf-aa58-fa092f91fe79', NULL, 10, 10, 'If we say that we haven''t sinned, we make him a liar, and his word is not in us.'),
  ('126d4985-b584-5a74-a5d0-62c1f0a6c56a', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 1, 1, 'My little children, I write these things to you so that you may not sin. If anyone sins, we have a Counselor with the Father, Jesus Christ, the righteous.'),
  ('9d59e1ab-b125-5549-a273-e10a3a486012', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 2, 2, 'And he is the atoning sacrifice for our sins, and not for ours only, but also for the whole world.'),
  ('2b230c74-28d5-5cab-a178-23c5b41402a9', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 3, 3, 'This is how we know that we know him: if we keep his commandments.'),
  ('fb9aa709-9324-54f5-a142-ef089431b569', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 4, 4, 'One who says, "I know him," and doesn''t keep his commandments, is a liar, and the truth isn''t in him.'),
  ('96a6c9e8-c794-5367-a188-32d7d0bbd2ba', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 5, 5, 'But whoever keeps his word, God''s love has most certainly been perfected in him. This is how we know that we are in him:'),
  ('50c59fb8-fa07-5861-aa67-d9abd2ce2d95', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 6, 6, 'he who says he remains in him ought himself also to walk just like he walked.'),
  ('7db22ac8-a607-5dba-a15d-0453241a3d45', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 7, 7, 'Brothers, I write no new commandment to you, but an old commandment which you had from the beginning. The old commandment is the word which you heard from the beginning.'),
  ('0985474f-1cba-5b22-a84a-2c29482b2c38', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 8, 8, 'Again, I write a new commandment to you, which is true in him and in you; because the darkness is passing away, and the true light already shines.'),
  ('06795dfc-545e-5422-af9d-4f2d881e9582', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 9, 9, 'He who says he is in the light and hates his brother, is in the darkness even until now.'),
  ('9eefeab8-b653-588b-ae13-f7c1544e1813', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 10, 10, 'He who loves his brother remains in the light, and there is no occasion for stumbling in him.'),
  ('c890a1bb-6901-50db-af27-27f3f679ec96', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 11, 11, 'But he who hates his brother is in the darkness, and walks in the darkness, and doesn''t know where he is going, because the darkness has blinded his eyes.'),
  ('55c435e8-6579-54d4-aa7d-9d35b7f39f20', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 12, 12, 'I write to you, little children, because your sins are forgiven you for his name''s sake.'),
  ('1992780d-b50c-5f33-a091-d66eafc722b5', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 13, 13, 'I write to you, fathers, because you know him who is from the beginning. I write to you, young men, because you have overcome the evil one. I write to you, little children, because you know the Father.'),
  ('35eec4f5-48cd-55f8-a865-3b55685acfd3', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 14, 14, 'I have written to you, fathers, because you know him who is from the beginning. I have written to you, young men, because you are strong, and the word of God remains in you, and you have overcome the evil one.'),
  ('1167c138-3a92-5ed8-ac31-fae9b45186ff', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 15, 15, 'Don''t love the world, neither the things that are in the world. If anyone loves the world, the Father''s love isn''t in him.'),
  ('83c791ae-c527-5114-a400-15b57abc1f26', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 16, 16, 'For all that is in the world, the lust of the flesh, the lust of the eyes, and the pride of life, isn''t the Father''s, but is the world''s.'),
  ('c5a0fd69-86f9-5af4-aaa0-360b56a4f1ea', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 17, 17, 'The world is passing away with its lusts, but he who does God''s will remains forever.'),
  ('b21aaad6-6fc7-53e5-a39f-a7fc171ff48b', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 18, 18, 'Little children, these are the end times, and as you heard that the Antichrist is coming, even now many antichrists have arisen. By this we know that it is the final hour.'),
  ('a3d25118-19f4-540a-ae97-2e3419287a6c', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 19, 19, 'They went out from us, but they didn''t belong to us; for if they had belonged to us, they would have continued with us. But they left, that they might be revealed that none of them belong to us.'),
  ('88f7116b-68ed-5002-ab9a-5c9b4bbc9da6', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 20, 20, 'You have an anointing from the Holy One, and you all have knowledge.'),
  ('f3846573-2660-5061-a96d-ebd1fc2b1ad9', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 21, 21, 'I have not written to you because you don''t know the truth, but because you know it, and because no lie is of the truth.'),
  ('0f9b5042-4388-5ddd-a169-c8b00e71acdc', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 22, 22, 'Who is the liar but he who denies that Jesus is the Christ? This is the Antichrist, he who denies the Father and the Son.'),
  ('f2987a5c-4546-50a2-a96d-59146c18faa3', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 23, 23, 'Whoever denies the Son, the same doesn''t have the Father. He who confesses the Son has the Father also.'),
  ('69d902ef-30e4-5b17-ad98-5f275a6b6037', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 24, 24, 'Therefore, as for you, let that remain in you which you heard from the beginning. If that which you heard from the beginning remains in you, you also will remain in the Son, and in the Father.'),
  ('94cda3bf-e5da-5a4a-a524-84a6daf69a6e', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 25, 25, 'This is the promise which he promised us, the eternal life.'),
  ('923e219a-2c8a-5352-a2f7-e28b08bff519', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 26, 26, 'These things I have written to you concerning those who would lead you astray.'),
  ('e88dc41e-29c9-5a71-a84a-6172781b2b53', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 27, 27, 'As for you, the anointing which you received from him remains in you, and you don''t need for anyone to teach you. But as his anointing teaches you concerning all things, and is true, and is no lie, and even as it taught you, you will remain in him.'),
  ('d912f4c7-55e8-5a42-ae48-7e8481658159', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 28, 28, 'Now, little children, remain in him, that when he appears, we may have boldness, and not be ashamed before him at his coming.'),
  ('08d0afe4-378e-5040-a114-941e9cbc95d9', '8147e210-4606-57d4-abb9-ebe4455505e3', NULL, 29, 29, 'If you know that he is righteous, you know that everyone who practices righteousness is born of him.'),
  ('2b2dee38-046e-55da-ae74-9daa1c5d1d48', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 1, 1, 'Behold, how great a love the Father has bestowed on us, that we should be called children of God! For this cause the world doesn''t know us, because it didn''t know him.'),
  ('7c5cdc3d-0be7-5274-ab2f-1ad3c1c158d2', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 2, 2, 'Beloved, now we are children of God, and it is not yet revealed what we will be. But we know that, when he is revealed, we will be like him; for we will see him just as he is.'),
  ('ad2b862b-58b6-5729-a2d7-8a5e84d0de3d', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 3, 3, 'Everyone who has this hope set on him purifies himself, even as he is pure.'),
  ('ff3005d6-6446-5840-a60d-382e9bbdf3cd', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 4, 4, 'Everyone who sins also commits lawlessness. Sin is lawlessness.'),
  ('c74065e8-a414-5986-a382-dfc8c9bfea22', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 5, 5, 'You know that he was revealed to take away our sins, and in him is no sin.'),
  ('a9516bf3-657d-59be-af82-0e53f6ce8e72', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 6, 6, 'Whoever remains in him doesn''t sin. Whoever sins hasn''t seen him, neither knows him.'),
  ('5055968d-fae4-5f71-a00c-f74255985960', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 7, 7, 'Little children, let no one lead you astray. He who does righteousness is righteous, even as he is righteous.'),
  ('a41cee2a-7568-5752-a6d2-cb0b0fa5b7ad', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 8, 8, 'He who sins is of the devil, for the devil has been sinning from the beginning. To this end the Son of God was revealed, that he might destroy the works of the devil.'),
  ('286cad95-46d8-58e3-a783-c6c68c0a1b41', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 9, 9, 'Whoever is born of God doesn''t commit sin, because his seed remains in him; and he can''t sin, because he is born of God.'),
  ('9ea175b5-e0ff-582e-a761-63cacaf874c2', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 10, 10, 'In this the children of God are revealed, and the children of the devil. Whoever doesn''t do righteousness is not of God, neither is he who doesn''t love his brother.'),
  ('025ab24f-d161-5317-adec-024df62f6cff', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 11, 11, 'For this is the message which you heard from the beginning, that we should love one another;'),
  ('f4531b9a-43ce-5d81-ab88-9333c208b9b4', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 12, 12, 'unlike Cain, who was of the evil one, and killed his brother. Why did he kill him? Because his works were evil, and his brother''s righteous.'),
  ('d0721163-c406-57a3-a49f-1e3327f40a24', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 13, 13, 'Don''t be surprised, my brothers, if the world hates you.'),
  ('8eb18642-e6e4-5bac-a36b-834ae911a4dd', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 14, 14, 'We know that we have passed out of death into life, because we love the brothers. He who doesn''t love his brother remains in death.'),
  ('0f86a6d7-ebb8-5a0c-a367-8feafa13156d', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 15, 15, 'Whoever hates his brother is a murderer, and you know that no murderer has eternal life remaining in him.'),
  ('949e5050-f730-5511-adb9-fe04fb9ac834', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 16, 16, 'By this we know love, because he laid down his life for us. And we ought to lay down our lives for the brothers.'),
  ('4dc336e6-aae2-5b30-a5f7-4a12fb62de22', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 17, 17, 'But whoever has the world''s goods, and sees his brother in need, and closes his heart of compassion against him, how does the love of God remain in him?'),
  ('24072484-105c-506d-a8e7-3e7b39148f83', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 18, 18, 'My little children, let''s not love in word only, neither with the tongue only, but in deed and truth.'),
  ('b93c8468-e8fe-509c-a32c-1b04c12dec05', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 19, 19, 'And by this we know that we are of the truth, and persuade our hearts before him,'),
  ('dff30111-1cb9-583f-a631-e0eba71bcdd5', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 20, 20, 'because if our heart condemns us, God is greater than our heart, and knows all things.'),
  ('4bebf375-c61a-5373-a1f9-abc7b377e917', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 21, 21, 'Beloved, if our hearts don''t condemn us, we have boldness toward God;'),
  ('8688c9ff-bf1c-5330-a1f1-500e2f12574f', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 22, 22, 'and whatever we ask, we receive from him, because we keep his commandments and do the things that are pleasing in his sight.'),
  ('ae5ff66f-8bfc-5583-a68f-1f05aa2ec6e9', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 23, 23, 'This is his commandment, that we should believe in the name of his Son, Jesus Christ, and love one another, even as he commanded.'),
  ('71c5c267-dea3-507c-a341-68e35fa8cac0', 'e601bee0-5285-5db1-aa8e-5165c2cad935', NULL, 24, 24, 'He who keeps his commandments remains in him, and he in him. By this we know that he remains in us, by the Spirit which he gave us.'),
  ('2646346a-a20f-5446-a0d7-41797047f410', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 1, 1, 'Beloved, don''t believe every spirit, but test the spirits, whether they are of God, because many false prophets have gone out into the world.'),
  ('4b699b60-5938-5b09-a5c5-5c83c76ba9d9', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 2, 2, 'By this you know the Spirit of God: every spirit who confesses that Jesus Christ has come in the flesh is of God,'),
  ('4668b06d-85da-5136-a5ec-e9c7a4fe1058', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 3, 3, 'and every spirit who doesn''t confess that Jesus Christ has come in the flesh is not of God, and this is the spirit of the Antichrist, of whom you have heard that it comes. Now it is in the world already.'),
  ('6d4ec226-cc84-58fc-a32d-761d71403b8e', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 4, 4, 'You are of God, little children, and have overcome them; because greater is he who is in you than he who is in the world.'),
  ('60142757-610a-513b-a25e-c0f8511b28e9', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 5, 5, 'They are of the world. Therefore they speak of the world, and the world hears them.'),
  ('5a83a01e-cb41-546d-a31e-05436a141b3b', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 6, 6, 'We are of God. He who knows God listens to us. He who is not of God doesn''t listen to us. By this we know the spirit of truth, and the spirit of error.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('96e2c255-cc67-5f9d-af91-d2ac316e0e77', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 7, 7, 'Beloved, let us love one another, for love is of God; and everyone who loves is born of God, and knows God.'),
  ('bcc41282-e382-51fb-ac05-2e7025f688e0', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 8, 8, 'He who doesn''t love doesn''t know God, for God is love.'),
  ('ae789a7a-1ddd-5021-a950-01aa2c40f8db', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 9, 9, 'By this God''s love was revealed in us, that God has sent his one and only Son into the world that we might live through him.'),
  ('8fe71146-f19b-5802-ae4f-5ddab0845132', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 10, 10, 'In this is love, not that we loved God, but that he loved us, and sent his Son as the atoning sacrifice for our sins.'),
  ('fcec0bcc-131f-51cc-a1d5-ba4d518bc3c4', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 11, 11, 'Beloved, if God loved us in this way, we also ought to love one another.'),
  ('aa035bc6-8e79-5ad6-a3a9-3f1f33cdaabf', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 12, 12, 'No one has seen God at any time. If we love one another, God remains in us, and his love has been perfected in us.'),
  ('84205f55-443c-5799-a87a-cf916f21bbb6', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 13, 13, 'By this we know that we remain in him and he in us, because he has given us of his Spirit.'),
  ('f682b2e8-330c-5b8f-a9b8-b9d4faee8d79', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 14, 14, 'We have seen and testify that the Father has sent the Son as the Savior of the world.'),
  ('0aceca86-362f-5b57-a80e-be2f1c5301ae', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 15, 15, 'Whoever confesses that Jesus is the Son of God, God remains in him, and he in God.'),
  ('a97f33e4-8f87-5a32-ae37-39c921fadbf1', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 16, 16, 'We know and have believed the love which God has for us. God is love, and he who remains in love remains in God, and God remains in him.'),
  ('e320e68a-b1ae-5c8f-ae62-d5a46ec95b20', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 17, 17, 'In this love has been made perfect among us, that we may have boldness in the day of judgment, because as he is, even so are we in this world.'),
  ('82fb0ab6-ba0e-561b-aa3f-57edd804fe51', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 18, 18, 'There is no fear in love; but perfect love casts out fear, because fear has punishment. He who fears is not made perfect in love.'),
  ('bf4e307f-8d9e-5d8a-a2a0-956300038cca', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 19, 19, 'We love him, because he first loved us.'),
  ('50f0019e-8373-5068-accb-29e56fac621b', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 20, 20, 'If a man says, "I love God," and hates his brother, he is a liar; for he who doesn''t love his brother whom he has seen, how can he love God whom he has not seen?'),
  ('28e97201-53f1-5952-aca4-a61136a2c22e', 'c6eb5239-c6b7-5811-a708-a27976dfebf2', NULL, 21, 21, 'This commandment we have from him, that he who loves God should also love his brother.'),
  ('e0ab743e-a5df-5612-a30b-40cb641dd809', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 1, 1, 'Whoever believes that Jesus is the Christ is born of God. Whoever loves the Father also loves the child who is born of him.'),
  ('5c0632bc-ede4-5a89-a4df-96b69e24c762', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 2, 2, 'By this we know that we love the children of God, when we love God and keep his commandments.'),
  ('bc3f7def-4834-5a3e-adb0-498c0d7a6c25', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 3, 3, 'For this is the love of God, that we keep his commandments. His commandments are not grievous.'),
  ('c3b9af7c-bb7f-56a6-a062-e997af901d13', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 4, 4, 'For whatever is born of God overcomes the world. This is the victory that has overcome the world: your faith.'),
  ('ff222dd7-e171-507e-ac45-0878527368d5', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 5, 5, 'Who is he who overcomes the world, but he who believes that Jesus is the Son of God?'),
  ('0770885c-3cff-54d9-a127-e8c5a599aa4c', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 6, 6, 'This is he who came by water and blood, Jesus Christ; not with the water only, but with the water and the blood. It is the Spirit who testifies, because the Spirit is the truth.'),
  ('f1e7ae0d-df26-540d-a2e9-c8d726415423', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 7, 7, 'For there are three who testify:'),
  ('ccbc101e-f534-5a32-afcf-019c4042e7be', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 8, 8, 'the Spirit, the water, and the blood; and the three agree as one.'),
  ('095ce7e0-2a35-54b7-a201-b60a81f501fb', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 9, 9, 'If we receive the witness of men, the witness of God is greater; for this is God''s testimony which he has testified concerning his Son.'),
  ('de18c8dc-ea4d-570a-a7c6-e8c1b4625cce', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 10, 10, 'He who believes in the Son of God has the testimony in himself. He who doesn''t believe God has made him a liar, because he has not believed in the testimony that God has given concerning his Son.'),
  ('c284b536-cb64-5687-acf4-f61d14f10d5b', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 11, 11, 'The testimony is this, that God gave to us eternal life, and this life is in his Son.'),
  ('92dfcf7d-a87c-5c2a-adcf-039a28a6fc75', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 12, 12, 'He who has the Son has the life. He who doesn''t have God''s Son doesn''t have the life.'),
  ('7f6278f1-bccb-591d-acac-1bcff80e472a', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 13, 13, 'These things I have written to you who believe in the name of the Son of God, that you may know that you have eternal life, and that you may continue to believe in the name of the Son of God.'),
  ('1bd32043-2edf-5f16-a4da-2a1cc78ccfb1', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 14, 14, 'This is the boldness which we have toward him, that, if we ask anything according to his will, he listens to us.'),
  ('defef97a-7f97-5564-aa4b-0850b00df6f5', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 15, 15, 'And if we know that he listens to us, whatever we ask, we know that we have the petitions which we have asked of him.'),
  ('03b7bce7-3e51-5d07-a88a-4adf531cc4aa', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 16, 16, 'If anyone sees his brother sinning a sin not leading to death, he shall ask, and God will give him life for those who sin not leading to death. There is a sin leading to death. I don''t say that he should make a request concerning this.'),
  ('ebdb1f0d-050a-5fef-adaa-90bc2d5aef9c', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 17, 17, 'All unrighteousness is sin, and there is a sin not leading to death.'),
  ('47caca28-3c77-547b-ad56-7570c4ede884', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 18, 18, 'We know that whoever is born of God doesn''t sin, but he who was born of God keeps himself, and the evil one doesn''t touch him.'),
  ('17b36955-338d-567b-ae39-77a9968430cd', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 19, 19, 'We know that we are of God, and the whole world lies in the power of the evil one.'),
  ('7a87e56f-d888-58ea-a4be-af3aee284d7d', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 20, 20, 'We know that the Son of God has come, and has given us an understanding, that we know him who is true, and we are in him who is true, in his Son Jesus Christ. This is the true God, and eternal life.'),
  ('09115fd7-aa2d-53c8-a382-5ad0b6a2ec79', 'b6f1d888-d95c-5008-ab81-6c4d2f55b2ea', NULL, 21, 21, 'Little children, keep yourselves from idols.'),
  ('29e88f6a-a269-5707-a8ed-45e676a39301', '3cc5589e-0614-53b0-a207-ce12e9beb01e', NULL, 1, 1, 'The elder, to the chosen lady and her children, whom I love in truth; and not I only, but also all those who know the truth;'),
  ('66017b1f-8783-5fbf-aa7a-804c07d7e890', '3cc5589e-0614-53b0-a207-ce12e9beb01e', NULL, 2, 2, 'for the truth''s sake, which remains in us, and it will be with us forever:'),
  ('9fb6c985-0df0-5cd0-a4ae-2e5298f5b23c', '3cc5589e-0614-53b0-a207-ce12e9beb01e', NULL, 3, 3, 'Grace, mercy, and peace will be with us, from God the Father, and from the Lord Jesus Christ, the Son of the Father, in truth and love.'),
  ('7e44be2b-a1f9-51af-a84f-e3396dc3528a', '3cc5589e-0614-53b0-a207-ce12e9beb01e', NULL, 4, 4, 'I rejoice greatly that I have found some of your children walking in truth, even as we have been commanded by the Father.'),
  ('431b1c0c-3d49-510c-a11a-f6fe09647000', '3cc5589e-0614-53b0-a207-ce12e9beb01e', NULL, 5, 5, 'Now I beg you, dear lady, not as though I wrote to you a new commandment, but that which we had from the beginning, that we love one another.'),
  ('c361668a-f9ab-5696-a520-9ac7c676912e', '3cc5589e-0614-53b0-a207-ce12e9beb01e', NULL, 6, 6, 'This is love, that we should walk according to his commandments. This is the commandment, even as you heard from the beginning, that you should walk in it.'),
  ('6b96a4a7-36ac-5e21-a1ef-b05dab7b7040', '3cc5589e-0614-53b0-a207-ce12e9beb01e', NULL, 7, 7, 'For many deceivers have gone out into the world, those who don''t confess that Jesus Christ came in the flesh. This is the deceiver and the Antichrist.'),
  ('8f562968-53c3-532b-a094-3adb1f435cf8', '3cc5589e-0614-53b0-a207-ce12e9beb01e', NULL, 8, 8, 'Watch yourselves, that we don''t lose the things which we have accomplished, but that we receive a full reward.'),
  ('2302f3df-f53e-51cb-a2d6-7345f30cf57f', '3cc5589e-0614-53b0-a207-ce12e9beb01e', NULL, 9, 9, 'Whoever transgresses and doesn''t remain in the teaching of Christ, doesn''t have God. He who remains in the teaching, the same has both the Father and the Son.'),
  ('ebc4e4af-b087-5164-aa40-1dd644c3908d', '3cc5589e-0614-53b0-a207-ce12e9beb01e', NULL, 10, 10, 'If anyone comes to you, and doesn''t bring this teaching, don''t receive him into your house, and don''t welcome him,'),
  ('b5fe5406-61e2-52ae-a92e-37e83a61c712', '3cc5589e-0614-53b0-a207-ce12e9beb01e', NULL, 11, 11, 'for he who welcomes him participates in his evil works.'),
  ('a4dc2eef-9ebb-5d4c-a8d3-5cdf548d64ba', '3cc5589e-0614-53b0-a207-ce12e9beb01e', NULL, 12, 12, 'Having many things to write to you, I don''t want to do so with paper and ink, but I hope to come to you, and to speak face to face, that our joy may be made full.'),
  ('7d3b0d6d-26df-56b7-a610-6061211d2d92', '3cc5589e-0614-53b0-a207-ce12e9beb01e', NULL, 13, 13, 'The children of your chosen sister greet you. Amen.'),
  ('9f3b17b8-f03c-545c-a3bd-00df85fb012f', '310faa87-2666-54fa-ad68-2eff411e87b2', NULL, 1, 1, 'The elder to Gaius the beloved, whom I love in truth.'),
  ('4c57f7ce-f54b-57c4-ae38-04de16ef74fc', '310faa87-2666-54fa-ad68-2eff411e87b2', NULL, 2, 2, 'Beloved, I pray that you may prosper in all things and be healthy, even as your soul prospers.'),
  ('c39ca664-87a4-5b51-a802-e2387899886a', '310faa87-2666-54fa-ad68-2eff411e87b2', NULL, 3, 3, 'For I rejoiced greatly, when brothers came and testified about your truth, even as you walk in truth.'),
  ('ed6b9f0d-2e43-596a-a131-becbfb2a4a63', '310faa87-2666-54fa-ad68-2eff411e87b2', NULL, 4, 4, 'I have no greater joy than this, to hear about my children walking in truth.'),
  ('88bdbe0b-3cbd-54a3-a4b9-61974b8aa163', '310faa87-2666-54fa-ad68-2eff411e87b2', NULL, 5, 5, 'Beloved, you do a faithful work in whatever you accomplish for those who are brothers and strangers.'),
  ('914d2ab7-b1fe-5787-a110-6f3eb2999c50', '310faa87-2666-54fa-ad68-2eff411e87b2', NULL, 6, 6, 'They have testified about your love before the assembly. You will do well to send them forward on their journey in a way worthy of God,'),
  ('d43c4b43-a6ac-5fcc-a03d-8c858ce978bf', '310faa87-2666-54fa-ad68-2eff411e87b2', NULL, 7, 7, 'because for the sake of the Name they went out, taking nothing from the Gentiles.'),
  ('d8eeca97-db24-58d6-a078-81e34a260d44', '310faa87-2666-54fa-ad68-2eff411e87b2', NULL, 8, 8, 'We therefore ought to receive such, that we may be fellow workers for the truth.'),
  ('b5b36156-d9f0-588a-a9a0-7595dc64177d', '310faa87-2666-54fa-ad68-2eff411e87b2', NULL, 9, 9, 'I wrote to the assembly, but Diotrephes, who loves to be first among them, doesn''t accept what we say.'),
  ('36b01d03-d916-5f7a-a5a8-8e13c77f354a', '310faa87-2666-54fa-ad68-2eff411e87b2', NULL, 10, 10, 'Therefore, if I come, I will call attention to his deeds which he does, unjustly accusing us with wicked words. Not content with this, neither does he himself receive the brothers, and those who would, he forbids and throws out of the assembly.'),
  ('5237b522-b444-5fdf-a168-690f246a71a3', '310faa87-2666-54fa-ad68-2eff411e87b2', NULL, 11, 11, 'Beloved, don''t imitate that which is evil, but that which is good. He who does good is of God. He who does evil hasn''t seen God.'),
  ('bbc856a4-bb63-5934-a5b0-781b99ecdc0f', '310faa87-2666-54fa-ad68-2eff411e87b2', NULL, 12, 12, 'Demetrius has the testimony of all, and of the truth itself; yes, we also testify, and you know that our testimony is true.'),
  ('7df34fd3-4da7-59f6-a1e9-f678dc8c14a7', '310faa87-2666-54fa-ad68-2eff411e87b2', NULL, 13, 13, 'I had many things to write to you, but I am unwilling to write to you with ink and pen;'),
  ('b9c48dc1-80f5-5a87-aa97-7e9705385604', '310faa87-2666-54fa-ad68-2eff411e87b2', NULL, 14, 14, 'but I hope to see you soon, and we will speak face to face. Peace be to you. The friends greet you. Greet the friends by name.'),
  ('81a6555c-4213-58b4-a8a9-9cbd09d99748', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 1, 1, 'Jude, a servant of Jesus Christ, and brother of James, to those who are called, sanctified by God the Father, and kept for Jesus Christ:'),
  ('68abdf55-c3ea-535d-abad-1484dac87867', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 2, 2, 'Mercy to you and peace and love be multiplied.'),
  ('7afbdbad-0f01-5f99-a76b-776d9f66dace', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 3, 3, 'Beloved, while I was very eager to write to you about our common salvation, I was constrained to write to you exhorting you to contend earnestly for the faith which was once for all delivered to the saints.'),
  ('5553bd7e-2786-5623-a83d-dd01f3e483e5', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 4, 4, 'For there are certain men who crept in secretly, even those who were long ago written about for this condemnation: ungodly men, turning the grace of our God into indecency, and denying our only Master, God, and Lord, Jesus Christ.'),
  ('40f74010-b103-5675-ae9e-bad6989be74a', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 5, 5, 'Now I desire to remind you, though you already know this, that the Lord, having saved a people out of the land of Egypt, afterward destroyed those who didn''t believe.'),
  ('f94f43ef-55f6-5370-a63b-720faca821b0', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 6, 6, 'Angels who didn''t keep their first domain, but deserted their own dwelling place, he has kept in everlasting bonds under darkness for the judgment of the great day.'),
  ('319183e8-2f16-5642-a911-da80e4c820e8', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 7, 7, 'Even as Sodom and Gomorrah, and the cities around them, having, in the same way as these, given themselves over to sexual immorality and gone after strange flesh, are set forth as an example, suffering the punishment of eternal fire.'),
  ('e5ac240c-0b8a-5647-ad9e-3d86ba413372', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 8, 8, 'Yet in the same way, these also in their dreaming defile the flesh, despise authority, and slander celestial beings.'),
  ('f4ec1f58-fb23-59a4-aa8b-60e7b2e8b13a', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 9, 9, 'But Michael, the archangel, when contending with the devil and arguing about the body of Moses, dared not bring against him an abusive condemnation, but said, "May the Lord rebuke you!"'),
  ('d97e5dfd-9668-5751-a6c9-0f4cbdfc40cb', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 10, 10, 'But these speak evil of whatever things they don''t know. What they understand naturally, like the creatures without reason, they are destroyed in these things.'),
  ('0890a5f0-72fd-5acf-a9d9-ebbf77459610', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 11, 11, 'Woe to them! For they went in the way of Cain, and ran riotously in the error of Balaam for hire, and perished in Korah''s rebellion.'),
  ('1918716e-e064-56c2-aed6-11ffb9a0539d', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 12, 12, 'These are hidden rocky reefs in your love feasts when they feast with you, shepherds who without fear feed themselves; clouds without water, carried along by winds; autumn leaves without fruit, twice dead, plucked up by the roots;'),
  ('d40d725c-196b-566f-acfe-cb96670df8ea', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 13, 13, 'wild waves of the sea, foaming out their own shame; wandering stars, for whom the blackness of darkness has been reserved forever.'),
  ('bae347dc-7e13-52aa-ad6e-99438b3f05ea', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 14, 14, 'About these also Enoch, the seventh from Adam, prophesied, saying, "Behold, the Lord came with ten thousands of his holy ones,'),
  ('d46c0d30-f740-5502-a46d-65ffad9c8016', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 15, 15, 'to execute judgment on all, and to convict all the ungodly of all their works of ungodliness which they have done in an ungodly way, and of all the hard things which ungodly sinners have spoken against him."'),
  ('1308c4e7-af87-514f-aa21-6f3106c1c0d2', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 16, 16, 'These are murmurers and complainers, walking after their lusts (and their mouth speaks proud things), showing respect of persons to gain advantage.'),
  ('b5baf646-f117-513d-a890-7e382afcac6d', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 17, 17, 'But you, beloved, remember the words which have been spoken before by the apostles of our Lord Jesus Christ.'),
  ('af2f940d-a9e1-5a32-a833-f8b2430452de', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 18, 18, 'They said to you that "In the last time there will be mockers, walking after their own ungodly lusts."'),
  ('d048b180-f311-55fe-a086-aa47b6541b5b', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 19, 19, 'These are they who cause divisions, and are sensual, not having the Spirit.'),
  ('31c7c09e-6802-5a23-aa1d-dde7621b57e4', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 20, 20, 'But you, beloved, keep building up yourselves on your most holy faith, praying in the Holy Spirit.'),
  ('5feb3227-f8cc-55d6-a8dc-bcc196d4bafc', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 21, 21, 'Keep yourselves in the love of God, looking for the mercy of our Lord Jesus Christ to eternal life.'),
  ('3299a4d2-0b8f-5677-a81f-cd670f24ce6b', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 22, 22, 'On some have compassion, making a distinction,'),
  ('74b062d8-471f-5c96-ad2d-af7e95e26895', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 23, 23, 'and some save, snatching them out of the fire with fear, hating even the clothing stained by the flesh.'),
  ('b292dc8d-b506-5297-a32a-b6ee82eb84d4', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 24, 24, 'Now to him who is able to keep them from stumbling, and to present you faultless before the presence of his glory in great joy,'),
  ('259fa0a6-2036-5d2b-a8e1-e8781273cfa7', '1b57996d-dcf3-5b0a-afe5-efef7391eae2', NULL, 25, 25, 'to God our Savior, who alone is wise, be glory and majesty, dominion and power, both now and forever. Amen.'),
  ('992f6cc9-a3d9-56c8-a017-fb9dfc5122a7', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 1, 1, 'This is the Revelation of Jesus Christ, which God gave him to show to his servants the things which must happen soon, which he sent and made known by his angel to his servant, John,'),
  ('bd2811d1-6512-55f0-a62a-95a3dcbcbe16', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 2, 2, 'who testified to God''s word, and of the testimony of Jesus Christ, about everything that he saw.'),
  ('b9ef63b7-f419-5865-a8fb-6be0513c2a6a', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 3, 3, 'Blessed is he who reads and those who hear the words of the prophecy, and keep the things that are written in it, for the time is at hand.'),
  ('7dd3045d-0aa1-5185-a665-071bd047709f', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 4, 4, 'John, to the seven assemblies that are in Asia: Grace to you and peace, from God, who is and who was and who is to come; and from the seven Spirits who are before his throne;'),
  ('1aaa81f7-1d95-5c72-abbb-7d3588e485e6', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 5, 5, 'and from Jesus Christ, the faithful witness, the firstborn of the dead, and the ruler of the kings of the earth. To him who loves us, and washed us from our sins by his blood;'),
  ('1e908820-d40a-580d-a380-5ee49f005c46', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 6, 6, 'and he made us to be a Kingdom, priests to his God and Father; to him be the glory and the dominion forever and ever. Amen.'),
  ('7a967439-dbc4-5672-af38-bb829b780cef', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 7, 7, 'Behold, he is coming with the clouds, and every eye will see him, including those who pierced him. All the tribes of the earth will mourn over him. Even so, Amen.'),
  ('35f667d0-0238-5cc9-ab57-37742c467b11', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 8, 8, '"I am the Alpha and the Omega," says the Lord God, "who is and who was and who is to come, the Almighty."'),
  ('626b167a-3919-51a1-a9d9-fd37c9b9ca07', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 9, 9, 'I John, your brother and partner with you in oppression, Kingdom, and perseverance in Christ Jesus, was on the isle that is called Patmos because of God''s Word and the testimony of Jesus Christ.'),
  ('8b77bd2b-fdc9-5bcd-a45e-d40e45f90c91', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 10, 10, 'I was in the Spirit on the Lord''s day, and I heard behind me a loud voice, like a trumpet'),
  ('150dcd00-188b-5bf9-ae9c-0fa52af194f8', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 11, 11, 'saying, "What you see, write in a book and send to the seven assemblies: to Ephesus, Smyrna, Pergamum, Thyatira, Sardis, Philadelphia, and to Laodicea."'),
  ('8d570737-9d12-5f63-a7d5-64eb3c939c1e', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 12, 12, 'I turned to see the voice that spoke with me. Having turned, I saw seven golden lampstands.'),
  ('c45e5300-1d84-529d-adfd-439778e0daee', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 13, 13, 'And among the lampstands was one like a son of man, clothed with a robe reaching down to his feet, and with a golden sash around his chest.'),
  ('9cf8ae21-0284-5016-a527-c13865c2c6e8', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 14, 14, 'His head and his hair were white as white wool, like snow. His eyes were like a flame of fire.'),
  ('029f7ff7-ede5-5d34-ab54-f9fd429fac23', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 15, 15, 'His feet were like burnished brass, as if it had been refined in a furnace. His voice was like the voice of many waters.'),
  ('6da9ea0b-ecbb-59c5-ac79-47f17a8c277a', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 16, 16, 'He had seven stars in his right hand. Out of his mouth proceeded a sharp two-edged sword. His face was like the sun shining at its brightest.'),
  ('135caa5f-e5ad-5e5f-adff-1d29e7ac6abf', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 17, 17, 'When I saw him, I fell at his feet like a dead man. He laid his right hand on me, saying, "Don''t be afraid. I am the first and the last,'),
  ('045b8f71-1f2f-5b19-abcf-fab8d02b708f', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 18, 18, 'and the Living one. I was dead, and behold, I am alive forevermore. Amen. I have the keys of Death and of Hades.'),
  ('1cc891d0-1975-5ed5-a5bd-7c0a10a85f3a', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 19, 19, 'Write therefore the things which you have seen, and the things which are, and the things which will happen hereafter;'),
  ('4a81afbe-6d78-52b0-a74e-dd196184c55f', 'a4013e39-940f-5e9c-aa3e-1cd590ed7c0a', NULL, 20, 20, 'the mystery of the seven stars which you saw in my right hand, and the seven golden lampstands. The seven stars are the angels of the seven assemblies. The seven lampstands are seven assemblies.'),
  ('327442a8-ad7b-5c8f-ac0e-27354d98c63a', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 1, 1, '"To the angel of the assembly in Ephesus write: "He who holds the seven stars in his right hand, he who walks among the seven golden lampstands says these things:'),
  ('2334622e-7149-53f6-a5e5-240e9c5d4dbb', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 2, 2, '"I know your works, and your toil and perseverance, and that you can''t tolerate evil men, and have tested those who call themselves apostles, and they are not, and found them false.'),
  ('921ddfa0-f454-5d09-ab9b-74f263c79151', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 3, 3, 'You have perseverance and have endured for my name''s sake, and have not grown weary.'),
  ('3a9287e3-73d6-5871-ae3b-6111b8b6edf9', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 4, 4, 'But I have this against you, that you left your first love.'),
  ('f48a5b32-9034-527b-a8f1-c1dcb4a1d23a', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 5, 5, 'Remember therefore from where you have fallen, and repent and do the first works; or else I am coming to you swiftly, and will move your lampstand out of its place, unless you repent.'),
  ('806ebc16-44e5-591c-a769-93b422250eb3', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 6, 6, 'But this you have, that you hate the works of the Nicolaitans, which I also hate.'),
  ('90464a12-6b5b-536d-a94f-4317944983ac', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 7, 7, 'He who has an ear, let him hear what the Spirit says to the assemblies. To him who overcomes I will give to eat of the tree of life, which is in the Paradise of my God.'),
  ('74fc4184-049d-59b3-ac33-bd527aeb8cde', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 8, 8, '"To the angel of the assembly in Smyrna write: "The first and the last, who was dead, and has come to life says these things:'),
  ('cde04476-9793-5e10-a6a6-a3d374e72a99', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 9, 9, '"I know your works, oppression, and your poverty (but you are rich), and the blasphemy of those who say they are Jews, and they are not, but are a synagogue of Satan.'),
  ('a8913de5-89bd-50dc-a455-f3584574eebd', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 10, 10, 'Don''t be afraid of the things which you are about to suffer. Behold, the devil is about to throw some of you into prison, that you may be tested; and you will have oppression for ten days. Be faithful to death, and I will give you the crown of life.'),
  ('2619cb8d-4d7d-5a6e-ab4b-904b16e60202', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 11, 11, 'He who has an ear, let him hear what the Spirit says to the assemblies. He who overcomes won''t be harmed by the second death.'),
  ('dd2564a2-7900-5cb0-a407-bc7130216f5b', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 12, 12, '"To the angel of the assembly in Pergamum write: "He who has the sharp two-edged sword says these things:'),
  ('fd1ccacf-b9c1-5a3f-a40b-15ba6417a5aa', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 13, 13, '"I know your works and where you dwell, where Satan''s throne is. You hold firmly to my name, and didn''t deny my faith in the days of Antipas my witness, my faithful one, who was killed among you, where Satan dwells.'),
  ('b353b2d7-cd73-58b5-a871-9ab79caec58f', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 14, 14, 'But I have a few things against you, because you have there some who hold the teaching of Balaam, who taught Balak to throw a stumbling block before the children of Israel, to eat things sacrificed to idols, and to commit sexual immorality.'),
  ('56c0f3e3-9225-50fc-a3a7-c4d34f541182', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 15, 15, 'So you also have some who hold to the teaching of the Nicolaitans likewise.'),
  ('81075bd6-f9b2-5a14-a86b-9f0075b49c44', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 16, 16, 'Repent therefore, or else I am coming to you quickly, and I will make war against them with the sword of my mouth.'),
  ('40b89091-7ba3-5b4b-a637-f7403fa06c22', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 17, 17, 'He who has an ear, let him hear what the Spirit says to the assemblies. To him who overcomes, to him I will give of the hidden manna, and I will give him a white stone, and on the stone a new name written, which no one knows but he who receives it.'),
  ('5cff0ceb-b5ef-50df-ac46-3d6ed591bcfd', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 18, 18, '"To the angel of the assembly in Thyatira write: "The Son of God, who has his eyes like a flame of fire, and his feet are like burnished brass, says these things:'),
  ('cd1f8241-3199-5304-a9ec-fc25a7c92103', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 19, 19, '"I know your works, your love, faith, service, patient endurance, and that your last works are more than the first.'),
  ('1ba60526-3eff-508e-a176-6a18c3e2e6f0', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 20, 20, 'But I have this against you, that you tolerate your woman, Jezebel, who calls herself a prophetess. She teaches and seduces my servants to commit sexual immorality, and to eat things sacrificed to idols.'),
  ('94b725b5-e535-5f83-a889-c464c9d8ad75', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 21, 21, 'I gave her time to repent, but she refuses to repent of her sexual immorality.'),
  ('89a06742-c347-5934-ad49-9885ef74cd61', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 22, 22, 'Behold, I will throw her into a bed, and those who commit adultery with her into great oppression, unless they repent of her works.'),
  ('0b714b7d-6767-5c26-a635-ca361d632411', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 23, 23, 'I will kill her children with Death, and all the assemblies will know that I am he who searches the minds and hearts. I will give to each one of you according to your deeds.'),
  ('01942961-1aab-5673-a0e4-4a18055bbdf8', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 24, 24, 'But to you I say, to the rest who are in Thyatira, as many as don''t have this teaching, who don''t know what some call ''the deep things of Satan,'' to you I say, I am not putting any other burden on you.'),
  ('7be79ae6-f9ee-5222-a67f-b5fc19d7010a', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 25, 25, 'Nevertheless, hold that which you have firmly until I come.'),
  ('2ca76c33-bee3-58d6-a2c5-f1e1a32d2be5', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 26, 26, 'He who overcomes, and he who keeps my works to the end, to him I will give authority over the nations.'),
  ('da87ffc2-69c3-5610-a4cd-61b269211d41', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 27, 27, 'He will rule them with a rod of iron, shattering them like clay pots; as I also have received of my Father:'),
  ('716bcf5b-3b69-5829-a098-4bdd65903822', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 28, 28, 'and I will give him the morning star.'),
  ('2a4e623b-9c08-5fed-aa04-8637d5116241', '08a0b0d9-9e94-54a2-a021-e954471c072a', NULL, 29, 29, 'He who has an ear, let him hear what the Spirit says to the assemblies.'),
  ('e95e442f-aa69-54cf-a721-1986d548d294', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 1, 1, '"And to the angel of the assembly in Sardis write: "He who has the seven Spirits of God, and the seven stars says these things: "I know your works, that you have a reputation of being alive, but you are dead.'),
  ('9f79c124-823d-5608-a1a0-e2bdd71f6f46', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 2, 2, 'Wake up, and keep the things that remain, which you were about to throw away, for I have found no works of yours perfected before my God.'),
  ('ca9fcb68-a64f-5b46-a1b2-7fa03ab87b41', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 3, 3, 'Remember therefore how you have received and heard. Keep it, and repent. If therefore you won''t watch, I will come as a thief, and you won''t know what hour I will come upon you.'),
  ('d22538a1-5173-5b8a-a3db-6531e76136c4', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 4, 4, 'Nevertheless you have a few names in Sardis that did not defile their garments. They will walk with me in white, for they are worthy.'),
  ('4b396b20-cfd0-588e-aec7-d65bbcf74369', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 5, 5, 'He who overcomes will be arrayed in white garments, and I will in no way blot his name out of the book of life, and I will confess his name before my Father, and before his angels.'),
  ('763c18bd-8b06-5d91-a5a3-2d32bda78604', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 6, 6, 'He who has an ear, let him hear what the Spirit says to the assemblies.'),
  ('ef84e5ab-fa83-5244-a476-fe50357edcf2', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 7, 7, '"To the angel of the assembly in Philadelphia write: "He who is holy, he who is true, he who has the key of David, he who opens and no one can shut, and who shuts and no one opens, says these things:'),
  ('94e0912e-e592-505f-af36-d88d0942a507', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 8, 8, '"I know your works (behold, I have set before you an open door, which no one can shut), that you have a little power, and kept my word, and didn''t deny my name.'),
  ('9e418363-2c3f-52aa-a72d-f234363649ff', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 9, 9, 'Behold, I give of the synagogue of Satan, of those who say they are Jews, and they are not, but lie. Behold, I will make them to come and worship before your feet, and to know that I have loved you.'),
  ('5f318ae6-784c-53aa-a846-81bb3e11541e', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 10, 10, 'Because you kept my command to endure, I also will keep you from the hour of testing, which is to come on the whole world, to test those who dwell on the earth.'),
  ('367a3353-df22-53cc-ac2a-13eb2241657c', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 11, 11, 'I am coming quickly! Hold firmly that which you have, so that no one takes your crown.'),
  ('9ac7d1c5-27b7-59c7-a918-9781f758a3b5', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 12, 12, 'He who overcomes, I will make him a pillar in the temple of my God, and he will go out from there no more. I will write on him the name of my God, and the name of the city of my God, the new Jerusalem, which comes down out of heaven from my God, and my own new name.'),
  ('98937ad7-8437-506f-ad06-9cc5c6b41d50', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 13, 13, 'He who has an ear, let him hear what the Spirit says to the assemblies.'),
  ('0f99046b-0fa7-576d-a8d9-7b30cbe15cc0', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 14, 14, '"To the angel of the assembly in Laodicea write: "The Amen, the Faithful and True Witness, the Head of God''s creation, says these things:'),
  ('5f7c915d-24cc-5a81-aefa-15e70e17a3d4', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 15, 15, '"I know your works, that you are neither cold nor hot. I wish you were cold or hot.'),
  ('8f640e4d-0fa9-50ec-ab38-2732894f12f6', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 16, 16, 'So, because you are lukewarm, and neither hot nor cold, I will vomit you out of my mouth.'),
  ('195fa999-910a-5056-a352-7e96454e99d0', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 17, 17, 'Because you say, ''I am rich, and have gotten riches, and have need of nothing;'' and don''t know that you are the wretched one, miserable, poor, blind, and naked;'),
  ('a1c7845e-85f4-5f01-a638-1558fb937e07', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 18, 18, 'I counsel you to buy from me gold refined by fire, that you may become rich; and white garments, that you may clothe yourself, and that the shame of your nakedness may not be revealed; and eye salve to anoint your eyes, that you may see.'),
  ('3c4dcbd9-7880-5c78-aab4-79eb1b53107e', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 19, 19, 'As many as I love, I reprove and chasten. Be zealous therefore, and repent.'),
  ('bdb9e78e-cd0c-5290-a79c-0e51bbdbc17b', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 20, 20, 'Behold, I stand at the door and knock. If anyone hears my voice and opens the door, then I will come in to him, and will dine with him, and he with me.'),
  ('a35a6e18-9b20-5d16-a920-485a1ae6ee0c', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 21, 21, 'He who overcomes, I will give to him to sit down with me on my throne, as I also overcame, and sat down with my Father on his throne.'),
  ('5f944175-d87d-53c1-a5f0-925a41b309db', '03710dd7-3a33-56cb-ad32-2ac919a0f408', NULL, 22, 22, 'He who has an ear, let him hear what the Spirit says to the assemblies."'),
  ('7feeb8f7-bd22-5de6-a38f-0bc9bc4c842f', '32b144bb-e68e-50c5-a30d-57049d5ee1a7', NULL, 1, 1, 'After these things I looked and saw a door opened in heaven, and the first voice that I heard, like a trumpet speaking with me, was one saying, "Come up here, and I will show you the things which must happen after this."'),
  ('d6877b4f-74d6-554e-a860-a48410f54a1a', '32b144bb-e68e-50c5-a30d-57049d5ee1a7', NULL, 2, 2, 'Immediately I was in the Spirit. Behold, there was a throne set in heaven, and one sitting on the throne'),
  ('20063b94-7b96-5528-a2cc-9be8a519ed96', '32b144bb-e68e-50c5-a30d-57049d5ee1a7', NULL, 3, 3, 'that looked like a jasper stone and a sardius. There was a rainbow around the throne, like an emerald to look at.'),
  ('987d7c86-a591-559d-af7f-8ce78d8eab56', '32b144bb-e68e-50c5-a30d-57049d5ee1a7', NULL, 4, 4, 'Around the throne were twenty-four thrones. On the thrones were twenty-four elders sitting, dressed in white garments, with crowns of gold on their heads.'),
  ('bef87008-2abe-520b-a860-1062505b98fe', '32b144bb-e68e-50c5-a30d-57049d5ee1a7', NULL, 5, 5, 'Out of the throne proceed lightnings, sounds, and thunders. There were seven lamps of fire burning before his throne, which are the seven Spirits of God.'),
  ('50351c1d-1643-5c66-a4d2-1c856c5726ef', '32b144bb-e68e-50c5-a30d-57049d5ee1a7', NULL, 6, 6, 'Before the throne was something like a sea of glass, similar to crystal. In the midst of the throne, and around the throne were four living creatures full of eyes before and behind.'),
  ('4a74613e-ecfe-530a-af97-0f5fe838596e', '32b144bb-e68e-50c5-a30d-57049d5ee1a7', NULL, 7, 7, 'The first creature was like a lion, and the second creature like a calf, and the third creature had a face like a man, and the fourth was like a flying eagle.'),
  ('5524e11d-399d-5d3b-a97b-41c147a80915', '32b144bb-e68e-50c5-a30d-57049d5ee1a7', NULL, 8, 8, 'The four living creatures, each one of them having six wings, are full of eyes around and within. They have no rest day and night, saying, "Holy, holy, holy is the Lord God, the Almighty, who was and who is and who is to come!"'),
  ('fb86a8eb-e753-5fa9-a249-410cc4314e2d', '32b144bb-e68e-50c5-a30d-57049d5ee1a7', NULL, 9, 9, 'When the living creatures give glory, honor, and thanks to him who sits on the throne, to him who lives forever and ever,'),
  ('ef808d1b-0f2e-5ab1-a35d-43d3d944c838', '32b144bb-e68e-50c5-a30d-57049d5ee1a7', NULL, 10, 10, 'the twenty-four elders fall down before him who sits on the throne, and worship him who lives forever and ever, and throw their crowns before the throne, saying,'),
  ('7387ab83-1476-5ae7-aed7-fd584d48e65d', '32b144bb-e68e-50c5-a30d-57049d5ee1a7', NULL, 11, 11, '"Worthy are you, our Lord and God, the Holy One, to receive the glory, the honor, and the power, for you created all things, and because of your desire they existed, and were created!"'),
  ('da73b5d1-3db6-51ec-ad0d-852968b2fa63', '5635fad5-6fff-5c09-a664-8a7cb3227133', NULL, 1, 1, 'I saw, in the right hand of him who sat on the throne, a book written inside and outside, sealed shut with seven seals.'),
  ('9de932fe-32bb-58ce-ad47-1e6b5a1325bb', '5635fad5-6fff-5c09-a664-8a7cb3227133', NULL, 2, 2, 'I saw a mighty angel proclaiming with a loud voice, "Who is worthy to open the book, and to break its seals?"'),
  ('ed37282a-dc6b-545f-a519-3125d5bb5760', '5635fad5-6fff-5c09-a664-8a7cb3227133', NULL, 3, 3, 'No one in heaven above, or on the earth, or under the earth, was able to open the book, or to look in it.'),
  ('a7fa0e29-b842-531f-a3a7-f58364649a20', '5635fad5-6fff-5c09-a664-8a7cb3227133', NULL, 4, 4, 'And I wept much, because no one was found worthy to open the book, or to look in it.'),
  ('9a2eb62a-ba15-506b-ac6c-5d841479257c', '5635fad5-6fff-5c09-a664-8a7cb3227133', NULL, 5, 5, 'One of the elders said to me, "Don''t weep. Behold, the Lion who is of the tribe of Judah, the Root of David, has overcome; he who opens the book and its seven seals."'),
  ('54b00fbe-badf-5c94-a774-5b72eab0b818', '5635fad5-6fff-5c09-a664-8a7cb3227133', NULL, 6, 6, 'I saw in the midst of the throne and of the four living creatures, and in the midst of the elders, a Lamb standing, as though it had been slain, having seven horns, and seven eyes, which are the seven Spirits of God, sent out into all the earth.'),
  ('0df1fadd-c704-570f-a5eb-929ba6625d45', '5635fad5-6fff-5c09-a664-8a7cb3227133', NULL, 7, 7, 'Then he came, and he took it out of the right hand of him who sat on the throne.'),
  ('5e1b1ba1-8c68-5a10-a783-1b68fdb450df', '5635fad5-6fff-5c09-a664-8a7cb3227133', NULL, 8, 8, 'Now when he had taken the book, the four living creatures and the twenty-four elders fell down before the Lamb, each one having a harp, and golden bowls full of incense, which are the prayers of the saints.'),
  ('bbcc1578-c10c-51bf-addd-848b3482ec79', '5635fad5-6fff-5c09-a664-8a7cb3227133', NULL, 9, 9, 'They sang a new song, saying, "You are worthy to take the book, and to open its seals: for you were killed, and bought us for God with your blood, out of every tribe, language, people, and nation,'),
  ('6a310553-8c19-5ed1-aa9e-808501117525', '5635fad5-6fff-5c09-a664-8a7cb3227133', NULL, 10, 10, 'and made us kings and priests to our God, and we will reign on earth."'),
  ('7e6ae0fd-6737-5f56-a4bc-e7666871bf86', '5635fad5-6fff-5c09-a664-8a7cb3227133', NULL, 11, 11, 'I saw, and I heard something like a voice of many angels around the throne, the living creatures, and the elders; and the number of them was ten thousands of ten thousands, and thousands of thousands;'),
  ('500ff50d-7139-5993-a787-2345f20b798b', '5635fad5-6fff-5c09-a664-8a7cb3227133', NULL, 12, 12, 'saying with a loud voice, "Worthy is the Lamb who has been killed to receive the power, wealth, wisdom, strength, honor, glory, and blessing!"'),
  ('8a07dede-5223-553c-a188-e9f54615a20f', '5635fad5-6fff-5c09-a664-8a7cb3227133', NULL, 13, 13, 'I heard every created thing which is in heaven, on the earth, under the earth, on the sea, and everything in them, saying, "To him who sits on the throne, and to the Lamb be the blessing, the honor, the glory, and the dominion, forever and ever! Amen!"'),
  ('10807c8f-5dcc-5ede-a830-66b810c8dfd8', '5635fad5-6fff-5c09-a664-8a7cb3227133', NULL, 14, 14, 'The four living creatures said, "Amen!" The elders fell down and worshiped.'),
  ('2313b332-465e-5a6d-ac52-f3e4288719d2', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 1, 1, 'I saw that the Lamb opened one of the seven seals, and I heard one of the four living creatures saying, as with a voice of thunder, "Come and see!"'),
  ('22514e95-72c6-5773-a20a-fa7026173292', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 2, 2, 'And behold, a white horse, and he who sat on it had a bow. A crown was given to him, and he came forth conquering, and to conquer.'),
  ('088ad34a-19fc-59e6-a0ac-83e6c6656692', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 3, 3, 'When he opened the second seal, I heard the second living creature saying, "Come!"'),
  ('4c897296-9633-58a6-aefe-0b012d819833', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 4, 4, 'Another came forth, a red horse. To him who sat on it was given power to take peace from the earth, and that they should kill one another. There was given to him a great sword.'),
  ('972894d8-1216-5f2f-a356-f3847725ce76', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 5, 5, 'When he opened the third seal, I heard the third living creature saying, "Come and see!" And behold, a black horse, and he who sat on it had a balance in his hand.'),
  ('7240cc32-04f8-5283-ad5b-af04844c4733', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 6, 6, 'I heard a voice in the midst of the four living creatures saying, "A choenix of wheat for a denarius, and three choenix of barley for a denarius! Don''t damage the oil and the wine!"'),
  ('babc4c91-2604-5459-ad31-92a2ac62c199', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 7, 7, 'When he opened the fourth seal, I heard the fourth living creature saying, "Come and see!"'),
  ('1f3d30eb-d308-5ac2-a594-9c68b020ce91', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 8, 8, 'And behold, a pale horse, and he who sat on it, his name was Death. Hades followed with him. Authority over one fourth of the earth, to kill with the sword, with famine, with death, and by the wild animals of the earth was given to him.'),
  ('36acd9cb-fd8b-5504-a480-949fe8d9485a', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 9, 9, 'When he opened the fifth seal, I saw underneath the altar the souls of those who had been killed for the Word of God, and for the testimony of the Lamb which they had.'),
  ('ca56540c-03d5-579e-ab65-5d15190d2669', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 10, 10, 'They cried with a loud voice, saying, "How long, Master, the holy and true, until you judge and avenge our blood on those who dwell on the earth?"'),
  ('c6d748c6-7acb-509b-ac11-b843c5e4483f', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 11, 11, 'A long white robe was given to each of them. They were told that they should rest yet for a while, until their fellow servants and their brothers, who would also be killed even as they were, should complete their course.'),
  ('a5a30cc2-1fbb-56a5-ac60-06d1c61c2cd7', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 12, 12, 'I saw when he opened the sixth seal, and there was a great earthquake. The sun became black as sackcloth made of hair, and the whole moon became as blood.'),
  ('b55e70e5-683f-5e73-acba-c9103ad9878b', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 13, 13, 'The stars of the sky fell to the earth, like a fig tree dropping its unripe figs when it is shaken by a great wind.'),
  ('a2c34927-ff06-5002-a21f-4efb861853a4', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 14, 14, 'The sky was removed like a scroll when it is rolled up. Every mountain and island were moved out of their places.'),
  ('9c2374cb-247e-55fa-a4df-b550d79f257c', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 15, 15, 'The kings of the earth, the princes, the commanding officers, the rich, the strong, and every slave and free person, hid themselves in the caves and in the rocks of the mountains.'),
  ('a6af8538-f5ac-5df1-adc9-de8034a39631', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 16, 16, 'They told the mountains and the rocks, "Fall on us, and hide us from the face of him who sits on the throne, and from the wrath of the Lamb,'),
  ('d5d47977-b73f-5b34-a6ee-f09793abb8d0', '96f15445-1f96-54c3-ab49-a089721d178e', NULL, 17, 17, 'for the great day of his wrath has come; and who is able to stand?"'),
  ('71e80dca-d9d0-55f8-a85b-a17439ad1c62', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 1, 1, 'After this, I saw four angels standing at the four corners of the earth, holding the four winds of the earth, so that no wind would blow on the earth, or on the sea, or on any tree.'),
  ('670b7cfd-606a-54bb-a328-228edacf80a0', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 2, 2, 'I saw another angel ascend from the sunrise, having the seal of the living God. He cried with a loud voice to the four angels to whom it was given to harm the earth and the sea,'),
  ('7a876377-da68-5415-affa-bb202af2d0e1', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 3, 3, 'saying, "Don''t harm the earth, neither the sea, nor the trees, until we have sealed the bondservants of our God on their foreheads!"'),
  ('e3a1441b-6822-59b2-a06d-109684a3e5bf', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 4, 4, 'I heard the number of those who were sealed, one hundred forty-four thousand, sealed out of every tribe of the children of Israel:'),
  ('ebc3e666-f232-5d8c-a64b-19de5300894f', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 5, 5, 'of the tribe of Judah were sealed twelve thousand, of the tribe of Reuben twelve thousand, of the tribe of Gad twelve thousand,'),
  ('3f480429-bbbd-541f-a2cd-ef88e8f06341', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 6, 6, 'of the tribe of Asher twelve thousand, of the tribe of Naphtali twelve thousand, of the tribe of Manasseh twelve thousand,'),
  ('56aed161-33ca-5b17-ad91-352566b6ee7e', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 7, 7, 'of the tribe of Simeon twelve thousand, of the tribe of Levi twelve thousand, of the tribe of Issachar twelve thousand,'),
  ('d8648517-685a-56d5-a4a1-3f52d1c092c0', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 8, 8, 'of the tribe of Zebulun twelve thousand, of the tribe of Joseph twelve thousand, of the tribe of Benjamin were sealed twelve thousand.'),
  ('4787281e-d674-5c59-a98a-b1617bffda93', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 9, 9, 'After these things I looked, and behold, a great multitude, which no man could number, out of every nation and of all tribes, peoples, and languages, standing before the throne and before the Lamb, dressed in white robes, with palm branches in their hands.'),
  ('fe65b1ec-e714-5c90-a393-b1025c5ca369', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 10, 10, 'They cried with a loud voice, saying, "Salvation be to our God, who sits on the throne, and to the Lamb!"'),
  ('d98ed2a9-e7f2-5235-a85c-18c15d2d3620', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 11, 11, 'All the angels were standing around the throne, the elders, and the four living creatures; and they fell on their faces before his throne, and worshiped God,'),
  ('bf1d7218-a5fa-5fb5-a317-4b4a46f547b2', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 12, 12, 'saying, "Amen! Blessing, glory, wisdom, thanksgiving, honor, power, and might, be to our God forever and ever! Amen."'),
  ('08c46709-4104-5fb4-a309-45cbe841b1ce', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 13, 13, 'One of the elders answered, saying to me, "These who are arrayed in white robes, who are they, and from where did they come?"'),
  ('aa7694d9-258e-500f-a18b-b7d8f1a11297', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 14, 14, 'I told him, "My lord, you know." He said to me, "These are those who came out of the great tribulation. They washed their robes, and made them white in the Lamb''s blood.'),
  ('279d80ef-04d6-5beb-aeac-e08e2894424a', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 15, 15, 'Therefore they are before the throne of God, they serve him day and night in his temple. He who sits on the throne will spread his tabernacle over them.'),
  ('bc57e3ba-74e9-52d6-aa17-3a99f11d0bfe', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 16, 16, 'They will never be hungry, neither thirsty any more; neither will the sun beat on them, nor any heat;'),
  ('9ffcb8f0-21f1-5c38-ade6-b1f4962a8c69', '58a6839b-922e-5e75-aa18-7e9e1cfae4d7', NULL, 17, 17, 'for the Lamb who is in the midst of the throne shepherds them, and leads them to springs of waters of life. And God will wipe away every tear from their eyes."'),
  ('cb861c9c-d2d6-524c-a809-6dcd5c01fe91', 'd75b4226-cc68-5ca0-a37c-4c3fbf665bea', NULL, 1, 1, 'When he opened the seventh seal, there was silence in heaven for about half an hour.'),
  ('bf3df26f-192e-52b0-af09-b4085fc74920', 'd75b4226-cc68-5ca0-a37c-4c3fbf665bea', NULL, 2, 2, 'I saw the seven angels who stand before God, and seven trumpets were given to them.'),
  ('0aefce53-f898-541a-ac65-d25aff598af4', 'd75b4226-cc68-5ca0-a37c-4c3fbf665bea', NULL, 3, 3, 'Another angel came and stood over the altar, having a golden censer. Much incense was given to him, that he should add it to the prayers of all the saints on the golden altar which was before the throne.'),
  ('921c1e92-aea0-5b1e-aa7b-2935dfcc8f32', 'd75b4226-cc68-5ca0-a37c-4c3fbf665bea', NULL, 4, 4, 'The smoke of the incense, with the prayers of the saints, went up before God out of the angel''s hand.'),
  ('be294e87-a35c-5f7b-a54f-69c1211b1081', 'd75b4226-cc68-5ca0-a37c-4c3fbf665bea', NULL, 5, 5, 'The angel took the censer, and he filled it with the fire of the altar, and threw it on the earth. There followed thunders, sounds, lightnings, and an earthquake.'),
  ('d4ccb331-39eb-57cf-ab6f-407ff0943af4', 'd75b4226-cc68-5ca0-a37c-4c3fbf665bea', NULL, 6, 6, 'The seven angels who had the seven trumpets prepared themselves to sound.'),
  ('5ae8be39-7c05-50c0-a3fe-060d26730b90', 'd75b4226-cc68-5ca0-a37c-4c3fbf665bea', NULL, 7, 7, 'The first sounded, and there followed hail and fire, mixed with blood, and they were thrown to the earth. One third of the earth was burnt up, and one third of the trees were burnt up, and all green grass was burnt up.'),
  ('b09af4cc-3a25-5c77-a78c-1c92356b37ea', 'd75b4226-cc68-5ca0-a37c-4c3fbf665bea', NULL, 8, 8, 'The second angel sounded, and something like a great burning mountain was thrown into the sea. One third of the sea became blood,'),
  ('8e8531d6-31a2-533d-af3a-f4bcfd7e9d57', 'd75b4226-cc68-5ca0-a37c-4c3fbf665bea', NULL, 9, 9, 'and one third of the living creatures which were in the sea died. One third of the ships were destroyed.'),
  ('db9d1132-a8a0-5f57-a196-6d2c6072f44e', 'd75b4226-cc68-5ca0-a37c-4c3fbf665bea', NULL, 10, 10, 'The third angel sounded, and a great star fell from the sky, burning like a torch, and it fell on one third of the rivers, and on the springs of the waters.'),
  ('0ff484f3-1696-554a-a56e-9c261135a612', 'd75b4226-cc68-5ca0-a37c-4c3fbf665bea', NULL, 11, 11, 'The name of the star is called "Wormwood." One third of the waters became wormwood. Many people died from the waters, because they were made bitter.'),
  ('2168cdb3-a726-5330-a22b-ad7265fd5c7d', 'd75b4226-cc68-5ca0-a37c-4c3fbf665bea', NULL, 12, 12, 'The fourth angel sounded, and one third of the sun was struck, and one third of the moon, and one third of the stars; so that one third of them would be darkened, and the day wouldn''t shine for one third of it, and the night in the same way.'),
  ('396d04cb-1d10-5c39-a62d-68f337c02445', 'd75b4226-cc68-5ca0-a37c-4c3fbf665bea', NULL, 13, 13, 'I saw, and I heard an eagle, flying in mid heaven, saying with a loud voice, "Woe! Woe! Woe for those who dwell on the earth, because of the other voices of the trumpets of the three angels, who are yet to sound!"'),
  ('4fdd1d16-690f-5b28-af63-f767a39ce50e', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 1, 1, 'The fifth angel sounded, and I saw a star from the sky which had fallen to the earth. The key to the pit of the abyss was given to him.'),
  ('2167c0da-2853-5e0f-a440-eaef5709fe0c', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 2, 2, 'He opened the pit of the abyss, and smoke went up out of the pit, like the smoke from a burning furnace. The sun and the air were darkened because of the smoke from the pit.'),
  ('6f157ad7-2e64-5bca-aa2e-b5977297ace6', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 3, 3, 'Then out of the smoke came forth locusts on the earth, and power was given to them, as the scorpions of the earth have power.'),
  ('04c0c879-81c2-57a7-a99a-4f05e7a629f0', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 4, 4, 'They were told that they should not hurt the grass of the earth, neither any green thing, neither any tree, but only those people who don''t have God''s seal on their foreheads.'),
  ('1037fc1d-1711-52d1-a1de-7a632ad94f1c', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 5, 5, 'They were given power not to kill them, but to torment them for five months. Their torment was like the torment of a scorpion, when it strikes a person.'),
  ('a7873b36-23c4-5717-a2cf-e91640e23fc7', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 6, 6, 'In those days people will seek death, and will in no way find it. They will desire to die, and death will flee from them.'),
  ('fbcd8130-8180-558d-a5ee-16479428210b', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 7, 7, 'The shapes of the locusts were like horses prepared for war. On their heads were something like golden crowns, and their faces were like people''s faces.'),
  ('c671ef0f-83a5-51c0-a459-d6898af8f8f2', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 8, 8, 'They had hair like women''s hair, and their teeth were like those of lions.'),
  ('3cf7ba1d-bcdc-50df-a6b1-333e126c458a', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 9, 9, 'They had breastplates, like breastplates of iron. The sound of their wings was like the sound of chariots, or of many horses rushing to war.'),
  ('8974bd56-45ba-5a59-a03a-3ee05d45e611', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 10, 10, 'They have tails like those of scorpions, and stings. In their tails they have power to harm men for five months.'),
  ('64e81c50-f94a-55f6-a4a2-cdeed7dadd57', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 11, 11, 'They have over them as king the angel of the abyss. His name in Hebrew is "Abaddon," but in Greek, he has the name "Apollyon."'),
  ('5bc86ccd-8350-5a9a-a954-f1613cfbad56', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 12, 12, 'The first woe is past. Behold, there are still two woes coming after this.'),
  ('4e1d3d04-ce6d-517a-a4a7-b0c58fd0018a', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 13, 13, 'The sixth angel sounded. I heard a voice from the horns of the golden altar which is before God,'),
  ('e74fd492-7036-589a-a857-16ad2c04701e', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 14, 14, 'saying to the sixth angel who had one trumpet, "Free the four angels who are bound at the great river Euphrates!"'),
  ('634bcebf-0916-5290-af63-a95c428f6e1c', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 15, 15, 'The four angels were freed who had been prepared for that hour and day and month and year, so that they might kill one third of mankind.'),
  ('e532e2eb-0a4c-550e-aebe-bab8176ed6a6', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 16, 16, 'The number of the armies of the horsemen was two hundred million. I heard the number of them.'),
  ('f9e8811e-c4da-5c55-a715-07fa63d7596f', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 17, 17, 'Thus I saw the horses in the vision, and those who sat on them, having breastplates of fiery red, hyacinth blue, and sulfur yellow; and the heads of lions. Out of their mouths proceed fire, smoke, and sulfur.'),
  ('91a9e302-9f75-5bab-a739-8bb3a8e04980', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 18, 18, 'By these three plagues were one third of mankind killed: by the fire, the smoke, and the sulfur, which proceeded out of their mouths.'),
  ('d9557381-752a-5321-a5ac-f7df428e4273', '80886165-817b-571e-aa7e-e55857b97ffa', NULL, 19, 19, 'For the power of the horses is in their mouths, and in their tails. For their tails are like serpents, and have heads, and with them they harm.')
